-- catalog.Artifacts
INSERT INTO [catalog].[Artifacts] ([Id], [ArtifactRef], [Name], [CategoryId], [EraBucketId], [EraTextOriginal], [CreatorDisplay], [Description], [SizeText], [PrimaryImagePath], [ThumbnailPath], [SourceUrl], [LicenseCode], [AttributionText], [IsActive]) VALUES
    ('1337d4fe-6447-84fd-4115-000b60825b05', N'中漆000061N000000000', N'剔紅番蓮紋瓶（五供）', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'觚形瓶，黃漆素地，上髹紅色漆。大撇口，長頸，圓腹，高圈足外撇。口內雕八方朵花錦地，口與足沿、腹上下各飾連續折線紋一周，器腹雕滿番蓮花葉紋，口足並以此對稱裝飾，刻多層蕉葉紋與番蓮花紋。足略有破損，露胎。五供乃香爐、瓶、燭臺成組，為供佛法器。', N'通高 27.0 公分、底深 2.5 公分、口徑 14.2 公分、足徑 10.9 公分', N'/media/catalog/lacquer/中漆000061N000000000/display.jpg', N'/media/catalog/lacquer/中漆000061N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17522?dep=U', N'CC-BY-4.0', N'剔紅番蓮紋瓶（五供） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b60d1d72-40ef-525d-9b3a-00a0222091a7', N'南購畫00001200000', N'東海道二 五十三次 品川', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪品川宿（現東京都品川區）風景，畫面由左而右標示「東海道二」、「五十三次 品川」、「廣重画」，畫面左下角副題「鮫洲の茶や」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001200000/display.jpg', N'/media/catalog/painting/南購畫00001200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36467?dep=P', N'CC-BY-4.0', N'東海道二 五十三次 品川 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e0e8fbc4-4d68-c1fd-4a61-0347c13d3fe6', N'故雕000147N000000000', N'癭木蕉葉盤 附果核五顆', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'癭木蕉葉盤，這類以具有特色而天然生成的枝幹、葉、果等為原型，製為文房中的陳設與用具，在明代晚期文人生活中甚受歡迎。癭木蕉葉盤節取癭木天然形狀，盤背兩側保留天然錯結的木質，中央莖脈處平磨，刻「蕉林珍玩」，並刻印二：「墨林」、「子京珍玩」。盤面丙戌年（乾隆三十一年，1766）高宗題識：「清供天籟閣中曾，既曰根云葉亦應，設擬鄭人夢駭鹿，植生猶覺近堪徵。」詩文內容談及此盤曾在項元汴（1525-1590）天籟閣的收藏，又由蕉葉聯想到《列子．周穆王篇》鄭國人覆蕉尋鹿的故事，因此高宗於盤底加刻「蕉緣」二字，望著桌案上陳設著一片如蕉葉狀的木癭，外緣卷起，再擱上果核五粒，外皮天然皴皺，瑩滑可愛。', N'長 27.1 公分、寬 8.6 公分、高 3.5 公分', N'/media/catalog/carving/故雕000147N000000000/display.jpg', N'/media/catalog/carving/故雕000147N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2470?dep=U', N'CC-BY-4.0', N'癭木蕉葉盤 附果核五顆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ab0fd8e3-04ed-c5b8-51be-040763090373', N'贈漆000006N000000000', N'褐漆葵花式盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', 'f2a78063-931b-9926-749c-324377d136c7', N'宋至元', NULL, N'盤，木胎，七瓣葵花式口，矮圈足，通身髹醬褐色漆，口緣包鑲一圈細窄銅邊，圈足內中央朱漆繪一橢圓印，印文漫渙不識。', N'高 2.7 公分、口徑 15.7 公分', N'/media/catalog/lacquer/贈漆000006N000000000/display.jpg', N'/media/catalog/lacquer/贈漆000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/103?dep=U', N'CC-BY-4.0', N'褐漆葵花式盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e42d52fe-d579-d929-94dd-045a8d469544', N'故瓷009276N000000000', N'有田窯 五彩花卉紋十二方盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'盤口部外敞，壁呈淺圓弧，圈足低矮。盤心繪一菱角形提籃及各色花卉之盆花紋，內壁有四開光，開光內繪湖石花木紋樣，開光外則飾折枝茶花。近口沿處一圈則以六朵紅金彩小花為界，穿插飾以青花菱格菊花紋及綠地渦卷花紋各三。器外壁有六朵紅花枝五彩纏枝花卉紋，口沿則飾波濤紋。足內以青花書「大明萬曆年製」楷書雙圈款，並有四個明顯支釘痕跡。', N'高 5.6 公分、口徑 29.5 公分、底徑 17.0 公分', N'/media/catalog/ceramic/故瓷009276N000000000/display.jpg', N'/media/catalog/ceramic/故瓷009276N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/33905?dep=U', N'CC-BY-4.0', N'有田窯 五彩花卉紋十二方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bb45e8ae-aff5-a3d3-f45c-04c7430c2358', N'購錢002101N000000000', N'元符通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'銅質，方孔圓錢，正面有行書：「元符通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢002101N000000000/display.jpg', N'/media/catalog/coin/購錢002101N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/11439?dep=U', N'CC-BY-4.0', N'元符通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4808dfa9-8de2-8d30-cf74-05f42b2850b7', N'中漆000039N000000000', N'剔紅番蓮紋十六瓣盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'圓盒，口有一圈十六瓣形寬邊，直壁，圓蓋，附金色葫蘆形鈕。蓋面及口沿寬邊的正面剔紅番蓮紋，口沿寬邊的背面淺款番蓮紋及繁密之錦紋，外壁剔雕六角形錦紋，六角形格內有花紋。內壁及底均髹黑漆。', N'連蓋高 8.0 公分、深 3.4 公分、口徑 9.0 公分、最大徑 14.9 公分', N'/media/catalog/lacquer/中漆000039N000000000/display.jpg', N'/media/catalog/lacquer/中漆000039N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17450?dep=U', N'CC-BY-4.0', N'剔紅番蓮紋十六瓣盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6c6944f5-09e8-2bf3-37e5-069f473c1c73', N'故玉000024N000000000', N'玉神人', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周中期', NULL, N'青白玉，受沁略呈灰色，神人有臣字眼，髮絲清晰，受玉料限制，有變形的鼻端以及收束如尖羽的身軀，此皆為西周中期神人常見的特徵。', N'直徑 3.8 公分、厚 0.6 公分', N'/media/catalog/jade/故玉000024N000000000/display.jpg', N'/media/catalog/jade/故玉000024N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48220?dep=U', N'CC-BY-4.0', N'玉神人 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1209e192-27f1-92ab-41fe-07552dbc2fe0', N'故畫00138200000', N'唐王維千岩萬壑　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐玄宗開元二十四年（736）', NULL, N'此長卷畫雲水飛動，山谷郁郁盤盤、江岸連綿千里，臺地、山澗、飛瀑流泉、崖亭水榭、長橋村落等各式景觀，俱現筆端。然通幅之山石樹木，相似造型往往重複出現；用筆雖工整，有提頓轉折之處，卻少變化，欠筆力，偏於平板，當是後人假託王維之作。王維（西元七○一—七六一年），字摩詰，山西祁縣人。以詩名盛於開元、天寶間，書畫特臻其妙。工草隸，尤工畫山水，筆墨宛麗，氣韻高清，畫中極富詩意。', N'31.5 × 705.9 公分', N'/media/catalog/painting/故畫00138200000/display.jpg', N'/media/catalog/painting/故畫00138200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14893?dep=P', N'CC-BY-4.0', N'唐王維千岩萬壑　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0d5ee27a-75e5-f401-d0e9-08080612147b', N'中琺000009N000000000', N'掐絲琺瑯靶碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'微撇口，深壁，雙層高圈足，微撇。全器內外均為淺藍地，以掐絲技法於器內壁飾法輪、法螺、寶傘、盤長與番蓮花紋，器外壁飾金魚、寶瓶、蓮花、白蓋與番蓮花紋，足頂飾深藍地如意雲紋，足底飾壽山福海。', N'高 9.2 公分、口徑 17.4 公分', N'/media/catalog/enamel/中琺000009N000000000/display.jpg', N'/media/catalog/enamel/中琺000009N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53886?dep=U', N'CC-BY-4.0', N'掐絲琺瑯靶碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6769c966-acf8-4027-29fc-081b56671622', N'中瓷005531N000000000', N'定窯 白瓷印花雙魚紋花口碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'六花口大碗，敞口，圓弧形深壁，矮圈足，口作六瓣花式，曲弧不明顯。全器施牙白色釉，僅口緣無釉，鑲銅棱釦。內壁有六道淺直棱，將內壁分為六等分，碗心飾印花雙魚紋。圈足滿釉，外壁上部輕劃兩圈弦紋。', N'高 7.0 公分、口徑 22.0 公分、底徑 6.2 公分', N'/media/catalog/ceramic/中瓷005531N000000000/display.jpg', N'/media/catalog/ceramic/中瓷005531N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23116?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花雙魚紋花口碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('efcf6c36-a8a9-769c-0b9f-0974a6ea59e9', N'贈雕000139N000000000', N'骨博棋', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'長方柱形，乃以骨切磨而成。器表打磨光滑，多處傷蝕，器呈深黃近褐色，局部呈淡綠色。贈雕000139-000144為六博棋子，精美者也可彩繪或雕刻紋飾，例如河北滿城西漢中山靖王夫婦墓中出土的六博棋子即是；本器則光素無紋。其實在漢墓中經常出土這類光素的六博棋子，例如西漢初期的南越王墓中出土的十八顆象牙棋子，即為光素者，其中出土於博局上的六顆棋子，表面則塗了朱彩。', N'長 2.3 公分、寬 1.2-1.4 公分、高 0.7-1.1 公分', N'/media/catalog/carving/贈雕000139N000000000/display.jpg', N'/media/catalog/carving/贈雕000139N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45368?dep=U', N'CC-BY-4.0', N'骨博棋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('66a4b9e5-f8ec-8c95-f261-09a06d50c770', N'贈雕000045N000000000', N'牙梳', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'商晚期至西周', NULL, N'器由一塊牙材磋磨而成，柄部中段內凹，利於執拿：十六根梳齒，兩端乃梳背之延伸。全器磋磨工藝樸拙。商代晚期開始，梳篦雖然仍多作長方形，但梳柄已開始變化，出現不規整的方形，在山西寶雞築圍溝西周墓中即曾出土梳柄中腰凹縮的長方型梳篦。', N'長 7.6 公分、寬 4.8 公分、厚 0.4 公分', N'/media/catalog/carving/贈雕000045N000000000/display.jpg', N'/media/catalog/carving/贈雕000045N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45271?dep=U', N'CC-BY-4.0', N'牙梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('22f9c038-5c05-30ef-c38a-0a7b81dfd934', N'故玉002235N000000000', N'玉柄形器（後代改製）', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'玉質，色赭紅密潤。器似小瓶但只有其半，器身上琢二弦紋，背面有單面穿口痕跡之凹槽，為商代玉柄形器改製而成。', N'全高 4.1 公分、寬 1.9 公分、厚 0.9 公分', N'/media/catalog/jade/故玉002235N000000000/display.jpg', N'/media/catalog/jade/故玉002235N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50369?dep=U', N'CC-BY-4.0', N'玉柄形器（後代改製） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b5af59ed-c975-dfe8-ccb3-0a89400d51ca', N'中銅000287N000000000', N'「承安三年」鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'圓鏡，圓鈕。內區飾瑞獸，銘文帶二十六字。', N'直徑 8.8 公分', N'/media/catalog/bronze/中銅000287N000000000/display.jpg', N'/media/catalog/bronze/中銅000287N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7097?dep=U', N'CC-BY-4.0', N'「承安三年」鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5de1f697-5d9f-d42f-38ea-0afe802f6f5e', N'中琺000002N000000000', N'掐絲琺瑯鳳身瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅胎。撇口，長頸，鍍金雙鳳啣如意雲紋菱形環耳，斜肩，斂腹，鍍金圈足外撇、下接三辟邪足，肩部飾十個鍍金鳳啣如意雲紋菱形環裝飾。以掐絲技法、琺瑯料填色製作花紋，頸部有蕉葉形開光，內飾淺藍地百合、茶花、菊，下接番蓮紋，開光隙地飾深藍地菊紋，肩飾百合、葡萄，腹飾夔龍紋、朵雲錦地獅紋，隙地飾各式雜寶，圈足外飾纏枝番蓮紋，內飾朵雲紋，外底飾纏枝菊花紋。', N'高 39.2 公分、深 33.5 公分、口徑 16.5 公分', N'/media/catalog/enamel/中琺000002N000000000/display.jpg', N'/media/catalog/enamel/中琺000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53879?dep=U', N'CC-BY-4.0', N'掐絲琺瑯鳳身瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c86c31f2-568e-f393-3fc2-0bfcb67efe9c', N'南購畫00002600000', N'東海道十六 五十三次 蒲原', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪蒲原宿（靜岡縣靜岡市清水區）風景，畫面由右而左標示「東海道十六」、「五十三次 蒲原」、「廣重画」，畫面右下副題「冨士川渡舟」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002600000/display.jpg', N'/media/catalog/painting/南購畫00002600000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36481?dep=P', N'CC-BY-4.0', N'東海道十六 五十三次 蒲原 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9b25c16b-753f-15a2-55a5-0c75b6aa68a4', N'贈錢001481N000000000', N'「大泉五十」錢幣', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'銅製，圓形中央有方孔，一面鑄有「大泉五十」，一面有類似花卉、星辰等紋飾之幾何紋。', N'徑 1.8 公分', N'/media/catalog/coin/贈錢001481N000000000/display.jpg', N'/media/catalog/coin/贈錢001481N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9323?dep=U', N'CC-BY-4.0', N'「大泉五十」錢幣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d0fff680-5c00-7d96-16e2-0c8dc375f712', N'中日陶000039N000000000', N'灰陶甑', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'上為折唇，圓口，平底有孔。全器平素。下為釜形。', N'高 4.8 公分、口徑 10.1 公分、底徑 3.4 公分', N'/media/catalog/ceramic/中日陶000039N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000039N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71774?dep=U', N'CC-BY-4.0', N'灰陶甑 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('17b9a637-a706-4629-eba5-0cfdc61d8163', N'故畫00068500000', N'清王時敏倣王蒙山水　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙六年（1667）', NULL, N'王時敏，江蘇太倉人，（西元一五九二－一六八０年）字遜之，號煙客，自稱西廬老人、西田主人、偶諧道人、歸村老農。性資穎異，淹雅博物，畫為清四大家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'此幅仿王蒙筆，層山疊翠，一澗中分。幅右下叢樹中置一草堂，高士揮扇對庭前舞鶴。皴山石以渴筆牛毛皴，下筆穩健，用墨由淡入深，層層皴染，通幅筆墨綿密而精工，學王蒙甚得其穩重蒼鬱之趣，畫成於康熙丁未（一六六七年），時年七十五。', N'170 × 69.6 公分', N'/media/catalog/painting/故畫00068500000/display.jpg', N'/media/catalog/painting/故畫00068500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3463?dep=P', N'CC-BY-4.0', N'清王時敏倣王蒙山水　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7c223e29-349d-d3cf-842a-0e4d74641aee', N'贈雕000175N000000000', N'牙雕刀式佩', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'器下半部成刀形，上端鈍尖，剖面成圓形，末端有一穿孔可供懸佩。器身飾圈點紋，並陰刻弦紋與斜線紋。全器已染成綠色。唐代服飾受到胡服影響，腰間革帶上佩飾所謂「蹀躞七事」，包括刀子、礪石、算袋、手巾等等。唐末五代，這七事成為佩飾。此件刀是珮，或即由腰間佩刀蛻化而成。', N'長 8.0 公分、最寬 0.8 公分', N'/media/catalog/carving/贈雕000175N000000000/display.jpg', N'/media/catalog/carving/贈雕000175N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45403?dep=U', N'CC-BY-4.0', N'牙雕刀式佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6d134b2e-432b-eef2-b717-0e7774bebada', N'購錢000979N000000000', N'嘉祐通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「嘉祐通寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000979N000000000/display.jpg', N'/media/catalog/coin/購錢000979N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10317?dep=U', N'CC-BY-4.0', N'嘉祐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('542d088c-a3bb-11cd-db40-106d3d71ccfa', N'故畫00040000000', N'明邊文進花鳥　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明宣宗宣德二年（1427）', NULL, N'邊文進（活動於西元一四０三－一四二八年），名景昭，以字行。福建沙縣人，祖籍甘肅隴西。明初花鳥院畫家中以邊氏最為有名，畫翎毛花果皆極精妙。永樂朝任職於工部文思院，直謹身殿待詔；宣德間被授予武英殿待詔官銜。其花鳥畫曾被譽為「禁中三絕」之一。　「花鳥」成於宣德二年（一四二七），為其工筆寫生之佳作。此圖繪竹、梅、雀，經營位置錯落有致，鳥之姿態生動富情趣；用筆學宋朝院體勾勒填彩，設色妍麗生動。以梅竹、百雀為主題，象徵吉祥瑞應。', N'160.1 × 74.2 公分', N'/media/catalog/painting/故畫00040000000/display.jpg', N'/media/catalog/painting/故畫00040000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3199?dep=P', N'CC-BY-4.0', N'明邊文進花鳥　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d45e3de5-8cb5-e045-7302-10dfe36bef67', N'中日陶000056N000000000', N'灰陶案', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'原器已殘，今已修補。案面不平整，一端略為上揚，作長方形，邊緣有凸稜，作為邊框。案面四角各有一圓孔，以陰線刻連成方框，中央刻繪魚紋乙尾，外亦有方框。遼陽出土。', N'長 37.0 公分、寬 27.0 公分、高 1.6 公分', N'/media/catalog/ceramic/中日陶000056N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000056N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71766?dep=U', N'CC-BY-4.0', N'灰陶案 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('36173404-8d61-8ac6-bf33-1135bfcd450d', N'贈銅000323N000000000', N'銅鎏金誕生佛立像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本 江戶時代 或以後', NULL, N'銅鎏金立佛，日本江戶時代作品。笑容可掬，上身赤裸，右手上舉，左手自然垂放於腰間，並以食指指地。腰間繫布裙，立於覆蓮葉座之上。正合於佛誕生之時，步步蓮花，七步之時，一手指天，一手指地云：「天上地下，唯我獨尊」的傳說，所以本尊佛為「誕生佛」。佛像的上半身肥碩光素。布裙向下漸漸開展，以細陰線刻劃、繪寫衣帶及衣物皺折，樣式簡單，與上半身相呼應。附木蓮座。', N'通高 16.5 公分、像高 12.8 公分', N'/media/catalog/bronze/贈銅000323N000000000/display.jpg', N'/media/catalog/bronze/贈銅000323N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24720?dep=U', N'CC-BY-4.0', N'銅鎏金誕生佛立像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('942258bc-ce0f-76ca-75d1-11797977d273', N'中雕000003N000000000', N'犀角雕人物乘槎', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'一仙人坐於船上，展書閱讀，四周以老樹殘枝花卉為背景，有月季、菊花、茶花、楓葉等，樹幹懸掛葫蘆一個，槎前方雕飾樹枝，底部有水波紋。整體依犀角原有形狀加以修潤雕刻，器形渾然天成。附波濤紋木座一只。', N'長 28.4 公分', N'/media/catalog/carving/中雕000003N000000000/display.jpg', N'/media/catalog/carving/中雕000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54938?dep=U', N'CC-BY-4.0', N'犀角雕人物乘槎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('432ef746-9d59-d7cd-a1c8-11a9fa8a6737', N'故畫00195300000', N'元管道昇竹溪攬勝　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大二年（1309）', NULL, N'管道昇（西元一二六二－一三一九年），吳興人。字仲姬，趙孟頫妻。延祐四年（西元一三一七年）封魏國夫人。翰墨辭章不學而能，篤信佛法，書牘行楷與乃夫趙孟頫幾不可辨異同，為我國書畫史上著名女性作家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'本幅舊傳為管氏所作，畫山巒起伏，緣溪瓦屋數椽，叢竹錯落其間，溪邊泊舟，橋上行人，以水墨細緻之筆調，寫寧靜之村景，真得小橋、流水、人家之詩意。', N'57.2 × 27.5 公分', N'/media/catalog/painting/故畫00195300000/display.jpg', N'/media/catalog/painting/故畫00195300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/733?dep=P', N'CC-BY-4.0', N'元管道昇竹溪攬勝　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a2e8fb7c-47d6-776b-2429-11f936b4ae67', N'購錢005138N000000000', N'寬永通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本 江戶時代', NULL, N'銅質。方孔圓錢，正面有楷書：「寬永通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢005138N000000000/display.jpg', N'/media/catalog/coin/購錢005138N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14476?dep=U', N'CC-BY-4.0', N'寬永通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f7a244b6-b5ac-7f2d-843d-13236c75e3af', N'中銅000001N000000000', N'弦紋鼎', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'圓鼎，子母口，立耳，深腹，三蹄足。腹飾弦紋一道。', N'高 20.0 公分', N'/media/catalog/bronze/中銅000001N000000000/display.jpg', N'/media/catalog/bronze/中銅000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5612?dep=U', N'CC-BY-4.0', N'弦紋鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e7c92ab8-e129-a754-2d40-135cf950ab2a', N'中銅000013N000000000', N'雷紋簋', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'ca8136fd-d414-902c-3f23-189593397b2d', N'商晚期至西周早期', NULL, N'侈口、雙耳、圓腹、圈足，耳作獸首形，附珥。頸飾雲雷紋，中央有小獸首，下上連珠紋一道，足飾雲雷紋，下上飾連珠紋一道。', N'高 16.1 公分', N'/media/catalog/bronze/中銅000013N000000000/display.jpg', N'/media/catalog/bronze/中銅000013N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5888?dep=U', N'CC-BY-4.0', N'雷紋簋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2a689efb-861d-4660-deef-13a8073ad058', N'贈雕000186N000000000', N'牙簪', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'f2a78063-931b-9926-749c-324377d136c7', N'宋至元', NULL, N'細長條形，剖面呈圓形，一端成鈍尖針形，另一端中腰細縮，後段呈長橢圓形，末端鈍尖。此器依稀可見紅彩遺痕，原或曾施紅彩，今則通體呈褐色。', N'長 10.1 公分', N'/media/catalog/carving/贈雕000186N000000000/display.jpg', N'/media/catalog/carving/贈雕000186N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45414?dep=U', N'CC-BY-4.0', N'牙簪 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b74c1f3a-e5a9-421d-0e31-141942b1fbac', N'贈雕000135N000000000', N'骨雕填彩雲龍紋管', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'此器由兩塊骨材製成，一塊中腰凸弧，左右各穿一小孔，陰刻填彩雲紋內密刻垂鱗紋；另一塊製成管形，器表陰刻填彩龍紋，龍身密飾垂鱗紋。填彩已褪色，依稀可辨為紅彩。全器皆呈淡綠色。在漢代畫像磚上可一再發現與此器器表所飾龍紋相似的龍紋。', N'高 3.4 公分', N'/media/catalog/carving/贈雕000135N000000000/display.jpg', N'/media/catalog/carving/贈雕000135N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45364?dep=U', N'CC-BY-4.0', N'骨雕填彩雲龍紋管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('51141356-6481-c950-1149-14abf626ffd4', N'故琺000623N000000000', N'掐絲琺瑯三羊尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，侈口，削肩，球腹，高而外撇的圈足，肩周圍鑲三鍍金羊首。器內露胎，器表淺藍地，頸飾對龍對鳳，肩佈雲紋錦飾轉枝花及梅花，腹部雲紋錦間飾松竹梅歲寒三友、湖石及山雀兩對，圈足裝飾拐子龍。底鑄去地陽文「大明景泰年製」長方框楷書偽款。根據豆青綠釉及紋飾風格，應屬十七世紀初期的文物。', N'腹寬 23.0 公分、高 39.5 公分', N'/media/catalog/enamel/故琺000623N000000000/display.jpg', N'/media/catalog/enamel/故琺000623N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1531?dep=U', N'CC-BY-4.0', N'掐絲琺瑯三羊尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('51596fe9-4b7d-2a20-6c60-15427246768c', N'中銅000290N000000000', N'「至元四年」鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'圓鏡，圓鈕。鈕外有銘四字，鏡背飾雙龍戲珠紋。', N'直徑 22.8 公分', N'/media/catalog/bronze/中銅000290N000000000/display.jpg', N'/media/catalog/bronze/中銅000290N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2737?dep=U', N'CC-BY-4.0', N'「至元四年」鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0f0d5ebc-8db5-c824-7bd1-156db93f12d4', N'購錢000249N000000000', N'至道元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有行書：「至道元寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000249N000000000/display.jpg', N'/media/catalog/coin/購錢000249N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9587?dep=U', N'CC-BY-4.0', N'至道元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0117824f-523d-a14b-f7ae-16eb140772c0', N'中玉000011N000000000', N'玉獸面觚形瓶', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'青白玉觚形瓶。方形，外壁分三截仿銅觚造形，上下兩段以陰刻線飾蕉葉紋及回紋，中段為淺浮雕獸面紋。', N'通高 7.8 公分、口徑長 2.8 公分、寬 2.5 公分、底徑長 2.3 公分、寬 1.9 公分', N'/media/catalog/jade/中玉000011N000000000/display.jpg', N'/media/catalog/jade/中玉000011N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52750?dep=U', N'CC-BY-4.0', N'玉獸面觚形瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c5fb6ef1-8654-0364-848d-17e8d4924a09', N'贈雕000061N000000000', N'骨雕魚形璜', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'扁平弧形，兩端尖，中段較寬，雕成一尾魚形；魚首端陰刻兩道弦紋，兩面陰刻圈點紋，鼻部前伸，唇部凹陷，魚身中段留出一光素三角形，餘陰刻四組方向相反的斜弦紋，器身滿塗褐色塗料，尾端染成淡綠色。', N'長 11.4 公分、寬 0.9 公分、厚 0.3 公分', N'/media/catalog/carving/贈雕000061N000000000/display.jpg', N'/media/catalog/carving/贈雕000061N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45287?dep=U', N'CC-BY-4.0', N'骨雕魚形璜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('399409a4-ac81-2604-f4ce-18258fee5dc2', N'贈雕000030N000000000', N'象牙雕鳥首笄', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'商晚期至西周', NULL, N'器用一整塊象牙雕製而成；笄首雕一高冠側面鳥立於王字臺座上，鑿一小凹槽作眼紋，翼部陰刻雙圈一點之圈點紋，尾上翹，近尾部亦鑿一小凹槽，凡凹槽內原或有綠松石等嵌件，今已佚，有三處凹槽填塞土質；喙突勾；笄身剖面呈橢圓形，尾端圓鈍。全器多處沾黏沙土，但仍露出象牙黃色。在商後期的殷墟，尤其是武丁之後的墓葬曾一再出現類似器用，婦好墓中即不見這類型笄。此外，在陜西長安澧西張家坡西周居址遺址中也曾出土這類鳥首笄，但絕大多數為骨製者。所以這類高座鳥首笄應在婦好墓主人入葬之後才出現，一直流行至西周。', N'長 24.2 公分', N'/media/catalog/carving/贈雕000030N000000000/display.jpg', N'/media/catalog/carving/贈雕000030N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45256?dep=U', N'CC-BY-4.0', N'象牙雕鳥首笄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d9c779af-8b82-ce37-118c-1864a66f88c7', N'故銅000068N000000000', N'柳毅傳書故事鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'圓形鏡，半球鈕。鏡背鏡緣寬素，內有一道細弦紋。浮雕紋飾為一男子坐於岸邊樹下，下方有一持物童子，仙女及其侍者乘浪而來。一般認為此類主題紋飾來自唐代傳奇《柳毅傳》，描述龍女向柳毅訴苦受虐的場景。這一主題於金代銅鏡上頗為流行，曾出土於黑龍江。 與本鏡相同的一面鏡子錄於《西清續鑑．甲編》，但未見於本院所藏〈西清續鑑〉鏡匣銅鏡中，或許在編收〈寧壽續鑑〉鏡匣銅鏡時，將之改列其中。', N'直徑 18.2 公分、邊厚 0.3 公分', N'/media/catalog/bronze/故銅000068N000000000/display.jpg', N'/media/catalog/bronze/故銅000068N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5479?dep=U', N'CC-BY-4.0', N'柳毅傳書故事鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c97b570e-6aa6-5596-633e-18beb67acf05', N'中漆000038N000000000', N'剔紅羲之換鵝圖筆筒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'水邊屋舍內，二老者一邊讀書一邊交談，屋外童子一人捧盤傾身看著捉鵝跨橋而來的人。屋前樹木茂盛，岸邊老樹盤蔭，鵝群戲水，漆層層次變化多，水波、地面錦地滿鋪，物象安排緊湊，又以羲之換鵝為題材，是乾隆時期典型的雕漆風格。', N'高 13.7 公分、口徑 11.2 公分', N'/media/catalog/lacquer/中漆000038N000000000/display.jpg', N'/media/catalog/lacquer/中漆000038N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2680?dep=U', N'CC-BY-4.0', N'剔紅羲之換鵝圖筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b9532ce1-5657-620c-028a-18dcc496e610', N'中銅000009N000000000', N'鑾鈴', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周晚期', NULL, N'鑾，包括鈴、頸、座三部分，附方木座。鈴為橢圓狀，內有銅丸，面為三角鏤空，周邊飾鏤空寬帶。頸為連接鈴與座。座為上大下小方銎座。銎座上有孔，飾幾何紋。', N'高 16.9 公分', N'/media/catalog/bronze/中銅000009N000000000/display.jpg', N'/media/catalog/bronze/中銅000009N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6507?dep=U', N'CC-BY-4.0', N'鑾鈴 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('09dd01ff-ec09-8c60-e351-19350e3c3b28', N'中銅000198N000000000', N'花鳥紋菱花鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'圓鏡，作八尖瓣菱花形、圓鈕。鏡背飾花卉與鳥紋。', N'直徑 19.3 公分', N'/media/catalog/bronze/中銅000198N000000000/display.jpg', N'/media/catalog/bronze/中銅000198N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7068?dep=U', N'CC-BY-4.0', N'花鳥紋菱花鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e3bb128b-ef49-8126-d172-19739c7865a7', N'中琺000019N000000000', N'掐絲琺瑯瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'直口，長直頸，斜肩，圓腹，圈足。全器藍地，以掐絲技法於頸飾蕉葉紋，腹飾番蓮紋，足飾海棠紋。附圓形銅鏟一，銅箸一雙。', N'高 17.0 公分', N'/media/catalog/enamel/中琺000019N000000000/display.jpg', N'/media/catalog/enamel/中琺000019N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53896?dep=U', N'CC-BY-4.0', N'掐絲琺瑯瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b3f25245-2f5e-5b78-3b3c-1a35a4870324', N'故畫00050300000', N'明文徵明古木寒泉　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖二十八年（1549）', NULL, N'文徵明（西元一四七０－一五五九年），江蘇長洲（今江蘇蘇州）人。初名壁，字徵明，後以字行。亦字徵仲，號停雲生、衡山居士。詩文書畫並佳，畫師沈周，為明四大家之一。 柏樹老幹紛披，枒杈四出；松樹參雲直上，兩幹並伸。背景更添石壁，濃密緊迫，幾無餘地，忽於絕高處畫飛泉一道，遂使通幅於緊迫之中，遽爾空靈。此幅成於嘉靖二十八年（一五四九），文氏時年八十。', N'194.1 × 59.3 公分', N'/media/catalog/painting/故畫00050300000/display.jpg', N'/media/catalog/painting/故畫00050300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3302?dep=P', N'CC-BY-4.0', N'明文徵明古木寒泉　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ed205d0a-20f7-0a68-6997-1a3fab3a66ad', N'故畫00041800000', N'明杜瓊師林圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明憲宗成化四年（1468）', NULL, N'杜瓊（一三九六－一四七四）字用嘉，號鹿冠道人，世稱東原先生，籍里蘇州。明經博學，旁及翰墨書畫。山水宗董源，亦工人物。著有東原集，耕餘雜錄。　　本圖為杜氏追摹徐賁獅子林圖之畫趣者，原圖分十二段，本幅則綜合為小軸。描繪幾間房舍，其中一處為佛堂，庭院平坦清淨，惟有幾株林木。頗具倪瓚清曠雅逸之風味。屋後小徑，通往山中小屋，為全幅增綴了深遠一層的畫境，也使園林添加曲折起伏之變化。', N'88.8 × 27.9 公分', N'/media/catalog/painting/故畫00041800000/display.jpg', N'/media/catalog/painting/故畫00041800000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3217?dep=P', N'CC-BY-4.0', N'明杜瓊師林圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4eead432-e800-f796-35de-1afd84d2d328', N'贈雕000199N000000000', N'象牙笏', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'長弧形象牙板。古時自天子至士皆執笏，《禮記 玉藻》：「笏，天子以球玉，諸侯以象，大夫以魚須文竹，士竹，本象可也。」此篇中說明：凡指畫於君前用笏，造受命於君前書於笏。又，《麈史》記載笏制：「初短而厚，俄而長闊，皇祐間極大而差薄，其勢向身微曲，調之抱身，後復用直而中者。」唐代的笏短而厚，例如唐代章懷太子李賢墓中壁畫的武弁像、敦煌一三0窟壁畫樂廷懷像、西安石刻「凌煙閣功臣圖」等人物手中執笏，可見一斑。宋代笏有曲有直，但以直為多，例如院藏「宋人折檻圖」中人物即執直笏。明代笏多成弧曲，此件擬定為明代物。', N'長 45.0 公分、最寬 5.7 公分', N'/media/catalog/carving/贈雕000199N000000000/display.jpg', N'/media/catalog/carving/贈雕000199N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45427?dep=U', N'CC-BY-4.0', N'象牙笏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('625ebb2b-f11b-f9cb-7e58-1b1ab97f3561', N'故畫00025500000', N'元郭畀寫高使君意　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元順帝至元五年（1339）', NULL, N'郭畀（一二八○—一三三五）字天鍚，號雲山，江蘇丹徒人，官至江浙行省辟充掾史。工書畫，書法出入趙孟頫，山水師法米芾，又善竹木窠石。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'此圖寫溪畔坡石高松，遠山寺宇，雲烟繚繞。山石用淡墨大筆渲染，加濃墨橫點提醒，雲烟鈎繪輪廓，這些都是從米家雲山變化來的。紀年己卯為至元五年（一三三九），時郭畀已歿，故應為後人的仿作。', N'81.5 × 30.6 公分', N'/media/catalog/painting/故畫00025500000/display.jpg', N'/media/catalog/painting/故畫00025500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/694?dep=P', N'CC-BY-4.0', N'元郭畀寫高使君意　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d12fe9cc-4270-7896-8250-1b243be5a27b', N'故玉000014N000000000', N'玉琮形佩', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'玉質，淺赭色，琮形而小，或作佩飾器。', N'長 2.2 公分、寬 2.2 公分、通高 1.7 公分', N'/media/catalog/jade/故玉000014N000000000/display.jpg', N'/media/catalog/jade/故玉000014N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48212?dep=U', N'CC-BY-4.0', N'玉琮形佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3335a65b-60ff-7767-4317-1b44acf548cd', N'贈雕000198N000000000', N'牙柄形器', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'長管形中有一孔貫穿，乃兩面對穿而成，較細的一端孔呈圓形，另一端呈三角形。呈圓形者之內壁仍遺留當時鏇孔時之寬弦紋；呈三角形者可看出當時鑽孔時先從三角點鑽入，再修磨出孔壁。近較細的一端兩側各穿一孔，可供固定中孔內物質，外壁中段有四道寬凹痕，其近較細之ㄧ端陰刻六道細弦紋為飾，另一端飾五道較寬弦紋。此器之中孔可供插入一物，再藉壁面之兩個成直線的小孔固定之。手握之，外壁中段之凹痕可供執握，可能為器柄類物。', N'長 10.1 公分、徑 1.7-2.0 公分', N'/media/catalog/carving/贈雕000198N000000000/display.jpg', N'/media/catalog/carving/贈雕000198N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45426?dep=U', N'CC-BY-4.0', N'牙柄形器 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6f297ec7-72a9-b0fe-4bb2-1c3763e8f40d', N'故畫00068600000', N'清羅牧林壑蕭疎圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙四十三年（1704）', NULL, N'羅牧（西元一六二二－一七○四年尚在），江西寧都人，字飯牛，僑居南昌。能詩善飲，又善製茶，工書畫山水。水淮間亦有祖之者，世所稱江西派是也。' + NCHAR(13) + NCHAR(10) + N'　　本幅用生紙濕筆，寫江邊小景，筆生辣而直勁，為八十三歲時作。', N'195.1 × 75.4 公分', N'/media/catalog/painting/故畫00068600000/display.jpg', N'/media/catalog/painting/故畫00068600000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3464?dep=P', N'CC-BY-4.0', N'清羅牧林壑蕭疎圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('07609c89-0c5b-739e-6ba6-1d3bd2913d22', N'購錢000413N000000000', N'太平通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有隸書：「太平通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000413N000000000/display.jpg', N'/media/catalog/coin/購錢000413N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9751?dep=U', N'CC-BY-4.0', N'太平通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d3e831c4-76ca-c070-ebeb-1d55b845ab10', N'購瓷000089N000000000', N'陶珠', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'灰白陶胎珠粒，中心穿孔，外壁有藍、白突起圓點狀燒結紋飾。浙江無錫鴻山戰國越墓層曾出土類似灰白泥質陶胎，施點狀彩飾物件。', N'高 1.0 公分、外徑 1.4 公分、孔徑 0.5-0.6 公分', N'/media/catalog/ceramic/購瓷000089N000000000/display.jpg', N'/media/catalog/ceramic/購瓷000089N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/42970?dep=U', N'CC-BY-4.0', N'陶珠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7ce32ab4-47fe-cf45-1163-1d816ba8af4c', N'中瓷002224N000000000', N'官窯 青瓷葵口碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'花口碗，口緣銅釦，深弧壁下斂，圈足。器內外壁施青釉，釉透而泛翠青，並滿布開片。足緣露胎一圈，塗褐色汁，足內滿釉無款識。', N'高 8.7 公分、口徑 20.5 公分、底徑 2.3 公分', N'/media/catalog/ceramic/中瓷002224N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002224N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23704?dep=U', N'CC-BY-4.0', N'官窯 青瓷葵口碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9e6f4c50-c41f-3a3c-1c7c-1ef4fe65dcbc', N'贈雕000069N000000000', N'牙骨串飾', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國至漢', NULL, N'全串由二十六粒管珠、十五粒扁圓珠(其中三粒陰刻圈點紋)、一粒鼓形珠、一粒弦紋管珠、數十件片狀珠及一砲彈頭形墜角和一粒松綠石組成。砲彈頭形墜角末端呈錐形，上接一陰刻圈點紋之扁圓珠，再接一段短圓柱，最上一節即為砲彈頭形，其上陰刻三組雙層弦紋，及五個圈點紋。扁圓珠之圈點紋內有紅彩遺痕，墜角之圈點紋內填紅彩與藍彩。上古先民常以牙、骨管珠等串成項飾或鐲飾，以供佩掛裝飾。這串牙骨串飾乃重新串組而成。', N'墜角長 4.1 公分', N'/media/catalog/carving/贈雕000069N000000000/display.jpg', N'/media/catalog/carving/贈雕000069N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45295?dep=U', N'CC-BY-4.0', N'牙骨串飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8e6fbe63-2ee5-200d-88ff-1f1865d46aae', N'故畫00070000000', N'清王武倣元人溪亭對菊圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙六年（1667）', NULL, N'作者王武，生在明思宗崇禎五（公元一六三二）年，死在清康熙二十九（公元一六九０）年，長洲（今江蘇吳縣）人。字勤中，號忘菴，又自稱雪顛道人。精熟於繪畫外，家中收藏古書畫甚富，因此又精通鑑賞，平素對於古人名蹟且能心摹手追，所以畫法不凡，脫盡匠氣，名高當代。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'他的畫中，以花鳥畫最擅長，聲望幾與惲壽平相等，山水畫卻極少，但是，偶一為之，也是格調不俗。', N'167.8 × 45.2 公分', N'/media/catalog/painting/故畫00070000000/display.jpg', N'/media/catalog/painting/故畫00070000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3478?dep=P', N'CC-BY-4.0', N'清王武倣元人溪亭對菊圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9283caca-1061-fbdd-bc3b-1fb0ba1e0cee', N'故玉002180N000000000', N'蟠虺紋玦', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋早期', NULL, N'玉質，暗褐色、褐色交錯分布。圓整帶缺，缺的對端按下削薄，缺口切割齊整，中孔、外緣均磨飾平整光滑。兩面飾以蟠虺紋，然花紋略有不同；作兩獸首側面相向，獸眼一作橢圓形，一作圓形眼，花紋的刻飾保留西周時代流行的大斜刀技法。此器若依其形制、花紋以及刻飾手法觀之，與河南光山寶相寺黃君孟夫婦墓所出之玦近似。', N'徑 5.77 公分、孔徑 2.29 公分、厚 0.4 公分、缺寬 0.29 公分', N'/media/catalog/jade/故玉002180N000000000/display.jpg', N'/media/catalog/jade/故玉002180N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2558?dep=U', N'CC-BY-4.0', N'蟠虺紋玦 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7320b555-2004-84c5-51a5-20619b5c792c', N'故琺000718N000000000', N'掐絲琺瑯方口瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯，長方形，侈口，長頸，雙魚形耳，斜肩，方腹，外撇圈足。器身正面外緣有一圈卷草紋邊飾，四面皆為番蓮花圖紋，正反面腹部有一壽字，圈足四面皆有卷草紋邊飾及番蓮花紋。口緣及圈足下原有回紋浮雕。底部露胎，鑄去地陽文「大明景泰年製」三行楷書款。', N'高 38.3 公分', N'/media/catalog/enamel/故琺000718N000000000/display.jpg', N'/media/catalog/enamel/故琺000718N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61758?dep=U', N'CC-BY-4.0', N'掐絲琺瑯方口瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('74176e6d-1c21-3fe6-d468-20efcac0b98e', N'故漆000028N000000000', N'剔紅菊花圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，子母口，圈足，底部及盒內髹褐漆。盒側作轉枝花卉，波浪狀枝葉，茶花、牡丹、荷花、梔子花，兩兩成組，花朵一上一下，葉間夾雜著花苞，是永樂時期以來常見的樣式。盒面刻折枝菊花，主幹從左下緣向右延伸，穿過圓心，其間向左右分枝，盒面安排五花，中心一，外圈四，佈局平均，葉片的分佈以左右成組的方式由下自上方排列，在上方花朵旁的花苞處結束，構圖具平和的韻律感。全開圓形的花，五花心五種組合，葉片平鋪，枝葉略為翻折或重疊，具平面化的趣味，物象間微露黃漆地，花葉造型節制而分明。漆質紅潤，漆質堅實，漆層側面近底層處有一黑線，刀法熟純，瓣脈、葉脈盒面刻線流暢，漆面凹凸起伏微婉，花瓣邊緣翹起，整體感細膩優雅。', N'高 7.4 公分、徑 22.0 公分、足徑 20.7 公分', N'/media/catalog/lacquer/故漆000028N000000000/display.jpg', N'/media/catalog/lacquer/故漆000028N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18153?dep=U', N'CC-BY-4.0', N'剔紅菊花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4fb46e8b-367e-67c4-a8c2-21f542798180', N'購銅000131N000000000', N'青銅鎏金菩薩半跏像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'鍍金色殘褪，缺背光，蓮花座下中空，可能另接一座。頂有化佛，左手似持淨瓶，瓶頸斷，右手置膝上，第二、三指前伸，作與願印，應為觀音菩薩。髮梳高髻，坐於複瓣仰蓮台座上，瓣間露出蓮蕊的直紋理，下承几形圓座，上身短，坐姿略挺直，冠帶沿肩而下，問飾結，和山西大同華嚴寺薄迦教藏殿遼重熙七年（1038）菩薩坐像，當有前後一脈相承的關係。', N'高 11.7 公分', N'/media/catalog/bronze/購銅000131N000000000/display.jpg', N'/media/catalog/bronze/購銅000131N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2609?dep=U', N'CC-BY-4.0', N'青銅鎏金菩薩半跏像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a9940794-e31c-6bc8-88ed-2261fd087123', N'贈玉000474N000000000', N'石圭璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'石質，有赭沁色及赭斑點。全器呈圓璧形，兩端有凸起，乃為圭與璧結合之形狀。外壁無紋。', N'長 20.4 公分、璧徑 13.8 公分、孔徑 2.0 公分、厚 1.9 公分', N'/media/catalog/jade/贈玉000474N000000000/display.jpg', N'/media/catalog/jade/贈玉000474N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53639?dep=U', N'CC-BY-4.0', N'石圭璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f42fafd5-a416-a8b5-d049-235eca46570a', N'故玉001086N000000000', N'玉珌', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'白玉，有深赭斑。雙面同紋，器面及底均琢陰刻幾何紋。器頂有圓形深槽，用以固定，將玉飾嵌於劍鞘底。', N'長 5.6 公分、寬 2.15 公分、高 2.2 公分', N'/media/catalog/jade/故玉001086N000000000/display.jpg', N'/media/catalog/jade/故玉001086N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/49243?dep=U', N'CC-BY-4.0', N'玉珌 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('754c28eb-791f-b051-d3fd-2375ba7819e4', N'故畫00026200000', N'元戴淳匡廬圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元仁宗延祐五年（1318）', NULL, N'戴淳（活動於西元十四世紀初），字厚夫，錢塘（今浙江杭州）人，擅長山水畫。老樹挺拔，山石險峻，高崖一層一層相疊著。峰頂築有古寺樓閣，建築物的描繪，方勁穩重，山石的形狀，也近乎方形。石紋多用枯筆皴擦，頗有蒼老而穩健的感覺。明末清初的龔賢，在畫 風上與這幅畫有極相近之處。', N'117.1 × 50.9 公分', N'/media/catalog/painting/故畫00026200000/display.jpg', N'/media/catalog/painting/故畫00026200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/730?dep=P', N'CC-BY-4.0', N'元戴淳匡廬圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0cd0f3d5-2eb8-456c-984c-23a9fd6174c4', N'南購畫00002900000', N'東海道十九 五十三次 江尻', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪江尻宿（靜岡縣靜岡市清水區）風景，畫面由右而左標示「東海道十九」、「五十三次 江尻」、「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002900000/display.jpg', N'/media/catalog/painting/南購畫00002900000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36484?dep=P', N'CC-BY-4.0', N'東海道十九 五十三次 江尻 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fdaaf858-d1da-b190-1d1e-244654c7ffa4', N'故畫00145400000', N'宋朱銳春社醉歸圖　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋理宗紹定二年(1229)', NULL, N'朱銳（活動於十二世紀），河北人。北宋宣和初授畫院待詔。南宋紹興年間復職，授迪功郎，賜金帶。工畫人物山水，師法王為，尤好寫騾綱、雪獵、盤車等圖。古制，每歲立春後第五個戊日為春社，是日舉行土地祭祀，以祈豐收。本卷繪祭祀畢，宴飲後的橫斜醉態，饒富奇逸之趣。沿途萬木復甦，大地欣榮，正是唐人王駕社日詩「桑柘影斜春社散，家家扶得醉人歸。」的寫照。幅末紹定二年之款，疑為後人添加，而其風格筆墨亦近於明代。', N'31.7 × 326.3 公分', N'/media/catalog/painting/故畫00145400000/display.jpg', N'/media/catalog/painting/故畫00145400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/531?dep=P', N'CC-BY-4.0', N'宋朱銳春社醉歸圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('851b0c60-2f89-fbae-3088-24a19feb1486', N'故琺000618N000000000', N'掐絲琺瑯雙龍盤', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明 萬曆', NULL, N'菊瓣折沿平底圈足盤，銅胎鎏金，紋飾掐絲。淺綠色盤心滿飾五色祥雲，中央有紅、黃雙龍拱衛團壽字。斜壁與盤底以淺藍色掐絲雲紋為地，前者更飾八雜寶與八吉祥，底心則有綠地填紅「大明萬曆年造」（1573-1620）雙行楷書款。琺瑯釉層薄，色彩繽紛，是晚明掐絲琺瑯之重要標準器。', N'高 6.9 公分、徑 48.3 公分', N'/media/catalog/enamel/故琺000618N000000000/display.jpg', N'/media/catalog/enamel/故琺000618N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1530?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙龍盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('34581e2f-9a36-0b51-bdd0-24a924a7fcbd', N'購錢001173N000000000', N'嘉祐元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「嘉祐元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001173N000000000/display.jpg', N'/media/catalog/coin/購錢001173N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10511?dep=U', N'CC-BY-4.0', N'嘉祐元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('06ff025d-242f-06af-17bc-257652410b30', N'故雕000005N000000000', N'竹雕出狩圖筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'筆筒以竹雕刻而成，鑲深棕色木口與底座，底帶三矮足。器表周飾蒼松與峻石與一隊人馬狩獵圖。狩獵大隊紛紛手持旌旗與各式武器，騎乘駿馬追逐獵物，獵犬尾隨其後。兔、鹿皆飛奔逃竄。全器以高浮雕、淺浮雕與淺刻技巧雕刻而成。', N'通高 17.7 公分、口徑 14.5 公分', N'/media/catalog/carving/故雕000005N000000000/display.jpg', N'/media/catalog/carving/故雕000005N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62310?dep=U', N'CC-BY-4.0', N'竹雕出狩圖筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e3f9baff-35aa-3f4b-373c-257a3d88f1a4', N'故雕000011N000000000', N'竹雕人物圖筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'筆筒以一節竹雕刻而成，底平，帶三矮足。竹筒表面刻一蹲坐人物。此人物留鬚，咧嘴而笑。竹筒另一面刻：「行到水窮處，坐看雲起時」。全器以薄地陽文技法雕刻而成。', N'高 14.0 公分、口徑 6.0 公分', N'/media/catalog/carving/故雕000011N000000000/display.jpg', N'/media/catalog/carving/故雕000011N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62314?dep=U', N'CC-BY-4.0', N'竹雕人物圖筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5f42e7ef-cf31-1f39-3084-257bee14b897', N'中玉000002N000000000', N'玉雕花扁平瓶', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'青⽟扁形瓶。⻑頸，變形夔耳，圈⾜。器身飾復古紋飾，頸飾三角形回紋，腹飾變形獸面紋。', N'高 9.1 公分、口徑長 1.7 公分、寬 1.4 公分、足徑長 2.5 公分、寬 1.7 公分', N'/media/catalog/jade/中玉000002N000000000/display.jpg', N'/media/catalog/jade/中玉000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52739?dep=U', N'CC-BY-4.0', N'玉雕花扁平瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f6e1b5c6-c888-66a8-b746-25c33943927f', N'故琺000712N000000000', N'掐絲琺瑯方尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯，長方形，侈口，短頸，雙獸首銜環耳，斜肩，圓腹，外撇圈足。口沿內壁飾有轉枝番蓮花紋，外壁由藍地黃環圈橫條紋分割為四個塊面，圖紋由上至下分別為花卉及蕉葉紋，轉枝番蓮花、茶花、番蓮花及綬帶鳥。圈足上飾奔馬紋。', N'高 30.8 公分', N'/media/catalog/enamel/故琺000712N000000000/display.jpg', N'/media/catalog/enamel/故琺000712N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61753?dep=U', N'CC-BY-4.0', N'掐絲琺瑯方尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3cbec537-9e7b-f0e5-303c-26a9227ff05f', N'故雕000001N000000000', N'竹根雕牧童臥牛', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'清十八世紀〈竹根雕牧童臥牛〉，以竹根圓雕一臥牛，頭盤髮髻、背著斗笠的牧童悠閒倚坐牛背上，左手牽繩直貫牛鼻，右手扶著牛角，向下俯視狀，生動地表現牧童與牛的互動。此外，利用竹子本身的纖維紋理，巧妙表現出牛毛的質感，為技法純熟的竹根圓雕。', N'長 10.3 公分、寬 7.9 公分、高 10.3 公分', N'/media/catalog/carving/故雕000001N000000000/display.jpg', N'/media/catalog/carving/故雕000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1828?dep=U', N'CC-BY-4.0', N'竹根雕牧童臥牛 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5fcfeaeb-f813-329f-4f0e-2761990cc08d', N'中琺000657N000000000', N'掐絲琺瑯螭耳爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎， 折沿淺爐， 立雕一對鎏金螭龍耳，底有象頭形矮足。爐身與折沿飾淺藍地深藍、紅、棕、白四色相間之纏枝蓮紋。爐底鑄有陽文楷書「景泰年製」偽款，應為明末作品。飾纏枝菊、蓮紋之鏤空鎏金夔龍蓋與立頸， 年代應晚於爐身。', N'高 28.3 公分、爐外徑 25.5 公分', N'/media/catalog/enamel/中琺000657N000000000/display.jpg', N'/media/catalog/enamel/中琺000657N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1534?dep=U', N'CC-BY-4.0', N'掐絲琺瑯螭耳爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fe95f35c-3b32-2c8f-909f-27a247b8a2d3', N'中瓷000055N000000000', N'青瓷八稜瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'瓶，全器作八邊形，侈口寬敞，短頸，斜肩，長腹下斂，圈足。通體施青瓷釉，灰青色帶米黃，密佈淺色開片紋。圈足露胎，塗棕色護胎汁，底心書「大清乾隆年製」青花篆款。', N'高 33.2 公分、口徑 9.5 公分、底徑 13.5 公分', N'/media/catalog/ceramic/中瓷000055N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000055N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19701?dep=U', N'CC-BY-4.0', N'青瓷八稜瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e12fc075-2478-8b93-4c1a-292932f2d126', N'中日雕000005N000000000', N'鏤雕象牙雲龍紋套球', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'象牙球的製作，是將牙材以車床鏇成球體，在球面往圓心處開出均勻分布的十四個錐形孔，用直角鈎刀在錐形孔中，一層一層由內而外刻出活動自如的套球後，再雕以各種紋樣裝飾。此件象牙套球，直徑約十二公分，表面以高浮雕刻飛龍穿梭於祥雲間，內部則雕刻各種鏤空精緻的錦地紋，共二十三層，每層皆可靈活轉動。', N'球徑 12.0 公分、座高 44.9 公分；木座長 29.4 公分、寬 29.4 公分、高 9.6 公分', N'/media/catalog/carving/中日雕000005N000000000/display.jpg', N'/media/catalog/carving/中日雕000005N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71781?dep=U', N'CC-BY-4.0', N'鏤雕象牙雲龍紋套球 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9631b837-be02-37a4-443a-294652e03d6a', N'故瓷009901N000000000', N'有田窯 五彩花鳥紋圓盒', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'口緣裝飾紅彩如意雲頭紋，其上並陰刻單線捲草紋填金彩。器身與器蓋內外以釉上彩滿飾纏枝梅花、牡丹、太湖石與鳥禽等圖案。器身臥足，著地處帶有砂粒，內有「肥碟山信甫造」紅字款。此器為伊萬里外銷落幕後，僅透過荷蘭商館進行私人貿易時崛起的田代紋左衛門，其轉手經銷作品的款銘之一。', N'高 6.5 公分、通高 10.4 公分、口徑 15.5 公分、底徑 7.0 公分', N'/media/catalog/ceramic/故瓷009901N000000000/display.jpg', N'/media/catalog/ceramic/故瓷009901N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/30650?dep=U', N'CC-BY-4.0', N'有田窯 五彩花鳥紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('13963f6f-4e72-ff52-63f8-2964f90ba864', N'中琺000050N000000000', N'掐絲琺瑯海宴河清燭臺', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'燈基為一圓盤，三雲紋扁足，全器紋飾以掐絲技法完成。盤外壁藍地，飾紅色蓮瓣紋。盤內為一深浮雕龜及二蛇，內壁作掐絲海水江牙，龜背立一立體展翅海燕(做鶴形)，燕身為白色，頸部一圈如意雲紋飾帶及翼膀上方二層鱗羽為紅色，以掐絲做羽紋。燕頭頂一燭檯，自下而上三層，下層較小靛藍地，中為綠地，上層最大、紅地、皆飾渦卷紋。底有陰刻「乾隆年製」四字雙行楷書雙方框款。', N'高 21.0 公分、盤徑約 12.0 公分', N'/media/catalog/enamel/中琺000050N000000000/display.jpg', N'/media/catalog/enamel/中琺000050N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53927?dep=U', N'CC-BY-4.0', N'掐絲琺瑯海宴河清燭臺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b7f81689-f790-9148-2efb-2a37e344498f', N'中銅000297N000000000', N'「尚方」仙人畫像鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'圓形鏡，半球鈕，連珠紋鈕座。內區主紋以四枚柿蒂形座乳丁為界。兩區內填以高浮雕仙人，兩側均有侍者。另兩區為相背的回首瑞獸兩隻。外環銘文一周二十九字：「尚方作鏡封日子明如日月世之□上有東王父西王母仙人子喬赤松子」，末屬「曹」字，為工匠名款。銘文外環紋飾三層，分別為細線篦紋、鋸齒紋及雲紋。三角斜緣。 明代商品經濟繁榮，鑄鏡業發達，也時興仿漢及仿唐銅鏡。仿漢鏡中又以帶有銘文的博局鏡及仙人鏡最受歡迎。本鏡即是其中一例。全鏡形制、紋飾題材與漢鏡十分相近，但紋飾刻畫呆板，細節模糊。銘文詞句具漢風，但簡省過度，文意不清。「曹」字工匠名款表示此鏡為仿古之作，非造假贗品。', N'直徑 18.2 公分', N'/media/catalog/bronze/中銅000297N000000000/display.jpg', N'/media/catalog/bronze/中銅000297N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7111?dep=U', N'CC-BY-4.0', N'「尚方」仙人畫像鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d92fd266-dd0f-9b6f-0514-2a9329458407', N'贈雕000134N000000000', N'骨雕填彩雲氣紋柄', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'此器取一段骨磨製而成，一端平齊，一端略磨圓，近磨圓之端相對面各穿一孔。器表陰刻連續雲氣紋，陰線勾邊，內刻短陰線填補空間，平齊的一端邊緣飾以火燄式紋飾；勾輪廓之陰線內填黑彩，餘填紅彩。器呈暗綠色。此器紋飾與西漢漆器上的雲氣紋類似，或即為西漢之物。', N'高 4.3 公分', N'/media/catalog/carving/贈雕000134N000000000/display.jpg', N'/media/catalog/carving/贈雕000134N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45363?dep=U', N'CC-BY-4.0', N'骨雕填彩雲氣紋柄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e8c11d95-7cad-d205-d986-2ce34db0c023', N'故玉000092N000000000', N'玉帶扣', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'玉質，有沁染形成的赭紅色斑。方形，帶卯字型扣，正面飾神獸，後面素面無紋。', N'長 7.96 公分、寬 4.7 公分', N'/media/catalog/jade/故玉000092N000000000/display.jpg', N'/media/catalog/jade/故玉000092N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48283?dep=U', N'CC-BY-4.0', N'玉帶扣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('07ae4a4c-0e9f-081f-844c-2ce5f3982a89', N'中銅000190N000000000', N'寶相花紋葵花鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'八瓣菱花形鏡，圓鈕，圓鈕座。鏡背飾寶相花紋。', N'直徑 14.5 公分', N'/media/catalog/bronze/中銅000190N000000000/display.jpg', N'/media/catalog/bronze/中銅000190N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7067?dep=U', N'CC-BY-4.0', N'寶相花紋葵花鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5b612490-4cc1-2634-29e4-2d7207ffba95', N'故玉006543N000000000', N'玉飛天', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'玉質沁褐，雕一飛天人物。', N'寬 3.4 公分', N'/media/catalog/jade/故玉006543N000000000/display.jpg', N'/media/catalog/jade/故玉006543N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57615?dep=U', N'CC-BY-4.0', N'玉飛天 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('679742dc-4d87-fc7f-ba05-2da2dbc9beb2', N'中漆000074N000000000', N'剔紅龍紋方勝盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅方勝式盒，木胎，色硃紅。罩式蓋，淺直壁，平底。蓋面雕三龍戲於水波之上，周緣飾回紋，蓋壁亦以水波紋為地，雕珊瑚、珠、角諸寶。器周壁彩繪黃色萬字、粉紅朵花、藍地黑邊框之菱形錦地，內有繪黃與紅色回紋黑漆屜，屜裝彩雕萬字朵花錦地小方盒七。', N'長 22.9 公分、寬 16.2 公分、通高 8.48 公分、深 5.8 公分', N'/media/catalog/lacquer/中漆000074N000000000/display.jpg', N'/media/catalog/lacquer/中漆000074N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17531?dep=U', N'CC-BY-4.0', N'剔紅龍紋方勝盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f39a9e39-164d-45c8-334d-2dced3f810f3', N'中銅000527N000000000', N'錯金銀天雞尊', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'本件著錄於《西清續鑑》，作「漢天雞尊一」。整體作鳥形，背上負尊，這類負尊鳥形器通常稱為「天雞尊」。通體錯以金銀，表面覆蓋著青綠、赭色的假鏽。經過放大，可見綠色的假鏽中有孔雀石屑。', N'長 35.0 公分、高 31.8 公分', N'/media/catalog/bronze/中銅000527N000000000/display.jpg', N'/media/catalog/bronze/中銅000527N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2028?dep=U', N'CC-BY-4.0', N'錯金銀天雞尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8a042f53-c4bb-e7b5-c0db-2dface0c7082', N'中銅000022N000000000', N'劍', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'劍，圓莖上下等粗，中有兩平行凸箍，寬格，圓首。', N'高 50.2 公分', N'/media/catalog/bronze/中銅000022N000000000/display.jpg', N'/media/catalog/bronze/中銅000022N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6776?dep=U', N'CC-BY-4.0', N'劍 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5fb2cf40-0ec9-89ab-e0c0-2e913d7c319a', N'故琺000761N000000000', N'掐絲琺瑯鹿鶴長春花插', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯花插，筒狀器身，口部嵌七孔蓋，矮圈足下底部鑲接三鍍金狻猊形足，器身一側鑲浮雕式鍍金夔龍。器內露胎，器表淺藍釉地掐絲竹鶴雙清、芭蕉、雙鹿、湖石、靈芝等紋飾。器底鍍金陰刻填黑「大明景泰年製」單行楷書款。應是十五世紀末十六世紀初的文物。', N'高 14.5 公分、口徑 8.0 公分、足徑 8.0 公分', N'/media/catalog/enamel/故琺000761N000000000/display.jpg', N'/media/catalog/enamel/故琺000761N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1522?dep=U', N'CC-BY-4.0', N'掐絲琺瑯鹿鶴長春花插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bdb0d205-8044-dc86-0170-311444aad7a5', N'故畫00070100000', N'清王武花鳥　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙二十四年（1685）', NULL, N'王武（西元一六三二至一六九○年），江蘇長洲人。字勤中，號忘庵，自稱雪顛道人。精於鑑賞，家富收藏，於宋元明諸大家名蹟，往往心摹手追，務得其遺法，故所畫花鳥動植物等，任筆宣染，皆具足生意，脫盡院畫習氣。名高當代，時人以之比擬惲壽平。', N'167.2 × 58.7 公分', N'/media/catalog/painting/故畫00070100000/display.jpg', N'/media/catalog/painting/故畫00070100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3479?dep=P', N'CC-BY-4.0', N'清王武花鳥　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2342c0fd-d74e-c0e0-1d3a-3175670f9eb0', N'中瓷000031N000000000', N'洋彩百鹿雙耳尊', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆三年', NULL, N'瓷胎，直口，短頸，雙螭型耳，斜肩，碩腹，外撇圈足。通體施白釉，外壁以各色彩釉繪製山水、鹿群、松樹、柏樹、桃樹、靈芝。足緣露胎，胎呈白色。底有青花書「大清乾隆年製」三行篆書款。', N'高 44.0 公分、口徑 15.7 公分、底徑 24.0 公分、最大徑 37.0 公分', N'/media/catalog/ceramic/中瓷000031N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000031N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18999?dep=U', N'CC-BY-4.0', N'洋彩百鹿雙耳尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1550bac1-2e6a-21a7-8c5b-327416390741', N'故畫00070400000', N'清王翬畫奇峰聳秀　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙十七年（1678）', NULL, N'王翬（西元一六三二－一七一七年），常熟人。字石谷，號耕煙散人、清暉主人、烏目山人、劍門樵客。山水得王時敏指授，為清四大家之一。此畫成於戊午花朝，作者四十七歲。溪塢之間，一峰特起，其下平林古寺，溪藪漁舟。全幅用水甚豐，畫面一片濕潤，筆亦極為生動，是石谷畫中，最饒天趣者。是年二月廿一日，石谷與武進唐于光同在蘇州，去花朝蓋不足十日也。', N'62.2 × 29.2 公分', N'/media/catalog/painting/故畫00070400000/display.jpg', N'/media/catalog/painting/故畫00070400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3482?dep=P', N'CC-BY-4.0', N'清王翬畫奇峰聳秀　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6fedd2b5-0b5b-340c-eab8-32b0147420b9', N'中琺000862N000000000', N'掐絲琺瑯獸面尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。敞口，溜肩，垂腹，鎏金雙獸首啣環耳，高圈足外撇。以掐絲技法、琺瑯料填色製作花紋，口沿飾蕉葉紋，頸、肩飾纏枝番蓮紋，腹部飾獸面紋及番蓮紋，各組紋飾間以回紋、花卉紋及環帶紋邊飾，圈足飾蓮瓣紋。', N'高 44.1 公分、口徑 14.9 公分', N'/media/catalog/enamel/中琺000862N000000000/display.jpg', N'/media/catalog/enamel/中琺000862N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54685?dep=U', N'CC-BY-4.0', N'掐絲琺瑯獸面尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7a4cdbc3-5e80-5b73-12bf-336256e0dd18', N'故畫00039700000', N'明邊文進三友百禽圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明成祖永樂十一年（1413）', NULL, N'邊文進，生卒年不詳，福建沙縣人。字景昭。永樂間（西元一四０三－一四二四年）召至京師，授武英殿待詔。宣德間（一四二六－一四三五）仍供事內殿。善畫花果翎毛，為其後呂紀等人所宗法。 本幅成於永樂癸己（一四一三），松、竹、梅三友並植，祥禽百隻，或跳躑；或鼓噪；或飲啄，悉能盡其情態。經營位置錯落有致，設色妍麗，繪製精整，為邊氏傳世之精品。', N'151.3 × 78.1 公分', N'/media/catalog/painting/故畫00039700000/display.jpg', N'/media/catalog/painting/故畫00039700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3196?dep=P', N'CC-BY-4.0', N'明邊文進三友百禽圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('912a7fe6-2010-267b-2aef-345e3e90b7ad', N'中琺000123N000000000', N'掐絲琺瑯夔龍紋簋式爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'撇口，短頸，垂腹，雙螭形耳，圈足外撇，帶鏤空蓮瓣紋及異獸紋笠形蓋，異獸鈕。以淺藍地掐絲琺瑯為飾，蓋緣飾朵雲紋，頸部飾渦卷紋，腹部前後各飾一對藍色夔龍紋，腹下飾一圈蓮瓣紋，圈足飾八瓣花紋。中琺123、124、125為一組。', N'通高 11.2 公分', N'/media/catalog/enamel/中琺000123N000000000/display.jpg', N'/media/catalog/enamel/中琺000123N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53995?dep=U', N'CC-BY-4.0', N'掐絲琺瑯夔龍紋簋式爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6e1f906d-abd5-8ed1-c6b9-3460deb10ba1', N'贈雕000042N000000000', N'磋骨長柱細腰', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'周', NULL, N'骨製細腰。長柱形，底平，中腰細縮，兩端做馬鞍形。類似細腰曾見於灃西、上村嶺、寶雞、曲阜與洛陽等地的西周至戰國遺址中，通常與車馬器共出，其質材不限於牙或骨，也常見銅製者。', N'長 2.8 公分、徑 1.1 公分', N'/media/catalog/carving/贈雕000042N000000000/display.jpg', N'/media/catalog/carving/贈雕000042N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45268?dep=U', N'CC-BY-4.0', N'磋骨長柱細腰 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fe09f46d-cbe3-3416-684a-346742f62f22', N'故瓷010100N000000000', N'有田窯 描金花卉山水圖盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'盤口部外敞，寬折沿，壁呈淺圓弧，圈足低矮。盤心繪一菱角形提籃及各色花卉之盆花紋，內壁以靛藍釉為地，上繪紅、金、黃三色為主之花卉紋飾。內壁上下並有二雲肩形開光，內繪山水及花鳥梅竹紋樣，以及數個書卷形開光，內繪纏枝花卉紋樣。器外壁有三組各二大一小花卉組成之纏枝紋。足內以青花繪一圓圈，並有七個明顯支釘痕跡。', N'高 8.7 公分、口徑 54.4 公分、足徑 26.1 公分', N'/media/catalog/ceramic/故瓷010100N000000000/display.jpg', N'/media/catalog/ceramic/故瓷010100N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/42611?dep=U', N'CC-BY-4.0', N'有田窯 描金花卉山水圖盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('65ee77f3-0696-7fc3-d5de-348fe475f4e2', N'中玉000014N000000000', N'玉獸面紋貫耳瓶', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'青玉扁形瓶，玉色泛綠。貫耳長頸，有圈足。腹部飾獸面紋。', N'高 12.3 公分、口徑長 3.0 公分、寬 2.6 公分、足徑長 3.1 公分、寬 2.2 公分', N'/media/catalog/jade/中玉000014N000000000/display.jpg', N'/media/catalog/jade/中玉000014N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52753?dep=U', N'CC-BY-4.0', N'玉獸面紋貫耳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1c953627-8ff1-bfde-7d6e-34bcb6e442db', N'中玉000313N000000000', N'雙身動物紋玉璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢早期至中期', NULL, N'青白玉，由外緣向內，局部有暗褐色沁，半透明。圓整，平廓，廓線圓整；中孔、外緣均齊整；花紋分內、外二區，內區刻飾以蒲紋，外區刻飾以雙身動物紋，近內廓有一圈絞絲紋，內、外區間亦有一團絞絲紋。附木架。', N'徑 13.9 公分、孔徑 4.79 公分、厚 0.28 公分', N'/media/catalog/jade/中玉000313N000000000/display.jpg', N'/media/catalog/jade/中玉000313N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2586?dep=U', N'CC-BY-4.0', N'雙身動物紋玉璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ecb062e0-17ff-1184-207b-35281ec22910', N'中漆000037N000000000', N'剔紅八仙人物桃式盒(曹國舅)', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'桃形盒。內壁髹素黑漆，外壁全以剔紅技法裝飾。蓋面中心人物為八仙之一「曹國舅」，手持拍板。周圍環繞著山石、如意雲紋及蝙蝠，天與地皆以繁密之錦紋表現，是漆器上特有的紋飾表現手法。其餘部分滿佈中間有花紋的六邊形格錦紋。', N'長 15.0 公分、寬 14.3 公分、高 5.3 公分、連蓋高 9.8 公分、深 4.9 公分、底徑長 10.0 公分、寬 9.5 公分', N'/media/catalog/lacquer/中漆000037N000000000/display.jpg', N'/media/catalog/lacquer/中漆000037N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17449?dep=U', N'CC-BY-4.0', N'剔紅八仙人物桃式盒(曹國舅) 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('36321a9d-f19e-8410-ac37-35711fb29687', N'故琺000750N000000000', N'掐絲琺瑯葫蘆式扁瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎， 葫蘆式瓶， 唇口， 頸部鼓漲渾圓，而瓶身扁圓，接長方形鎏金矮足，鑲鎏金雲紋雙耳。滿施淺藍色釉，頸及瓶側飾纏枝蓮紋； 腹部一面飾梅、竹及瑞鹿， 另一面則有殿堂屋簷及仙鶴銜桃枝遨翔海上仙山，寓意海屋添籌、鹿鶴（六合）同春。應為晚明作品。', N'高 24.0 公分、腹徑 15.2 公分', N'/media/catalog/enamel/故琺000750N000000000/display.jpg', N'/media/catalog/enamel/故琺000750N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1533?dep=U', N'CC-BY-4.0', N'掐絲琺瑯葫蘆式扁瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('59e062dd-52aa-b950-b0d1-36b74ace1ff5', N'中雕000006N000000000', N'犀角雕荷葉式杯', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'明代實施海禁，廣州口岸成為各國土特產的集散地，而犀牛角產自東南亞，從產地進口至廣州，被用作珍貴藥材與極好的雕刻材質。明代後期，經濟繁榮，盛行各種文房珍玩，犀角雕刻融匯各種技藝與風格，成為珍貴的收藏文玩，同時符合當時的奢華品味。此件雕荷葉為杯，旁有盛開後的荷花，與之共生的菱角交錯其間，又有河螺寄生於上，以流暢刀工，並極寫實的手法刻畫荷塘一隅，顯得生氣勃勃。並有「一品承天，露下秋荷，聖恩。顧達銘」淺浮雕行書款。（引自《亞洲探險記：十七世紀東西交流傳奇》）', N'寬 20.0 公分、高 10.5 公分', N'/media/catalog/carving/中雕000006N000000000/display.jpg', N'/media/catalog/carving/中雕000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54941?dep=U', N'CC-BY-4.0', N'犀角雕荷葉式杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e2290cc4-cb86-7597-3ca2-3741cee26bfb', N'中瓷004753N000000000', N'定窯 白瓷印花牡丹蓮荷紋盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'敞口，淺弧壁，圈足。器內外與圈足內底施米白色釉，足底露胎。口沿處鑲有一圈銅釦。器外壁光素無紋，內壁以印花技法裝飾各種圖案。器內口沿處飾兩道弦紋，腹壁滿飾花葉紋，碗心飾一圈回紋，內有各式花卉圖案。全器紋飾風格細膩精巧。', N'高 8.5 公分、口徑 15.3 公分、底徑 5.0 公分', N'/media/catalog/ceramic/中瓷004753N000000000/display.jpg', N'/media/catalog/ceramic/中瓷004753N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23345?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花牡丹蓮荷紋盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7ee07dba-da18-6bff-93ef-378b6504206f', N'故玉004947N000000000', N'玉虎紋飾件', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'方框形飾件。白玉沁褐，一長邊外側沁褐處保留部分玉皮，中央淺浮雕一坐虎，上下飾有葉紋，虎眼為菱形，以陰刻線條表現其肢體及斑紋線條。紋飾外型皆有簡化，然內部線條表現精細。', N'長 4.9 公分', N'/media/catalog/jade/故玉004947N000000000/display.jpg', N'/media/catalog/jade/故玉004947N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/56225?dep=U', N'CC-BY-4.0', N'玉虎紋飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('af3f09a8-6b79-b6f7-2d06-37d6cc609719', N'故瓷012098N000000000', N'有田窯 柿右衛門類型 五彩花口碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'碗呈五瓣花形，內外壁均施乳白色釉，釉層較薄。釉上加彩繪飾山石花木，碗心則有雙鳳追逐，紋飾之外還保留大量空白，散發含蓄優雅的氣質，是伊萬里瓷器中的「柿右衛門」樣式。器外底心書雙方框「福」字銘，書體近渦旋狀，也稱之為「渦福」銘。', N'高 11.4 公分、口徑 11.4 公分、足徑 11.3 公分', N'/media/catalog/ceramic/故瓷012098N000000000/display.jpg', N'/media/catalog/ceramic/故瓷012098N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24158?dep=U', N'CC-BY-4.0', N'有田窯 柿右衛門類型 五彩花口碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('affa097f-7bd6-b721-bfaa-390cf3f9d9c6', N'故琺000403N000000000', N'掐絲琺瑯象足洗', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'撇口、斜壁、平底洗，帶銅鑄雙，螭耳，三象足。銅胎，外壁飾藍地五彩掐絲琺瑯轉枝番蓮紋。器外底為轉枝番蓮間七珍，中央深灰青地掐絲填藍「景泰年製」圓框楷書款。', N'高 10.4 公分、口徑 19.3 公分', N'/media/catalog/enamel/故琺000403N000000000/display.jpg', N'/media/catalog/enamel/故琺000403N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1537?dep=U', N'CC-BY-4.0', N'掐絲琺瑯象足洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8ab0fb71-ced1-6b95-c47b-394ea6cc9227', N'贈雕000124N000000000', N'牙雕雲紋璧', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'扁平璧形，內外徑皆不規整，孔璧光滑平直，外緣窄而直；一面平，另一面斜弧，斜弧面打磨較平滑，細線陰刻三組流雲紋，部份陰線尚留朱彩，每組流雲紋間以二小洞間隔，原可能有嵌件，今已脫落。', N'徑 3.3 公分', N'/media/catalog/carving/贈雕000124N000000000/display.jpg', N'/media/catalog/carving/贈雕000124N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45353?dep=U', N'CC-BY-4.0', N'牙雕雲紋璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('420aa075-673c-8299-93ab-3d35ecf58233', N'贈雕000189N000000000', N'牙雕鏤空描金白彩花卉紋梳', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'f2a78063-931b-9926-749c-324377d136c7', N'宋金至元', NULL, N'全器呈半月形，一端銳尖，另一端已殘，原應仍成尖銳形。因紋飾所需，器之背寬中央稍大，梳齒長度由中央向兩側依序遞減，梳背雕飾鏤空花卉紋，間描金為飾，花瓣部位尚填白彩。', N'殘長 8.5 公分、寬 3.6 公分、背厚 0.3 公分', N'/media/catalog/carving/贈雕000189N000000000/display.jpg', N'/media/catalog/carving/贈雕000189N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45417?dep=U', N'CC-BY-4.0', N'牙雕鏤空描金白彩花卉紋梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('eeb951fd-5809-4e00-c6a9-3d75fb62c63d', N'贈錢001179N000000000', N'淳熙元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'方孔圓錢。「淳熙元寶」為世界最早的記年錢，自淳熙七年（1180）開始背面添加紀年，較歐洲記年錢早三百餘年。有篆、楷兩種字體，又有銅、鐵兩種材質。此枚銅錢正面有楷書「淳熙元寶」四字，背面方孔上下有「十三」二字，代表鑄於淳熙十三年。', N'待測量', N'/media/catalog/coin/贈錢001179N000000000/display.jpg', N'/media/catalog/coin/贈錢001179N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9002?dep=U', N'CC-BY-4.0', N'淳熙元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0c44baef-a330-51be-6d7e-3e70d1572eda', N'中瓷002227N000000000', N'白瓷印花花卉紋盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'敞口盤，口緣銅釦，弧壁下斂，圈足。器內外罩施透明釉，整器呈色白，只在圈足內積釉處見有青色。外壁光素無紋，隱約見有輪製痕。內壁印花卷枝花葉為飾，其近口緣處並見回紋一圈。足緣部份露胎，部份有釉，足內滿釉無款識。', N'高 4.2 公分、口徑 20.1 公分、底徑 5.8 公分', N'/media/catalog/ceramic/中瓷002227N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002227N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23707?dep=U', N'CC-BY-4.0', N'白瓷印花花卉紋盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3ef0af54-15df-274a-3adf-3e8c0646115b', N'贈瓷000480N000000000', N'綠釉皮囊壺', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'皮囊壺，遼代典型器形，仿契丹族使用的各種皮囊容器而燒造。扁身單孔式，壺身上扁下圓，上穿兩繫孔，邊角處貼飾一獸紋。全器施綠釉，釉不及地。器身一面貼飾團龍紋並刻劃卷紋，另一面貼飾草葉紋同樣刻劃卷紋。', N'高 32.3 公分、寬 18.2 公分、口內徑 4.7 公分', N'/media/catalog/ceramic/贈瓷000480N000000000/display.jpg', N'/media/catalog/ceramic/贈瓷000480N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43509?dep=U', N'CC-BY-4.0', N'綠釉皮囊壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e3e69b70-5f27-5eff-8ff5-3ebdd04f1c19', N'故玉000922N000000000', N'獸首扭絲紋玉環', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國晚期', NULL, N'青白玉質，局部受沁呈褐色，頭部略經修改。此件扭絲紋玉環玉質緻密、製作精細。由於孔徑占全體的比例較明顯為大，而且器身略為立體圓鼓，所以扭絲紋的間距在內、外圓周上也沒有太大的不同。另外在獸首上鑽磨一小孔作為繫帶穿孔，同時也作為眼睛。', N'徑 8.4 公分、孔徑 5.4 公分、厚 0.9 公分', N'/media/catalog/jade/故玉000922N000000000/display.jpg', N'/media/catalog/jade/故玉000922N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2565?dep=U', N'CC-BY-4.0', N'獸首扭絲紋玉環 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('728cd566-b40d-07f3-ca48-3f01b0f0cd96', N'中畫00023700000', N'清嚴宏滋白描羅漢　卷', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清高宗乾隆二十五年（1760）', NULL, N'嚴宏滋（活動於西元一七三六至一七九五年），字丕緒，江蘇江陰人。' + NCHAR(13) + NCHAR(10) + N'　　本卷畫十八羅漢，或持法器，或施法力，或相顧言笑，或怡然自得，各具表情。群像布置，左右各一組，復雜以高低錯落，以見其變化之妙。畫法為典型白描法。衣紋描法分二主要類別：一為下筆略重，但整體尚勻整；另一為一起一伏，粗細分明，線條密集有如畫譜所謂曹衣出水描。整幅筆調及氣質，頗覺清雅可愛。畫成於乾隆庚辰（西元一七六○）年。', N'33 × 60.4 公分', N'/media/catalog/painting/中畫00023700000/display.jpg', N'/media/catalog/painting/中畫00023700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1801?dep=P', N'CC-BY-4.0', N'清嚴宏滋白描羅漢　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dad7dca3-f0cf-8869-6704-3f1b4c1f96e2', N'中瓷000324N000000000', N'廣窯 白釉荷花洗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'器作一荷葉上捲為洗，侈口，深弧壁，平底。通體施白釉，色灰白光潤，密佈細小的灰色開片紋，器內外皆劃有荷葉經絡紋理，洗內貼飾螃蟹四隻，整體造形活潑有生趣。器底有六枚支釘痕。螃蟹與荷葉寓意「和諧」。', N'高 14.5 公分', N'/media/catalog/ceramic/中瓷000324N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000324N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19606?dep=U', N'CC-BY-4.0', N'廣窯 白釉荷花洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3da9e0c7-0907-283e-8f40-3fd3ca1a14a4', N'中瓷004012N000000000', N'邢窯 白瓷穿帶壺', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'這件白瓷壺器形仿自金屬或皮革材質的穿帶水壺。器外壁及外底施白釉，釉色瑩亮，積釉處微閃見湖水青色，器內施釉不及半，露出灰白色胎。侈圓口、短頸、圈足，筒狀圓長腹的兩側微凹，上下各貼有二個絆繫耳，使繩索能夠穿繫，很類似遊牧民族隨騎攜帶的水壺。唐朝時各種不同材質的器物經常會相互模仿，院藏另一件白瓷印花魚紋杯成四瓣花型，器形即源於作為酒器使用的薩珊式金銀多曲長杯。', N'高 20.2 公分、口徑 6.3 公分、足徑 9.8 公分', N'/media/catalog/ceramic/中瓷004012N000000000/display.jpg', N'/media/catalog/ceramic/中瓷004012N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1467?dep=U', N'CC-BY-4.0', N'邢窯 白瓷穿帶壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('edffab59-16e9-b2f3-988c-4250480c6804', N'故玉000052N000000000', N'玉瑗', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'玉質。圓環形，器小似鐲，素面無紋。', N'徑 5.8 公分、孔徑 3.8 公分', N'/media/catalog/jade/故玉000052N000000000/display.jpg', N'/media/catalog/jade/故玉000052N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48247?dep=U', N'CC-BY-4.0', N'玉瑗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('86367416-6518-2faf-92d6-428ebdd11dce', N'中漆000016N000000000', N'剔紅佛龕座頂', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅龕，色紅，略有傷損，本件僅餘龕座頂。長方形二重簷式蓋，折邊均飾回紋，簷斜面雕飾番蓮紋、蓮瓣紋與繡球朵花錦地之雲頭紋，二簷間作閣樓式小夾層，雕飾番蓮紋，各有三到五個開光，其中二短邊三開光還擺有繪佛像玻璃片，頂有長方形寶頂，頗巨。龕頂基處邊角有挖小圓孔，應是裝組之用。', N'長 42.0 公分、寬 29.5 公分、通高約 60.0 公分', N'/media/catalog/lacquer/中漆000016N000000000/display.jpg', N'/media/catalog/lacquer/中漆000016N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17552?dep=U', N'CC-BY-4.0', N'剔紅佛龕座頂 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('91183498-6365-bbd2-f325-42adf1673ca9', N'中銅000057N000000000', N'父丁爵', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'長流，尖尾，口沿有二柱，獸首鋬，深腹下碩，圓底，三個外撇的板形尖足。除了腹外壁的飾帶外，其餘光素無紋。腹外飾帶有暗示雙眼的圓凸起，配合滿飾的減地雲雷紋為地，成為眉目清晰的獸面紋。銘文位於鋬後。', N'通柱高 17.5 公分', N'/media/catalog/bronze/中銅000057N000000000/display.jpg', N'/media/catalog/bronze/中銅000057N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53450?dep=U', N'CC-BY-4.0', N'父丁爵 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('325af6f0-64a0-deb2-4784-42f1168acc77', N'贈雕000049N000000000', N'骨虎柄梳', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'兩塊骨材磨製而成，柄部磨成二尾部相連之回首虎紋，再以褐彩繪虎斑及眼、耳等部位，褐彩斑駁脫落。梳齒自頂部開始刻鑿，但並不刻透，僅離端部三分之一處開始鑿透，梳齒端部微外侈，但一端外侈部位可能因經常使用而平齊。梳柄與梳齒間各鑿二小孔，以供插榫相接。梳柄虎紋與戰國玉器之虎紋頗為相似，但玉器所琢磨紋飾常較精細。', N'長 7.4 公分、柄寬 6.8 公分', N'/media/catalog/carving/贈雕000049N000000000/display.jpg', N'/media/catalog/carving/贈雕000049N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45275?dep=U', N'CC-BY-4.0', N'骨虎柄梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a3c9bef2-470a-a2f7-acf1-433536827ee4', N'中瓷000361N000000000', N'龍泉窯 青瓷雙耳長頸瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'盤口，折沿，直長頸，雙螭形環耳，斜肩，垂腹，外撇圈足。頸部有四道凹弦紋，全器施青釉，呈豆青色，釉面佈滿淺色開片紋。足底緣露胎，塗赭色護胎汁。', N'高 25.6 公分、口徑 7.5 公分、底徑 8.2 公分、最大徑 11.5 公分', N'/media/catalog/ceramic/中瓷000361N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000361N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/20250?dep=U', N'CC-BY-4.0', N'龍泉窯 青瓷雙耳長頸瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ce7468ce-d314-956c-2a64-43a068978301', N'故琺000746N000000000', N'掐絲琺瑯龍耳扁壺', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'扁壺，直筒頸，扁圓腹，圈足，雙龍耳。外壁飾藍地五彩掐絲琺瑯。頸飾桃實，腹一面飾桃樹花果，另面為寶相花，底鑄「景泰年製」方框、填黑篆書款。', N'高 27.1 公分、腹寬 19.1 公分', N'/media/catalog/enamel/故琺000746N000000000/display.jpg', N'/media/catalog/enamel/故琺000746N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1535?dep=U', N'CC-BY-4.0', N'掐絲琺瑯龍耳扁壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8c3dbed1-f29c-c1e3-dbcf-43a45baa94dd', N'故銅000443N000000000', N'錢引庫檢察印', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '537eb4b8-f69a-7ca3-e137-f528e2c7b0a3', N'西夏', NULL, N'方形，板狀，橛鈕，印面作陽文，篆體六字：「錢引庫檢察印」。配有素淨的木方盒，盒內另裝盛呈文一紙，考訂該印源流。此印得自烏魯木齊屯田墾地出土，收於《西清續鑑‧甲編》附錄，圖說內容較呈文精簡。據考，《宋史‧食貨志》載北宋崇寧以前使用「錢引」紙幣，對照〈職官志〉說明交引庫負責給印出納，以及左藏庫設有「提轄檢察官」，可知此印是用於錢鈔發行的認證。然而，宋代疆域未及烏魯木齊，與歷代官印相比，形制粗率，遂認為此印乃西夏學習宋制之遺存。 現就此印用朱文、印鈕無穿孔的形式，與西夏官印使用白文，且保留古印鈕穿孔的特色不同。宋制銅印在烏魯木齊出土，或有其他傳世緣由，現已不得而知。', N'高 5.7 公分、長 4.5 公分、寬 4.5 公分', N'/media/catalog/bronze/故銅000443N000000000/display.jpg', N'/media/catalog/bronze/故銅000443N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62120?dep=U', N'CC-BY-4.0', N'錢引庫檢察印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('cf210e63-ba5d-484e-0fa7-4406fef50f0a', N'南購畫00010500000', N'日本 20世紀富岡鐵齋牧童騎牛圖 軸', 'ec78c074-e905-9285-7894-321d57e98275', '11ec6247-6d3d-1c84-46c0-511d7d4f8c9d', N'日本大正時代14年（1925）1月', NULL, N'富岡鉄斎死後的作品被記載為「大正十四年一月/九十叟鐵齋」。橋本独山在外箱墨書「遺墨」、書寫的時間則是「時過初夏」，表示箱書是在鉄斎死後寫的，從緣由書可得知寸紅堂主委託独山寫了箱書。富岡鉄斎近年的研究顯示，大正13年(1924)起，初秋左右的作品開始用九十歲的落款。鉄斎死於12月31日除夕，12月上旬左右痼疾的膽石症發病，中旬一度轉好，年底卻又複發。31日中午，病床上雖可談話但下午突然去世。本作品的紀年「大正十四年一月九十叟」，推估為大正13年9月到12月上旬左右製作，可視為鉄斎最晚年的作品。相較於其他畫作，本作品雖略感無力，但是作為煎茶器套組的掛軸，佈置在和室壁龕中依然是非常合適。', N'官方資料未提供', N'/media/catalog/painting/南購畫00010500000/display.jpg', N'/media/catalog/painting/南購畫00010500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36551?dep=P', N'CC-BY-4.0', N'日本 20世紀富岡鐵齋牧童騎牛圖 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('97fecec8-34c2-362c-7048-449f4877d3cc', N'購玉000814N000000000', N'玉鏃 推測由玉戈改制', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'深淺交雜不透明的玉質，細膩溫潤。琢作一玉簇。但較一般箭簇寬大。由器之外形、中脊等觀之，似為用玉戈或玉矛改製而成。這種玉料流行於龍山時期至商、西周，而此造形的戈、矛，較接近商代風格。改工部分質地色澤均自然，應去原作時期不遠，固亦訂為商代。', N'長 10.0 公分、寬 4.5 公分、厚 0.6 公分', N'/media/catalog/jade/購玉000814N000000000/display.jpg', N'/media/catalog/jade/購玉000814N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/444?dep=U', N'CC-BY-4.0', N'玉鏃 推測由玉戈改制 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a10bd3f1-f41d-cd0e-e4de-4556e4bd6fc2', N'故畫00049700000', N'明文徵明松陰曳杖圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖二十三年（1544）', NULL, N'文徵明（西元一四七○至一五五九年），江蘇長洲人。本名文壁，字徵明，後以字行，亦字徵仲，別號停雲生、衡山居士。詩文書畫造詣均佳，與沈周、唐寅、仇英共稱為「明四大家」。　　水墨畫山泉林屋，沿溪邊有長松數株，蒼秀矗立。士人二閑步而來，倚杖者行於前。後有山壁瀑泉，遠樹人家，層層推遠。此幀皴山畫樹皆用中鋒細筆，精工綿密而不瑣碎。畫成於嘉靖甲辰（一五四四），是年徵明七十五歲。', N'106.9 × 25.1 公分', N'/media/catalog/painting/故畫00049700000/display.jpg', N'/media/catalog/painting/故畫00049700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3296?dep=P', N'CC-BY-4.0', N'明文徵明松陰曳杖圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('74b04a2c-e8d4-d771-9303-457185d5eb79', N'贈雕000057N000000000', N'骨雕雙拼龍紋帶鉤', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國至漢', NULL, N'全器應由兩塊骨材組成，今僅存其中之一，並殘斷成兩段，鉤首殘斷缺蝕，器身有一橫穿孔以便與另一塊相連接；鉤鈕位於中央稍偏鉤首部位。器身呈曲棒形，尾端翹起，器雖傷蝕仍約略可辨為龍首形，身軀飾陰線、弧線、小圈點紋與密點紋等。器身正面近鉤鈕部位鑿一深槽，並向鉤首方向延伸鑿出，略作三角形深溝，原或有綠松石類嵌件。', N'長 13.9 公分', N'/media/catalog/carving/贈雕000057N000000000/display.jpg', N'/media/catalog/carving/贈雕000057N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45283?dep=U', N'CC-BY-4.0', N'骨雕雙拼龍紋帶鉤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a9614d67-b2b2-5f4a-7cf6-45b0f5a693dd', N'故瓷009579N000000000', N'邢窯 白瓷執壺', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'敞口，鼓腹，平足，底邊與圈足一線切線明顯，短流，曲把。外壁至內頸均施白釉，內頸部以下及外底無釉，內壁可見明顯拉坯遺痕。白釉瑩潔光亮，把手積釉處白釉泛青，腹部有多處淌釉遺痕。胎土潔白細膩。此類執壺，由晚唐至北宋早期，經常出現於北方窯系，與西安出土唐太和三年(829)王明哲墓出土「老得家茶瓶」形制相似，亦和唐代劉府君墓出土邢窯白釉執壺雷同，又和國立臺中自然科學博物館所藏唐代滑石茶器組中的短流茶瓶相近，此類型制是唐代用來裝煮沸水點茶的茶瓶。', N'高 12.1 公分、口徑 6.9 公分、足徑 6.5 公分', N'/media/catalog/ceramic/故瓷009579N000000000/display.jpg', N'/media/catalog/ceramic/故瓷009579N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1073?dep=U', N'CC-BY-4.0', N'邢窯 白瓷執壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a7920804-9205-1356-238c-45cfffb1b9cf', N'故玉000034N000000000', N'鹿猴玉飾', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'玉質，全器鏤空，仿湖石靈芝形，下似有一鹿蹲踞，器頂有一穿。', N'通長 5.12 公分、寬 2.65 公分', N'/media/catalog/jade/故玉000034N000000000/display.jpg', N'/media/catalog/jade/故玉000034N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48230?dep=U', N'CC-BY-4.0', N'鹿猴玉飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4243936b-d1c9-ae01-20ff-46e5a0624303', N'中琺000053N000000000', N'掐絲琺瑯碟', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'侈口，折沿，淺壁，平底，圈足。全器紋飾以掐絲技法完成，通體藍地，金屬絲精細，琺瑯料濃厚鮮麗。口沿緣飾梵文一周，內底有卷鬚錦，盤心有一由七個梵文及三個符號組成的「十相自在」吉祥紋飾，盤內外壁為朵雲紋間飾佛教七珍、八寶。底部有陰刻「乾隆年製」四字雙行楷書雙方框款。', N'高 3.5 公分、口徑 15.2 公分、足徑 7.8 公分', N'/media/catalog/enamel/中琺000053N000000000/display.jpg', N'/media/catalog/enamel/中琺000053N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53929?dep=U', N'CC-BY-4.0', N'掐絲琺瑯碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6adea260-ef79-1560-284b-47779a071156', N'中瓷002226N000000000', N'白瓷印花鳳紋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'敞口大碗，深弧壁下斂，圈足。口緣銅釦，器內外壁施透明釉，外壁色白而光素無紋，但可見胎壁上的旋削痕。內壁磨損嚴重，色透黃，釉下印花雙鳳穿花為飾。底足積釉處略泛青色，足內滿釉無款識。', N'高 7.3 公分、口徑 21.0 公分、底徑 6.2 公分', N'/media/catalog/ceramic/中瓷002226N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002226N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23706?dep=U', N'CC-BY-4.0', N'白瓷印花鳳紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3b2157f5-25c5-8ef4-f5f8-47fe3ac141bf', N'中玉000307N000000000', N'「長樂」玉璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'東漢', NULL, N'青玉，局部有褐色沁，半透明。璧體圓整，有廓，廓稍高；中孔壁留有鑽孔的旋轉紋，外緣齊整；花紋分內外二區，內區飾以乳釘紋，外區鏤雕以螭紋，螭紋盤繞而上，突伸至璧體外；外區的上下端鏤雕「長」、「樂」各一字。', N'最長 16.6 公分、徑 13.5 公分、孔徑 2.9 公分、厚 0.5 公分', N'/media/catalog/jade/中玉000307N000000000/display.jpg', N'/media/catalog/jade/中玉000307N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/401?dep=U', N'CC-BY-4.0', N'「長樂」玉璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0f549679-a01d-2f71-aeee-482cdcf0fd6e', N'中銅000288N000000000', N'「承安四年」鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'圓鏡，圓鈕。內區飾瑞獸，銘文帶二十六字。', N'直徑 9.1 公分', N'/media/catalog/bronze/中銅000288N000000000/display.jpg', N'/media/catalog/bronze/中銅000288N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7098?dep=U', N'CC-BY-4.0', N'「承安四年」鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bafcdb31-9fbb-8fc2-9e0f-485531e75045', N'中琺000125N000000000', N'掐絲琺瑯夔龍紋盒', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'蒸餅式，子母口，平底。以淺藍地掐絲琺瑯為飾，全器飾朵雲地藍色夔龍紋。中琺123、124、125為一組。', N'盒高 3.3 公分', N'/media/catalog/enamel/中琺000125N000000000/display.jpg', N'/media/catalog/enamel/中琺000125N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53997?dep=U', N'CC-BY-4.0', N'掐絲琺瑯夔龍紋盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fc994d6c-7e1c-b57a-55dd-486c74bd59dd', N'中玉000017N000000000', N'玉細頸瓶', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'青玉小瓶，局部有赭斑。長頸、直筒腹、平底。腹部飾瓦楞直紋。', N'高 10.6 公分、口徑 1.9 公分、足徑 3.5 公分', N'/media/catalog/jade/中玉000017N000000000/display.jpg', N'/media/catalog/jade/中玉000017N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52756?dep=U', N'CC-BY-4.0', N'玉細頸瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('27207461-c3ca-d348-62f3-49e02e87c624', N'故畫00050100000', N'明文徵明茂松清泉　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖二十一年（1542）', NULL, N'壬寅（一五四二）四月廿四日，作茂松清泉軸，兩檜一松，三株雜樹，幾佔全幅。松下作平坡，兩翁坐而聽泉，樹杪微襯背山，筆跡亦極茂密。通幅皆學王蒙。　　是年八月二十一日，配吳夫人卒，年亦七十三。', N'89.9 × 44.1 公分', N'/media/catalog/painting/故畫00050100000/display.jpg', N'/media/catalog/painting/故畫00050100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3300?dep=P', N'CC-BY-4.0', N'明文徵明茂松清泉　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('60d54af1-2a63-9c3b-062a-49fe79e56dbc', N'故畫00193700000', N'元趙孟頫觀泉圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大二年（1309）', NULL, N'趙孟頫（西元一二五四—一三二二年），字子昂，號松雪道人。本宋宗室，宋亡仕元，至翰林學士承旨，封魏國公，諡文敏。詩文清遠，工書善畫。所倡書法入畫觀念，影響後世甚鉅。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'青壁雙起，蒼松夾峙，半為雲掩，瀑水自石壁間出，數折而下，士人抱拳聽泉，狀甚悠閒。此圖筆法高逸，青綠設色亦極淳厚典雅，以明文徵明、仇英風格之筆墨，作此頗富趙氏青綠山水韻味之作品。', N'53.9 × 24.8 公分', N'/media/catalog/painting/故畫00193700000/display.jpg', N'/media/catalog/painting/故畫00193700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1243?dep=P', N'CC-BY-4.0', N'元趙孟頫觀泉圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('68277d10-ee1b-376d-607b-4a0dee8bb563', N'故瓷011441N000000000', N'黑釉鐵斑三足鍑', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'這件黑釉鐵斑鍑口沿微捲，短直頸，圓肩鼓腹，平底，帶有三獸形足。器身施罩醬黑色釉，釉色不勻，釉表有光澤感，釉面可見明顯鐵斑痕跡；器內施釉亦有抹畫痕，外壁施釉不及底，露出棕褐色胎，胎質細膩，外底還可看見轆轤鏇修痕跡。整件作品與河北省深州市下博村唐墓出土品近似，也和三彩、白瓷等相似造型的作品共同反映出九世紀三足鍑盛行的時代風格。本器雖貼有清代「天字三号」黃籤一張，但對照民國十四年（1925）「辦理清室善後委員會」點檢紫禁城故宮物品，以千字文順序所編的《故宮物品點查報告》卻發現，於其時本件的所在地是壽皇殿，稱為「古瓷三足礶」，由此或可反映出清宮物品在傳世過程中可能經過移動或存在不同的編號系統。', N'高 17.2 公分、口徑 16.2 公分', N'/media/catalog/ceramic/故瓷011441N000000000/display.jpg', N'/media/catalog/ceramic/故瓷011441N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/35696?dep=U', N'CC-BY-4.0', N'黑釉鐵斑三足鍑 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('391b93f4-205e-13dc-bc46-4a594b710aca', N'中畫00022300000', N'明丁雲鵬應真雲彙　卷', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明神宗萬曆二十四年（1596）', NULL, N'丁雲鵬（生於西元一五四七或一五四八年，至年八十二歲尚在人世），字南羽，號聖華居士，安徽休寧人。善畫佛道人物，為晚明大家。' + NCHAR(13) + NCHAR(10) + N'　　危巖峭壁，古木叢林，諸羅漢或倚松坐石，或晏坐禪定，或閱經論法，龍虎神怪，種種變現。羅漢造型以貫休羅漢為本，胡貌梵相，曲盡其態。全卷用墨濃淡兼施，用筆粗細並用，款署明萬曆丙申（一五九六），雲鵬畫風至此又一變矣。', N'33.8 × 663.7 公分', N'/media/catalog/painting/中畫00022300000/display.jpg', N'/media/catalog/painting/中畫00022300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1787?dep=P', N'CC-BY-4.0', N'明丁雲鵬應真雲彙　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('19751e09-285e-4213-8e60-4b322730f1c5', N'贈雕000044N000000000', N'骨雕貝', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'東周', NULL, N'仿先秦貝幣形狀，扁橢圓形，正中陰刻一道直槽，左右橫刻十數道平行短陰線，似貝之面；背面或平直，或中央內凹，或凹凸不平，並有兩孔，以供繫綴。廿一件骨雕貝局部已呈綠色。貝幣是商晚期至周代曾流行的一種貨幣，後來出現以牙、角、骨、銅、銀、金等仿貝幣型作為裝飾嵌件，例如洛陽戰國墓中曾發現銅器或陶器上鑲嵌這類骨雕貝，另外在西周張加坡車馬坑中，也曾發現以骨雕貝作為車馬飾件。', N'長 2.1-3.0 公分', N'/media/catalog/carving/贈雕000044N000000000/display.jpg', N'/media/catalog/carving/贈雕000044N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45270?dep=U', N'CC-BY-4.0', N'骨雕貝 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('eb44ac29-d29f-842f-c667-4b8543ccff13', N'中畫00002300002', N'明唐寅採蓮圖　卷　文彭草書採蓮曲', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖三十八年（1559）', NULL, N'文彭，字壽承，號三橋，為明代吳門領袖文徵明長子，少承家學，能書擅畫。本幅用筆熟練，筆意酣暢，為文彭狂草佳作，書於嘉靖已未（一五五九）年，贈予項元汴，右下角有千字文第九八五「孤」字編號。項氏與文家世交，每得舊藏常邀文彭兄弟鑒定真偽，而文彭亦精篆刻，元汴藏印之佳者亦多出其手。此卷乃三作合成，唐寅〈採蓮圖〉上項氏諸印與卷末項氏之畫、跋、印等，疑為合卷時所偽添。', N'35 × 318 公分', N'/media/catalog/painting/中畫00002300002/display.jpg', N'/media/catalog/painting/中畫00002300002/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1897?dep=P', N'CC-BY-4.0', N'明唐寅採蓮圖　卷　文彭草書採蓮曲 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7ce0419a-f63d-515c-7a6a-4bdb8bc1d7bb', N'故琺000736N000000000', N'掐絲琺瑯雙耳鳳瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，掐絲琺瑯。喇叭口，長頸，碩腹下歛，撇圈足，下接三獸足作承負狀，頸嵌雙鳳銜環為耳，肩部另有三銜環鳳首。器身施藍釉為地，滿繪多彩纏枝番蓮紋，肩與足處加飾蓮瓣紋一周。器底鏨雙龍，中剔地陽刻「大明景泰年製」楷款，款識與器身露胎處皆鎏金。', N'高 45.4 公分、口徑 21.3 公分', N'/media/catalog/enamel/故琺000736N000000000/display.jpg', N'/media/catalog/enamel/故琺000736N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61774?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙耳鳳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('cd335035-548b-6836-e30b-4cd321ebc3d0', N'中漆000044N000000000', N'剔紅赤壁圖插屏', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'長方形，連座。髹紅色漆。以蘇軾的赤壁賦為題材，船行於遼闊的江面上，水波粼粼，一旁山崖陡峭高聳，構圖悠揚雄壯，漆層厚，刀法犀利，光影的效果下，錦地與光面的山石、船舟相互對比，雕漆結合繪畫，另闢蹊徑。', N'長 59.9 公分、寬 16.5 公分、高 63.6 公分', N'/media/catalog/lacquer/中漆000044N000000000/display.jpg', N'/media/catalog/lacquer/中漆000044N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3177?dep=U', N'CC-BY-4.0', N'剔紅赤壁圖插屏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0f1447c4-351e-0def-7927-4cff4edab102', N'贈雕000028N000000000', N'牙雕魚形珮', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'商晚期至西周', NULL, N'全器取一段獸牙琢製而成，剖面略成三角形，一端作魚首形，於唇部鑿一孔，自其下頷穿出，可繫掛，側面尚有一未鑿穿之孔；另一端圓弧。器身中腰內縮，陰線紋飾分成三段：有孔的一段即作魚首紋，魚身前段飾一側面獸首紋，後段所飾陰刻線紋略成三角形。魚唇部位已為銅鏽染成綠色，在側面未鑿穿之孔的部位上遺留銅鏽。近年在山東滕縣前掌大村發現商代中晚期墓葬，在已發掘的五座商代晚期大墓即有一件雕骨魚，長一二‧六公分，通體泛綠，兼有朱色，紋飾與此件相似。此外，在加拿大皇家安大略博物館亦藏有類似器，與此件更類似，但無穿孔。加拿大皇家安大略博物館的雕骨魚出於河南，山東滕縣前掌大商代大墓是商代某方國的貴族墓地，也被認為是商代在東方的「商文化亞區」。除了商代後期的出土雕骨魚外，在河南濬縣辛村E區第四條探溝一個西周早期小型墓(M72)中，也曾出土一件骨雕魚形佩，尺寸與玉丁寧館所贈者接近(長一四‧五公分)，器形與紋飾也雷同。前者魚唇部位略殘，似原有穿，故郭寶鈞逕名之為「魚形佩系」。', N'長 14.1 公分、最寬 2.2 公分、最厚 1.2 公分', N'/media/catalog/carving/贈雕000028N000000000/display.jpg', N'/media/catalog/carving/贈雕000028N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45247?dep=U', N'CC-BY-4.0', N'牙雕魚形珮 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('34e47acb-c77f-6141-53c7-4d36c9805fe4', N'故雕000013N000000000', N'竹雕窺簡圖筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'筆筒為書齋之器用，《長物志》〈筆筒〉條記「湘竹栟櫚者佳」，明中葉以來多以竹刻為陳設雅玩。此件「窺簡圖筆筒」浮雕高髻仕女，為「西廂記」中的崔鶯鶯，背屏風而立，含羞展卷細讀。屏風上淺刻梧桐樹，枝葉繁茂，枝上立一鳥，「三松」二字楷書款識陰刻於屏風右下角。屏風後躲著另一仕女為紅娘，食指掩唇偷窺讀簡的小姐。側屏風後，几案陳設有瓶花、爐盒香具、古琴、筆硯之類。此件圖樣源自明末清初畫家陳洪綬（1599-1652）為《張深之先生正北西廂秘本》版畫之〈窺簡〉和〈報捷〉。而朱稚征字叔子，號三松，是萬曆年間竹雕的代表人物。傳世作品中多有「三松」款，但以此件最為著名。在構圖上的匠心裁量，營造如繪畫般的氣氛，又力求工細繁複的技術表現，可為竹雕工藝之極致。（引自《亞洲探險記：十七世紀東西交流傳奇》）', N'高 14.0 公分、口徑 8.5 公分、底徑 8.7 公分', N'/media/catalog/carving/故雕000013N000000000/display.jpg', N'/media/catalog/carving/故雕000013N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2412?dep=U', N'CC-BY-4.0', N'竹雕窺簡圖筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8a9060a3-a4bd-35cd-c9b2-4d4fd9e2195c', N'購瓷000075N000000000', N'琉璃珠', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'灰藍色不透明球形珠，中央穿有小孔，外壁部分呈平滑的藍色塊面，色澤近似青金石。', N'高 2.2 公分、外徑 2.4 公分、孔徑 0.2 公分', N'/media/catalog/ceramic/購瓷000075N000000000/display.jpg', N'/media/catalog/ceramic/購瓷000075N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/42956?dep=U', N'CC-BY-4.0', N'琉璃珠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b1c9fdf4-468a-fc0e-e22a-4d65451fae3c', N'中雕000002N000000000', N'犀角溪谷泛舟觥', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'犀角質器，色深赭間蜜黃。器仿觥形，前有闊流，深長腹向下漸斂，平底。器身浮雕山林溪澗間，涼亭小橋，還有數人泛舟水面。器底雕水邊石堆小景。', N'長 16.2 公分、寬 9.9 公分、高 14.3 公分', N'/media/catalog/carving/中雕000002N000000000/display.jpg', N'/media/catalog/carving/中雕000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14931?dep=U', N'CC-BY-4.0', N'犀角溪谷泛舟觥 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('43771156-ee6a-ccd4-37e5-4dac1423bb19', N'贈雕000032N000000000', N'骨雕鳥首笄', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'器用一整塊骨雕製而成；笄首雕重疊的側面雙鳥立於王字臺座上，陰刻一點作眼紋，翼部陰刻雙圈一點之圈點紋，鳥眼、胸部與臺座上原或嵌松綠石為飾，部份嵌件已佚；臺座與鳥尾部位有傷缺，尾端呈銳尖錐形。類似的雕骨鳥首基層於陝西長安灃西張家坡西周居址遺址中出現，鳥的眼睛與胸部也鑲嵌著綠松石，因此這件骨笄或也是西周遺物。', N'長 12.2 公分', N'/media/catalog/carving/贈雕000032N000000000/display.jpg', N'/media/catalog/carving/贈雕000032N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45258?dep=U', N'CC-BY-4.0', N'骨雕鳥首笄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9ae06f42-a043-5fb7-b388-4e4bb454384d', N'中雕000004N000000000', N'犀角雕螭龍杯', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'倒三角形杯，外壁浮雕折枝梅花、木蘭及松樹，一螭龍口啣靈芝趴於杯緣，身體延伸出杯外，對面杯緣內有一小螭龍，回首與之對望。杯底尖，如雙獸足交疊，無法立起，需置於附件之歲寒三友木座上。', N'連座高 21.5 公分', N'/media/catalog/carving/中雕000004N000000000/display.jpg', N'/media/catalog/carving/中雕000004N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54939?dep=U', N'CC-BY-4.0', N'犀角雕螭龍杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bc581abe-922e-f6b3-9fbd-4f3ccf3b09fa', N'南購畫00002700000', N'東海道十七 五十三次 由井', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪由比宿（靜岡縣靜岡市清水區）風景，畫面由右而左標示「東海道十七」、「五十三次 由井」、「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002700000/display.jpg', N'/media/catalog/painting/南購畫00002700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36482?dep=P', N'CC-BY-4.0', N'東海道十七 五十三次 由井 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('728b5abd-5a94-f7a8-c5f1-4f44639254af', N'中琺000006N000000000', N'掐絲琺瑯瓶（五供）', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'銅胎。敞口，長頸，鍍金雙雲形帶環耳，鼓肩，圓長腹，圈足外撇。器身以掐絲技法、琺瑯料填色製作花紋，以淺藍色為地，頸部及腹部飾番蓮紋，頸部下端及腹部下端外撇處飾雙夔龍紋邊飾，口沿及圈足飾回紋。底部露胎，有「乾隆年製」雙行楷書雙方框鏨款。內附銅膽一只。瓶為五供之一，本器與中琺3-7成套。', N'瓶高 27.5 公分', N'/media/catalog/enamel/中琺000006N000000000/display.jpg', N'/media/catalog/enamel/中琺000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53883?dep=U', N'CC-BY-4.0', N'掐絲琺瑯瓶（五供） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('94e142a0-cc33-b950-5442-4f56f09ce430', N'故銅001353N000000000', N'「侯同」銅印', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '561e3931-1096-c637-9eb3-b5c5ce02c88f', N'秦', NULL, N'壇鈕，印面白文邊界開上下二字，作「日」形邊欄，由上起讀篆文「侯同」二字，白文。文字改古篆的圓婉為方折，成為簡單的點畫，出現了隸書的結構雛形。「日」形邊欄，即「半通印」。相對於「田」字格印記，因如「田」字界欄削去其半，故得此名。本印置於清乾隆朝「金薤留珍」之「書」櫃屜匣中。「金薤留珍」乃乾隆朝時將內府所收的前代印記整理編次而成。其包含銅官印221件，私印1070件，共1294件，存放於「東」、「壁」、「圖」、「書」、「府」五個黑地金漆龍紋屜匣中，並依各櫃所藏編製印譜。印譜目錄編次方式以官印為始，繼以私印，可能是援引明代以來印譜編目的傳統。', N'高 1.44 公分、印面長 1.75 公分、寬 1.04 公分', N'/media/catalog/bronze/故銅001353N000000000/display.jpg', N'/media/catalog/bronze/故銅001353N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/4748?dep=U', N'CC-BY-4.0', N'「侯同」銅印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3b1667d1-549c-1a9e-3f30-4f745734fc46', N'中瓷003796N000000000', N'定窯 白瓷印花力士獻寶百褶盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'折沿盤，盤口及器壁作五十一瓣百褶多曲花式。敞口、弧形淺壁，臥足，底寬平，邊線微凸起為圈足；滿釉，口沿鑲銅棱。全器以內模成形及印花裝飾，折沿作雙層蓮瓣紋；器壁每一褶區中作一折枝小花。盤面則作力士獻寶圖：左方為奔入的托寶力士，裸胸、赤足、垂耳飾、著飄帶、足佩環，若蠻夷貢寶，雙手托著頂上的寶盆，盆壁飾蓮瓣，現寶光火焰，盆內盛象牙、犀角、珊瑚、寶珠等。右方一臥鹿，頸繫飄帶回望。前後方各置一水波紋如意足橢圓盆，各植桃實滿樹與湖石。全圖隙處分填飾象牙、方勝、犀角、火珠、珊瑚等雜寶。', N'高 2.5 公分、口徑 22.0 公分、底徑 14.2 公分', N'/media/catalog/ceramic/中瓷003796N000000000/display.jpg', N'/media/catalog/ceramic/中瓷003796N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19956?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花力士獻寶百褶盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('60bc015b-fa4a-aba8-259d-51206fac787d', N'故瓷012504N000000000', N'白瓷撇口長頸瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'撇口長頸瓶，頸中段窄細並向上下端緩和外展；肩圓鼓，腹作球形，長寬約略相當，上部略豐而下斂；餅形假足，平底無釉。胎色白，無施化妝土，外表大半受土鏽與傷蝕。此種長頸壺瓶自北朝開始製作，或與歐亞草原傳來之金屬器、玻璃器相關；從北齊、隋、唐一直持續發展。本器胎體堅緻，施釉細膩平勻，雖有大片面積的釉面受蝕，仍屬早期白瓷難得之作，推測為邢窯作品。', N'高 26.3 公分、口徑 6.3 公分、底徑 8.5 公分', N'/media/catalog/ceramic/故瓷012504N000000000/display.jpg', N'/media/catalog/ceramic/故瓷012504N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/27708?dep=U', N'CC-BY-4.0', N'白瓷撇口長頸瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('64ef6e22-feee-75c8-640a-513ce8e59dd0', N'中銅000441N000000000', N'仲駒簋', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'附蓋圓簋，子母口、雙耳、圓腹、圈足，耳作獸首形附珥。全器錯金銀，蓋、頸飾冏紋、夔紋，腹飾波帶紋，足飾鳥紋，均以雷紋為地。蓋、器均有銘四行。', N'高 23.3 公分', N'/media/catalog/bronze/中銅000441N000000000/display.jpg', N'/media/catalog/bronze/中銅000441N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5564?dep=U', N'CC-BY-4.0', N'仲駒簋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fa087190-e32a-b4b8-5bf9-519de8043081', N'故玉000001N000000000', N'玉勒（玉𤨕）', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋早期', NULL, N'玉質，有黃灰斑。扁方形，上下不同寬，束腰有孔貫穿，器表飾側面龍首紋，並略有變形調整以配合形制，原於清宮時與數件文物，合儲物四層屜匣內。', N'長 3.9 公分、寬 2.3 公分', N'/media/catalog/jade/故玉000001N000000000/display.jpg', N'/media/catalog/jade/故玉000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48199?dep=U', N'CC-BY-4.0', N'玉勒（玉𤨕） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('578fbdbd-23db-e47b-e2ad-51af806e1b45', N'故漆000382N000000000', N'鎗金填漆荷花圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'盒蓋與盒身的口沿均外侈，蓋平，圈足，器形特殊，盒內及足內髹紅褐漆。盒外鋪以填漆花紋六角形錦地，荷花圖案的輪廓線及葉脈等處鎗金，圖案內填漆。盒身沿足邊飾三組荷花圖，盒蓋外緣與盒身裝飾相同，盒蓋中心飾對稱的全開蓮花與葉，花蒂相連。漆面打磨不細，以色彩取勝，紅花與綠葉對比強烈，錦地紅色的線條在黃地上，與鎗金相映下，顯得金碧輝煌。', N'高 3.8 公分', N'/media/catalog/lacquer/故漆000382N000000000/display.jpg', N'/media/catalog/lacquer/故漆000382N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17724?dep=U', N'CC-BY-4.0', N'鎗金填漆荷花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('965706fe-460c-0bf9-eab1-534fcc6c4874', N'贈銅000321N000000000', N'日本 江戶時代 銅鎏金 誕生佛立像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本 江戶時代 或以後', NULL, N'銅鎏金立佛，頭部光素無紋，笑容可掬，全身赤裸，立於圓筒狀座上。右手上舉，左手握拳自然垂放於腰間。尊像大體光素無紋，強調弧面，加上笑容滿面的表情，很能表現小孩純真的氣氛，造像樣式近於佛誕生之時，步步蓮花，七步之時，一手指天，一手指地云：「天上地下，唯我獨尊。」的傳說，本尊佛可能為「誕生佛」。', N'通高 17.0 公分、像高 14.5 公分、台座徑 4.0 公分、全重 292.6公克', N'/media/catalog/bronze/贈銅000321N000000000/display.jpg', N'/media/catalog/bronze/贈銅000321N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/24718?dep=U', N'CC-BY-4.0', N'日本 江戶時代 銅鎏金 誕生佛立像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d681bb63-a543-5980-63ce-54284cfe59b3', N'購錢000519N000000000', N'景祐元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面篆書：「景祐元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000519N000000000/display.jpg', N'/media/catalog/coin/購錢000519N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9857?dep=U', N'CC-BY-4.0', N'景祐元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7f36b9b2-5e9c-e364-294f-5463bedc6220', N'故漆000029N000000000', N'剔紅荔枝圓盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'皮胎，圈足，足底髹褐漆，盤沿雕連枝牡丹，花一仰一俯相間排列，兩側各二枝上下交叉，以線條表現花與葉。盤面外沿刻花形菱格帶狀飾。盤內下沿刻山丘樣重覆起伏的地面，一棵樹伴著一株藤蔓，穿過盤心，向左右分枝，再往上伸展，中心為三粒荔枝，圓周四個位置各二個果實，樹幹上是波浪狀的紋理，底部又無數同心圓似的地紋，再加上扭動的樹幹和捲曲的枝葉，使盤面充滿動感，佈局疏密平均，構圖穩定，漆色紅，漆層薄，漆質堅實，刀法略斜，使規整的輪廓線增加變化，是一件少見的佳品。', N'高 1.7 公分、口徑 14.7 公分、足徑 11.7 公分', N'/media/catalog/lacquer/故漆000029N000000000/display.jpg', N'/media/catalog/lacquer/故漆000029N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18154?dep=U', N'CC-BY-4.0', N'剔紅荔枝圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('efa378ce-8335-eca9-b04a-54946aabb724', N'故玉000076N000000000', N'玉劍璏', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'玉質，方形，面向兩側突出飾弦紋。璏是嵌飾於劍鞘中部，用以穿劍帶之鈕，本器為仿漢作品，應已無原始功能。', N'長 5.7 公分、寬 2.6 公分', N'/media/catalog/jade/故玉000076N000000000/display.jpg', N'/media/catalog/jade/故玉000076N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48267?dep=U', N'CC-BY-4.0', N'玉劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('22d9adc3-771d-f503-ebf2-553320958677', N'故畫00044300000', N'明沈周畫山水　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明憲宗成化十二年（1476）', NULL, N'成化丙申四月廿九日，友人相約陪吳石居為虎邱之遊，獨沈周未能踐約。次日攜酒追往，而吳石居已離去。雨後，周徘徊山水之間，成五言律詩一首，適吳石居表弟吉之求畫，周遂書此詩題畫。　　畫山畫樹，筆意漸圓漸熟，與崇山修竹及醉後山水並異。畫中雲影中斷，林麓蒼溼，是寫雨後景。小橋之上，一翁曳杖而行，或即畫「雨後振孤策」詩意也。畫時正五十歲。', N'56.1 × 31.7 公分', N'/media/catalog/painting/故畫00044300000/display.jpg', N'/media/catalog/painting/故畫00044300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3242?dep=P', N'CC-BY-4.0', N'明沈周畫山水　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3c7c07c4-428e-a217-4771-5543834df91e', N'中玉000375N000000000', N'玉琮形盂', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'玉質，黃赭色相間。器作矮圓筒形，兩側有獸形銜環耳。外壁淺浮雕獸面紋、棱脊。上雕飾回紋，風格接近安徽休寧南宋朱晞顏墓出土玉器。器底刻「子孫保之」款。附木座。', N'高 4.1 公分、口徑 5.81 公分', N'/media/catalog/jade/中玉000375N000000000/display.jpg', N'/media/catalog/jade/中玉000375N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53129?dep=U', N'CC-BY-4.0', N'玉琮形盂 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c5bd9a2f-d645-e347-45c9-55b938fe5f08', N'中瓷000340N000000000', N'定窯 白瓷花卉紋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'金至元', NULL, N'敞口碗，弧形深壁，平底，圈足。全器施牙白色釉，釉色瑩潤。口緣無釉，鑲銅棱釦，外壁劃飾轉枝蓮花(或萱草花)，碗內光素無紋，圈足緣平齊露胎。', N'高 8.0 公分、口徑 16.6 公分、底徑 6.8 公分', N'/media/catalog/ceramic/中瓷000340N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000340N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23130?dep=U', N'CC-BY-4.0', N'定窯 白瓷花卉紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3ed51e64-bd3e-d340-8ba9-55dceae94689', N'中銅001197N000000000', N'鎏金蟠龍紋瓶', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'瓶，蒜形口，長頸，鼓腹，圈足。全器鎏金，頸飾立雕蟠龍，身軀盤踞扭動，動感十足。', N'高 14.3 公分', N'/media/catalog/bronze/中銅001197N000000000/display.jpg', N'/media/catalog/bronze/中銅001197N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6615?dep=U', N'CC-BY-4.0', N'鎏金蟠龍紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('20dfc291-3a70-7f33-d6d9-561a23501be4', N'故畫003886N000000000', N'冬圃含韶 冊', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'紙本冊頁，裝訂屬「經摺裝」方式，據《書畫裝池之美》記載，因此法最早被使用於裝裱佛經，又稱「梵夾裝」。前後以木質幀，封面書「冬圃含韶」。共有十二頁，繪有各式不同花卉，有梅花、薔薇、茶花、蘭花、水仙..等等，姿態各異，競相爭妍。末頁花卉圖左下側書「臣 董誥敬繪」，鈐印「臣」、「誥」。', N'長 13.85 公分、寬 10.8 公分', N'/media/catalog/painting/故畫003886N000000000/display.jpg', N'/media/catalog/painting/故畫003886N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62049?dep=U', N'CC-BY-4.0', N'冬圃含韶 冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0a8adbb1-515c-7e3a-0804-567b36ee4c6f', N'故漆000138N000000000', N'剔紅琴鶴人物盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅小盒，色紅，沉艷有光澤。子母口，淺直壁，平底。蓋面雕林間飛鳥小景，舉子與僕童於其中，神態歡愉，器身與底則飾連枝花卉，本件漆層肥厚，刀法表現圓潤飽滿。器裡髹黑色光漆。', N'高 4.5 公分、徑 7.6 公分', N'/media/catalog/lacquer/故漆000138N000000000/display.jpg', N'/media/catalog/lacquer/故漆000138N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18084?dep=U', N'CC-BY-4.0', N'剔紅琴鶴人物盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('af6bd226-ef28-0220-7d3b-56e410adf9d9', N'故琺000479N000000000', N'掐絲琺瑯雙螭虎耳三足盤', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。敞口，平底，下接三足（一足缺），口緣二側飾鍍金螭獸二隻。全器以掐絲琺瑯裝飾，內外以淺藍釉為地，滿飾纏枝番蓮紋，釉面氣泡多。盤心嵌飾鏨金朵花一，器底嵌朵花，上鈐「景泰年製」偽款。', N'高 8.0 公分、深 4.5 公分、口徑 23.5 公分、底徑 18.5 公分', N'/media/catalog/enamel/故琺000479N000000000/display.jpg', N'/media/catalog/enamel/故琺000479N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61572?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙螭虎耳三足盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5fe35aaa-aeac-991b-5d6d-56ef108abfe5', N'故漆000386N000000000', N'填漆牡丹圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，胎薄，底平無足，底及盒內髹紅褐漆。盒側以八個回紋為飾，字之間一上一下的枝葉彷彿是波浪狀連枝，葉片散落有致。盒面滿鋪花形六角格錦地，牡丹一枝自左下進入畫面中央，分成兩莖後，分枝前後交疊掩映中，後側一枝高挺直立，最右一枝欹斜至最左側，四枝頭各開一朵牡丹，各有姿態，或正或側或背，葉片配置均衡，畫面協調。花葉輪廓線條的輕重變化，有毛筆線條的提按頓挫，紅地黃線的地紋與白花綠葉，色彩突出不失優雅。', N'徑 13.1 公分、高 3.4 公分', N'/media/catalog/lacquer/故漆000386N000000000/display.jpg', N'/media/catalog/lacquer/故漆000386N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1834?dep=U', N'CC-BY-4.0', N'填漆牡丹圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0ec66234-9a51-9b45-6a25-583dea10b20a', N'贈雕000062N000000000', N'牙鳥首璜', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'器呈半圓形，一面平，一面弧突，剖面略呈三角形，兩端尖，中段較寬，兩端雕鳥首形，有一端鳥喙部已殘；鳥首部位陰刻圈點紋為眼紋，完好的鳥首端陰刻一線以分別鼻部與唇部，身軀刻斜弦紋：器之正中部位突起一道弦紋，其旁貫穿一孔以供繫掛。器殘斷成數段，今已黏合。湖北江陵雨台山第一六三號楚墓中，曾出土四件角質鳥首璜，只是前者中段弦紋不似後者幾乎佈滿全器。第一六三號楚墓是戰國時代的墓葬，而本件牙雕鳥首璜與此墓出土的角質鳥首璜類似，故可作為斷代之依據。', N'長 10.2 公分、寬 1.0 公分、厚 0.6 公分', N'/media/catalog/carving/贈雕000062N000000000/display.jpg', N'/media/catalog/carving/贈雕000062N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45288?dep=U', N'CC-BY-4.0', N'牙鳥首璜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('37e46904-e3a9-0fa4-48a2-585d762e8757', N'故畫00069200000', N'清王鑑倣趙孟頫山水　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙十六年（1677）', NULL, N'王鑑（一五九八－一六七七），太蒼人，字圓照，號湘碧，自稱染香庵主，世貞之孫。仕至廉州知府，精通畫理，為清初四王之一。 雲巒飛瀑，煙樹層樓，一叟策杖過橋，一童囊琴隨後，設色明麗，佈局精到。', N'160.4 × 96.4 公分', N'/media/catalog/painting/故畫00069200000/display.jpg', N'/media/catalog/painting/故畫00069200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3470?dep=P', N'CC-BY-4.0', N'清王鑑倣趙孟頫山水　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('40d587f9-1789-8f3f-0cb6-58616807e3e4', N'贈錢001260N000000000', N'嘉慶通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「嘉慶通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001260N000000000/display.jpg', N'/media/catalog/coin/贈錢001260N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9083?dep=U', N'CC-BY-4.0', N'嘉慶通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dc0fa7f1-eca3-370b-22bf-58937d6bb6fc', N'中漆000069N000000000', N'剔黑嵌玉三層套盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔黑套盒，色黑泛墨綠色。方形十二瓣式，矮直壁，平底淺凹。蓋面中心嵌白玉與碧玉組成之太極圖，周嵌如意與蟬形玉片各四，玉片有傷損，間隙雕飾斜方萬字錦地紋，蓋與三層套盒皆以回紋為邊，正方回紋地上雕蟬紋。器裡與底髹黑色光漆。', N'長 16.5 公分、寬 16.5 公分、通高 20.3 公分、足徑 13.1 公分', N'/media/catalog/lacquer/中漆000069N000000000/display.jpg', N'/media/catalog/lacquer/中漆000069N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17535?dep=U', N'CC-BY-4.0', N'剔黑嵌玉三層套盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3cb74e1c-9e5a-638d-2722-5929777f7000', N'贈雕000133N000000000', N'骨雕填彩雲氣紋管', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'長管形，剖面呈六瓣花式，一端在每個弧狀突起部位剔刻一三角凹面，另於未曾剔刻的器表陰刻細線雲氣紋，或為弧線，或是短陰線；細陰線內或填紅彩，或填黑彩，色彩仍相當鮮麗。器表局部呈淺綠色，有不少黑斑。此器可能為車馬上的飾件，細陰線填彩的裝飾方法常見於漢代牙骨器上。', N'高 6.3 公分、徑 2.3 公分', N'/media/catalog/carving/贈雕000133N000000000/display.jpg', N'/media/catalog/carving/贈雕000133N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45362?dep=U', N'CC-BY-4.0', N'骨雕填彩雲氣紋管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b09c0903-71d4-b31f-c76b-5a095fcc9510', N'贈雕000138N000000000', N'「袁君」牙印', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'私印，鈕已殘，印面略呈長方形，器呈暗綠色。鈕面陰刻白文篆書：「袁君」二字，印文刻得相當深。漢代牙製私印不乏其例，例如在西漢南越王趙昧墓葬的東側室中，即曾出土一方有「趙藍」印文的象牙印，與其共出者尚有一方南越王趙昧之右夫人的龜鈕金印。', N'長 1.4 公分、寬 1.3 公分、高 0.4 公分', N'/media/catalog/carving/贈雕000138N000000000/display.jpg', N'/media/catalog/carving/贈雕000138N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45367?dep=U', N'CC-BY-4.0', N'「袁君」牙印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('39253a8d-c0e1-95bd-1118-5ac096d376ef', N'購錢000403N000000000', N'宋通元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋 太祖', NULL, N'方孔圓錢，正面楷書「宋通元寶」4字，背面無文。', N'官方資料未提供', N'/media/catalog/coin/購錢000403N000000000/display.jpg', N'/media/catalog/coin/購錢000403N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9741?dep=U', N'CC-BY-4.0', N'宋通元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('adadb10c-e993-cc07-124e-5aef09fb5931', N'贈錢001488N000000000', N'宣統通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅製，圓形中央有方孔，一面鑄有「宣統通寶」，一面鑄有二滿文。', N'徑 1.6 公分', N'/media/catalog/coin/贈錢001488N000000000/display.jpg', N'/media/catalog/coin/贈錢001488N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9330?dep=U', N'CC-BY-4.0', N'宣統通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a54e4aeb-6bef-b795-a3b5-5b1a1c34880d', N'贈雕000190N000000000', N'羚羊角茶則', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'取一段羚羊角，磋磨細薄，一端成筒狀，並雕出一半環鈕；此外全器三分之二削除，端緣並磨出弧形。宋人嗜碾茶如浮綠螘，此器用以挑茶末入盞；以羚羊角琢磨而成，而且薄如蟬翼，實屬少見之精品。', N'長 15.9 公分、寬 3.2 公分、厚 0.1 公分', N'/media/catalog/carving/贈雕000190N000000000/display.jpg', N'/media/catalog/carving/贈雕000190N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45418?dep=U', N'CC-BY-4.0', N'羚羊角茶則 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('373a54a9-f7fb-6435-fac2-5b3cb2d34ec9', N'故畫00069700000', N'清王鑑倣倪瓚山水　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙二年（1663）', NULL, N'作者王鑑，生在明萬曆二十六（1598）年，死在清康熙十六（1677）年。江蘇太倉人。字圓照，號湘碧，自稱染香庵主，為明代學者王世貞的孫子，作官到廉州知府。善畫山水，又精通畫理。他的畫也是師學元四家，對於臨摹前人作品，有獨到之處。前人批評他是「擅長用筆，用墨濃黑滋潤，又善於著色暈染，所以，山石特別具有厚重的質感」。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'他與王時敏、王翬、王原祁，被尊為清初山水四大家，合稱「四王」。', N'78.3 × 35.8 公分', N'/media/catalog/painting/故畫00069700000/display.jpg', N'/media/catalog/painting/故畫00069700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3475?dep=P', N'CC-BY-4.0', N'清王鑑倣倪瓚山水　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dceba0e3-6f27-d7d2-d447-5bfbddca36a5', N'故玉000508N000000000', N'玉螭耳杯', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'青玉，泛赭黃色。圓杯，直壁下斂，圈足。單耳，耳雕作獸一隻，攀附口沿，末端分歧的長尾巴延伸至杯壁。', N'高 5.6 公分、口徑 7.5 公分、足徑 2.9 公分', N'/media/catalog/jade/故玉000508N000000000/display.jpg', N'/media/catalog/jade/故玉000508N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48706?dep=U', N'CC-BY-4.0', N'玉螭耳杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b37fbdb7-47c5-790d-ce26-5c1c76585640', N'中漆000015N000000000', N'木胎金漆阿彌陀佛像', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'清宮作品，十八世紀。小佛像，結跏趺坐，成禪定印。木胎雕成，外表簡單的髹塗金漆與紅藍彩。原置於漆龕內。', N'長 42.4 公分、寬 29.4 公分、通高不連佛 16.0 公分、佛高 17.3 公分', N'/media/catalog/lacquer/中漆000015N000000000/display.jpg', N'/media/catalog/lacquer/中漆000015N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18465?dep=U', N'CC-BY-4.0', N'木胎金漆阿彌陀佛像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('036486eb-1b06-c34a-cbc0-5c946c99e8e8', N'中琺000555N000000000', N'掐絲琺瑯葡萄紋壺', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，高冠式蓋，上有桃形鈕，方形流、耳形把手，把手上有鈕穿，本應有鍊子與蓋子相連，平底。全器作藍色地釉，蓋、頸、流及把手飾各式大小花葉紋，壺肩飾三如意形開光，內飾折枝花卉，開光之間飾葡萄紋，隙地則飾卷鬚紋，裝飾紋樣佈滿全器。器型非中國傳統形制，頗具回教世界風格。', N'高 22.3 公分、口徑 8.1 公分', N'/media/catalog/enamel/中琺000555N000000000/display.jpg', N'/media/catalog/enamel/中琺000555N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/265?dep=U', N'CC-BY-4.0', N'掐絲琺瑯葡萄紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fab228f7-9309-a8fc-507a-5d265d8b6177', N'購漆000002N000000000', N'剔犀如意雲紋盞托', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'高足盞托，木胎。足徑寬廣，足沿微外張，盤面弧度微向上，造型輪廓線溫和敦厚。胎體輕薄，托面中央的紅褐漆和足內褐漆，可能為後髹，托緣內外及足外為雕漆，作黑漆剔犀如意雲紋。托面圓心外圍平均分佈十二朵如意雲紋，頂部呈尖形，內作桃形，樣式單純，佈局均衡清晰。地漆帶黃色調，以斜刀深刻，切面露出深褐色漆，上、下各一紅線，用刀沈穩，線條樸實內斂，全器呈現一種理性而單純的優雅美感，具有時代特色。剔犀為宋代雕漆的主流。', N'高 5.5 公分、盤徑 17.0 公分、足徑 11.0 公分', N'/media/catalog/lacquer/購漆000002N000000000/display.jpg', N'/media/catalog/lacquer/購漆000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47873?dep=U', N'CC-BY-4.0', N'剔犀如意雲紋盞托 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('98fbde63-c9c2-9d1f-015a-5e35ba4da524', N'中琺000162N000000000', N'掐絲琺瑯轎瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'銅胎，前面為侈口，如意雲紋口緣，長頸，豐肩，斂腹，撇足瓶，足下連雕銅質木紋座，頸處雕附花卉，一樹纏繞。靠牆面平，面有一孔可以直接掛在牆面的釘上，故稱壁瓶，清檔中稱之轎瓶。此型器始見於明萬曆朝，清代盛行於乾隆時期。全器紅地，以掐絲技法於頸、腹部飾番蓮紋，圈足為海棠紋。腹部開光鍍金地填「御製」二字及詩文「分來含韻齋中韻，擅得眾香國裏香。」落「臣于敏中」紅地陰文印，「以寫葵心」鍍金地陽文填紅字。于敏中（1714-1782），乾隆二年（1737）中狀元，工書法，歷官文華殿大學士，二十五年（1760）入懋勤殿奉敕寫華嚴經寶塔，廷論多出其手。', N'寬 11.0 公分、高 26.4 公分、厚 5.6 公分', N'/media/catalog/enamel/中琺000162N000000000/display.jpg', N'/media/catalog/enamel/中琺000162N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54033?dep=U', N'CC-BY-4.0', N'掐絲琺瑯轎瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8e58ba44-89f0-1356-752b-5f1091a418b2', N'購錢001613N000000000', N'皇宋元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「皇宋元寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢001613N000000000/display.jpg', N'/media/catalog/coin/購錢001613N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10951?dep=U', N'CC-BY-4.0', N'皇宋元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0111056c-d1ab-ff6f-fb4c-5f3860fb9670', N'購錢000223N000000000', N'熙寧元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「熙寧元寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000223N000000000/display.jpg', N'/media/catalog/coin/購錢000223N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9561?dep=U', N'CC-BY-4.0', N'熙寧元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b4c6d11d-18aa-d6ca-5305-5f59a8ae8b39', N'中瓷003792N000000000', N'定窯 白瓷印花牡丹百摺盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'敞口、淺壁、折沿盤；唇沿自口部平折，外緣窄棱凸起，作五十八瓣菊瓣式花口；器壁押印同式菊瓣起伏的摺痕。平底。全器施牙白釉，口緣無釉，釉係施後刮除者，故菊瓣口側面凹痕內仍有釉，為覆燒製作的痕跡；口部外緣有沾沙痕跡。器裡印花為飾：折沿處印雙層花瓣，底面則滿佈七朵牡丹花的錦面裝飾，印痕清晰。', N'高 2.3 公分、口徑 21.3 公分、底徑 13.4 公分', N'/media/catalog/ceramic/中瓷003792N000000000/display.jpg', N'/media/catalog/ceramic/中瓷003792N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/81?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花牡丹百摺盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8bf97b19-8e0f-37e5-3964-6003435e7a92', N'購錢004613N000000000', N'洪武通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'方孔圓錢，正面有楷書「洪武通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢004613N000000000/display.jpg', N'/media/catalog/coin/購錢004613N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13951?dep=U', N'CC-BY-4.0', N'洪武通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('64bc5340-faed-9237-8810-60d3863c210f', N'故畫00038800000', N'明王紱獨樹圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明成祖永樂二年(1404)', NULL, N'王紱（西元一三六二－一四一六年），江蘇無錫人。字孟端，後以字行。號友石，又號九龍山人、青城山人。永樂間，以墨竹名天下，兼善山水。' + NCHAR(13) + NCHAR(10) + N'　　永樂甲申（一四○四），作者四十三歲，在友人沈氏自樂軒中作。凌空一石，上作老樹杈枒，盤根露節。其下則坡石似在水濱，襯以荊條竹葉。布局甚簡，而用筆圓勁，墨色濃郁，覺與吳鎮有溪壑相通處。', N'113.7 × 39.4 公分', N'/media/catalog/painting/故畫00038800000/display.jpg', N'/media/catalog/painting/故畫00038800000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3187?dep=P', N'CC-BY-4.0', N'明王紱獨樹圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('973ff089-630d-c794-9a85-60d3bb1ba19b', N'中日陶000047N000000000', N'灰陶博山爐', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'全器分器蓋、爐身及基座等三部分。器蓋頂端有一圓孔插稍。蓋頂為圓弧狀，上有十八個小孔。孔前端均飾有山狀形突起，部分已脫落。口沿處有凸稜，以區分蓋頂、口沿。爐身為半球體，口沿亦有凸稜。基座呈倒喇叭狀，柄部有兩孔，足部有三角形鏤空三個。全器平素無紋，唯足部下緣飾有三道弦紋。', N'高 24.7 公分；蓋高 8.0 公分、徑 12.5 公分；爐身高 18.0 公分、徑 12.4 公分；足徑 15.4 公分', N'/media/catalog/ceramic/中日陶000047N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000047N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71762?dep=U', N'CC-BY-4.0', N'灰陶博山爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9f39b772-9c52-5b61-5370-613a72895225', N'故畫00070200000', N'清王翬匡廬讀書圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙四十一年（1702）', NULL, N'王翬（1632-1717），江蘇常熟人。字石谷，號耕煙散人、清暉主人、烏目山人、劍門樵客。山水得王時敏指授，為清四大家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'此為康熙壬午（1702）王氏七十一歲之作。一人緣溪持杖而行，急流洄洑處有水榭數間，其上作平池兩疊，皆有樓宇。而林木森秀，磴道相通。背山微用雲煙隔斷，飛瀑瀉於其間，圖左形成大壑。一溪蜿蜒如帶，層層深入，極其幽遠。', N'171.3 × 79.5 公分', N'/media/catalog/painting/故畫00070200000/display.jpg', N'/media/catalog/painting/故畫00070200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3480?dep=P', N'CC-BY-4.0', N'清王翬匡廬讀書圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3eac63c5-7d5c-dbc8-92cf-62c53d4a42d1', N'故畫00150300000', N'元趙孟頫百祿圖　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大二年（1309）', NULL, N'本幅描寫鹿群徜徉於山水間，或飲水，或對望，各具姿態。「鹿」與「祿」同音，寓意官祿。畫中松樹代表「長壽」，山水間並點綴表徵祥瑞的靈芝與罕見白鹿，整幅畫充滿吉祥的寓意。畫面青綠色調乾淨明亮，松樹與岩石的畫法，很接近清宮畫家方琮為郎世寧〈畫青羊〉所補背景，顯示此作與清代宮廷畫風的關係。(20100710)', N'51.5 × 417.6 公分', N'/media/catalog/painting/故畫00150300000/display.jpg', N'/media/catalog/painting/故畫00150300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/955?dep=P', N'CC-BY-4.0', N'元趙孟頫百祿圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fcf21976-eb70-eeda-adcb-62f159310da9', N'購錢001598N000000000', N'宣和通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「宣和通寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢001598N000000000/display.jpg', N'/media/catalog/coin/購錢001598N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10936?dep=U', N'CC-BY-4.0', N'宣和通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8cb0e634-a740-d327-1f83-6413e03d11f8', N'中瓷000688N000000000', N'青瓷弦紋竹節瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'盤口，長直頸，碩腹，圈足。頸上凸起弦文四道。器腹中段凸起弦紋兩道。全器施青釉，釉質腴潤，釉面滿佈赭色開片紋。圈足露胎塗褐色汁。', N'高 25.3 公分、口徑 7.0 公分、底徑 9.8 公分', N'/media/catalog/ceramic/中瓷000688N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000688N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18524?dep=U', N'CC-BY-4.0', N'青瓷弦紋竹節瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a904024f-c916-5def-44fb-651cceacd801', N'贈雕000146N000000000', N'骨博箸', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'贈雕000146-000150為博箸，長條形，兩面的兩端與中央皆各陰刻一組紋飾，每組紋飾兩端各飾三道陰線，中央以雙線刻一X形，一面的X之四間隔內各陰刻一圈點紋，中心圓點填紅彩，另一面則無圈點紋；陰刻線內皆填白色顏料。器之窄側邊的兩端與中央各穿一小孔，數根博箸可串接在一起。博箸通體已染成淺綠色。', N'長 9.1 公分', N'/media/catalog/carving/贈雕000146N000000000/display.jpg', N'/media/catalog/carving/贈雕000146N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45375?dep=U', N'CC-BY-4.0', N'骨博箸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('989e97aa-d157-f537-8a4a-6534325905e3', N'中畫00002600000', N'明陳淳花卉　卷', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖二十一年（1542）', NULL, N'陳淳（西元一四八三─一五四四年），江蘇長洲人，字道復，別號白陽山人。早歲曾從學於文徵明，中年以後畫風轉變，以寫意花卉與米家山水見長，蔚為吳派畫派中的重要代表。' + NCHAR(13) + NCHAR(10) + N'本卷用水墨寫意法，分段繪折枝牡丹、繡球、辛夷、百合、蘭花、菊花、水仙、白梅等，各段並附以行草書題詩。通幅筆致變化多端，洋溢著清新秀逸的情調。款署壬寅（一五四二），為陳淳六十歲的精采傑作。' + NCHAR(13) + NCHAR(10) + N'(20121016)', N'25.9 × 454.3 公分', N'/media/catalog/painting/中畫00002600000/display.jpg', N'/media/catalog/painting/中畫00002600000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1597?dep=P', N'CC-BY-4.0', N'明陳淳花卉　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('71d8c469-d063-7131-7e15-655c4e40a65a', N'中瓷002583N000000000', N'定窯 白瓷印花奔鹿盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'盤，敞口、淺壁、臥足、平底。外壁近底處有一圈鏇修痕。器裡印花為飾，器壁飾回紋，轉枝蓮荷花葉紋各一周，花葉連續圖案間有凸點為地紋填白；底部以回紋周繞，中為奔鹿圖案，卷草枝蔓鋪陳其間。全器施牙白釉，僅口緣無釉，鑲銅棱釦，係覆燒成器。', N'高 3.1 公分、口徑 19.0 公分、足徑 12.8 公分', N'/media/catalog/ceramic/中瓷002583N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002583N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/78?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花奔鹿盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('51baa8ed-e77a-275c-eaf9-6584e0900c0e', N'故畫00147300000', N'宋馬遠畫水二十景　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'紹興十一年（1141）', NULL, N'純以流水為主題的作品，歷來並不多見。本幅以工細之筆，一絲不茍地畫水二十景，每段各有標題，包含著著名地區和事蹟中的水景，以及水之各類型態。有浪花翻騰的壯闊之美，也有水波輕漾的柔和之美，甚為多采多姿。舊傳為馬遠之作，但欠其靈活生動之意。馬遠，字欽山，宋光、寧宗朝(西元1190-1224年)畫院待詔。畫山水、人物、花卉、禽鳥，雖得家傳，然能自樹一幟。', N'25.8 × 801 公分', N'/media/catalog/painting/故畫00147300000/display.jpg', N'/media/catalog/painting/故畫00147300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/90?dep=P', N'CC-BY-4.0', N'宋馬遠畫水二十景　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e7555488-93fc-1c32-6775-65bd36c3389a', N'中銅000039N000000000', N'蟠夔紋盆', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'敞口折沿，束頸，碩腹下收，圓弧底，帶角異獸雙耳。器頸與腹上半部滿布紋飾，腹部紋飾有如將夔龍相交成缺一角的「卍」字形，但是並不明確描繪夔龍的特徵，便讓這些紋飾既有幾何形的規整，也可連結到未規整前的夔龍樣式。腹外壁下半則裝飾蟬紋。', N'高 10.5 公分、徑 22.0 公分', N'/media/catalog/bronze/中銅000039N000000000/display.jpg', N'/media/catalog/bronze/中銅000039N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53449?dep=U', N'CC-BY-4.0', N'蟠夔紋盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b7256709-e5e8-b53f-4273-65c757842677', N'中雕000011N000000000', N'雕犀角人物乘槎', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'器作一長槎形，人物鏤空凸雕而成，人物背後枝幹上方雕一蒲蘆；人物眉目清晰，右手執如意，著大袖長袍，長髯及胸；枝幹上花卉或為梅花，或是牡丹；一隻荷花帶一大荷葉自槎內伸至口緣；槎下方近底處皆浮雕波濤紋飾。槎尾端外壁浮雕陽文篆書款識：「再來華甲子，尤通」，其下接一陽文二字篆書印，印文漫渙。槎內壁淺陰刻乾隆皇帝楷書七言詩：「照渚幸而逭溫氏，刻杯仍此遇尤家；河源自在人間世，漢使訛傳星漢槎。」淺陰刻楷書款：「乾隆壬寅御題」，下方陰刻乾卦圓印與篆書「隆」字方印。乾隆壬寅乃乾隆四十七年（1782）。這首詩文也收在《清高宗御製詩文全集（八）‧御製詩四集》卷九十八‧癸卯（乾隆四十八年，1783），「詠尤通刻犀角乘槎杯」條。', N'長 27.3 公分、寬 10.2 公分、高 11.7 公分', N'/media/catalog/carving/中雕000011N000000000/display.jpg', N'/media/catalog/carving/中雕000011N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2493?dep=U', N'CC-BY-4.0', N'雕犀角人物乘槎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f1304fd2-7e86-e81f-20e5-660ed2127f95', N'贈雕000066N000000000', N'牙環', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'全器橫切一段牙材而成，內外周徑皆不規整，剖面呈方形，每面陰刻六圈點紋，其間距不等；外緣有三穿孔，可繫墜。兩面皆可見清晰的打磨時所留的平行橫線，全器並已呈深綠色。先民以牙骨質琢製成環形裝飾品的情形並不少見，在新石器時代晚期的大汶口文化遺址中即曾出現此類牙骨環，但在洛陽燒溝附近的戰國墓葬中也曾發現牙質環形器；此件牙環之器表陰刻圈點紋，或為戰國時代遺物。', N'外徑 2.9 公分、孔徑 1.7 公分', N'/media/catalog/carving/贈雕000066N000000000/display.jpg', N'/media/catalog/carving/贈雕000066N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45292?dep=U', N'CC-BY-4.0', N'牙環 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('aa8f2625-9971-5259-5eda-678f658a755f', N'中銅000174N000000000', N'梵文鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'圓鏡，橋鈕。鏡背梵文幾為銅鏽所掩。', N'直徑 9.9 公分', N'/media/catalog/bronze/中銅000174N000000000/display.jpg', N'/media/catalog/bronze/中銅000174N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7101?dep=U', N'CC-BY-4.0', N'梵文鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('72808e46-24a3-141c-4535-6859a24cb614', N'購錢001216N000000000', N'政和通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「政和通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001216N000000000/display.jpg', N'/media/catalog/coin/購錢001216N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10554?dep=U', N'CC-BY-4.0', N'政和通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2389a568-42ad-ea14-e972-6a5a63fcfb63', N'中瓷000342N000000000', N'白瓷剔花葫蘆瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'器呈葫蘆形，小圓口，束腰，圈足，製作規整。整器施釉，色牙黃，滿佈細密開片紋，外壁剔刻花紋，線條細勁，剔痕現出下層的深灰色。上下腹刻纏枝番蓮花葉，口下方刻回紋一圈，束腰處飾回紋及卷雲紋各一道，腹壁近足處刻卷雲紋一周。花紋清晰，線條流暢。圈足底端露胎，色灰白。', N'高 27.9 公分、口徑 2.6 公分、底徑 9.0 公分', N'/media/catalog/ceramic/中瓷000342N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000342N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23132?dep=U', N'CC-BY-4.0', N'白瓷剔花葫蘆瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fea4e2c9-b845-ee99-7bb1-6ad90befd643', N'南購畫00002400000', N'東海道十四 五十三次 原', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪原宿（靜岡縣沼津市）風景，畫面由右而左標示「東海道十四」、「五十三次 原」、畫面左下「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002400000/display.jpg', N'/media/catalog/painting/南購畫00002400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36479?dep=P', N'CC-BY-4.0', N'東海道十四 五十三次 原 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1);
INSERT INTO [catalog].[Artifacts] ([Id], [ArtifactRef], [Name], [CategoryId], [EraBucketId], [EraTextOriginal], [CreatorDisplay], [Description], [SizeText], [PrimaryImagePath], [ThumbnailPath], [SourceUrl], [LicenseCode], [AttributionText], [IsActive]) VALUES
    ('02368011-a6a4-c995-346c-6b1119815222', N'故漆000134N000000000', N'剔紅雙鳳牡丹圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅圓盒，色紅，漆層有裂傷。子母口，淺直壁，平底。蓋面雕飾連枝牡丹花葉，當中穿梭鳳鳥一對，器與蓋側面各雕回紋一周，本件漆層肥厚，刀法深圓。器裡與底髹黑色光漆。', N'高 3.0 公分、徑 7.2 公分', N'/media/catalog/lacquer/故漆000134N000000000/display.jpg', N'/media/catalog/lacquer/故漆000134N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18080?dep=U', N'CC-BY-4.0', N'剔紅雙鳳牡丹圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('156e9efe-d2bc-5a16-59d9-6b46035bb5c4', N'故瓷010049N000000000', N'青花五彩花卉紋十方蓋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'十邊形折面碗，帶淺盤狀蓋。全器以乳白釉為基底，加上青花、紅彩、金彩等，蓋頂與器身描繪太湖石與菊花、芙蓉花等。碗與蓋內中心為菊花紋，碗內緣繪青花隔柵配紅花。蓋與器身口稜相合，且塗有褐汁，兩者皆帶圈足，足內各有方框渦狀「福」字款，為典型「柿右衛門」樣式作品。', N'高 6.3 公分、通高 8.7 公分、口徑 14.6 公分', N'/media/catalog/ceramic/故瓷010049N000000000/display.jpg', N'/media/catalog/ceramic/故瓷010049N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/26658?dep=U', N'CC-BY-4.0', N'青花五彩花卉紋十方蓋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d14e4299-c2be-0702-375e-6b4a789f530e', N'故漆000082N000000000', N'剔紅秋葵圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'扁圓形盒，子母口，圈足，盒內及底髹褐漆。盒身四株花朵間隔著一、二片葉片。盒面中心為一葉，外圍平均分佈三朵盛開的大花，花間外各一大葉，或夾雜著花蕾，枝幹穿梭於葉上、葉下，葉片疊壓著葉片與花朵，刻意表現物象重疊的關係，使構圖顯得複雜。漆色紅潤，間露黃色地漆，刀法硬直，花瓣起伏變化較硬，中央葉脈深度變化一致，漆面打磨變化銳利，似壓花般具裝飾性。底有「大明永樂年製」六字款。', N'高 4.0 公分、口徑 10.5 公分', N'/media/catalog/lacquer/故漆000082N000000000/display.jpg', N'/media/catalog/lacquer/故漆000082N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17887?dep=U', N'CC-BY-4.0', N'剔紅秋葵圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b1b594c5-4268-0870-9755-6da621120960', N'中玉000013N000000000', N'玉鏤空牡丹三足爐', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'白玉爐，白玉泛灰黃並有赭斑。附蓋，二耳、三足。蓋上玉頂、蓋面與腹皆為鏤雕纏枝花葉，二耳也立雕花葉紋。足柱上浮雕環帶紋、回紋及蕉葉紋。器內底有浮雕盛開之花朵。', N'高 9.8 公分、帶蓋高 14.3 公分、口徑 10.8 公分', N'/media/catalog/jade/中玉000013N000000000/display.jpg', N'/media/catalog/jade/中玉000013N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52752?dep=U', N'CC-BY-4.0', N'玉鏤空牡丹三足爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ece98993-4853-3a26-bece-6ea03c5c17f1', N'故漆000081N000000000', N'剔紅茶花圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'扁圓形盒，子母口，圈足，底部及盒內髹褐漆。盒面雕折枝茶花，主枝自下緣伸展，接著一盛開的花朵，穿過圓心，向左開一大花，接著向右開一大花，盒面三朵大花平均居圓三角，其間或花蕾或小花。底有「大明永樂年製」六字款。', N'高 4.1 公分、口徑 10.5 公分', N'/media/catalog/lacquer/故漆000081N000000000/display.jpg', N'/media/catalog/lacquer/故漆000081N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17886?dep=U', N'CC-BY-4.0', N'剔紅茶花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bf1f67fc-52b2-2db5-00b5-6eb761f498c4', N'故玉006611N000000000', N'玉魚龍佩', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'玉質，全器琢成一扁平異獸形狀，帶龍首，身軀為魚形，帶魚鰭。周身佈滿魚鱗，腹底有一圓穿孔。', N'長 3.8 公分', N'/media/catalog/jade/故玉006611N000000000/display.jpg', N'/media/catalog/jade/故玉006611N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/57683?dep=U', N'CC-BY-4.0', N'玉魚龍佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4e9f6e0f-64e8-bfcd-8d4e-6f9f00182b6d', N'中瓷002223N000000000', N'哥窯 青瓷葵口洗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'敞口洗，口作九瓣花形，深直壁略斂，平底，外底略內凹。器內外滿施青釉，釉色泛青，大片冰裂紋滿覆器內外。底外滿釉，見有大致作等距分佈的支釘痕。', N'高 3.3 公分、口徑 11.8 公分、底徑 9.0 公分', N'/media/catalog/ceramic/中瓷002223N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002223N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23703?dep=U', N'CC-BY-4.0', N'哥窯 青瓷葵口洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0949f84e-865d-941b-245e-6fc8855f5308', N'中漆000077N000000000', N'剔紅八寶番蓮紋觚', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'瓶，分三段，上、下段外侈，中段圓鼓。外髹朱漆，內塗金漆。三段皆雕捲枝番蓮紋，上、下段加飾八寶紋，均襯以菱格花朵錦地紋，三段中間以蕉葉紋、回紋、變形蓮瓣紋及如意雲頭紋間隔。上、中段之際雕「大清乾隆年製」六字篆款，外加方框。為供具，一爐、二瓶、二燭台合稱「五供」，此為其中一件瓶。院藏中漆76-中漆80為一套五供。', N'高 26.8 公分、深 15.3 公分、足深 6.6 公分、口徑 16.3 公分、足徑 12.6 公分', N'/media/catalog/lacquer/中漆000077N000000000/display.jpg', N'/media/catalog/lacquer/中漆000077N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17477?dep=U', N'CC-BY-4.0', N'剔紅八寶番蓮紋觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('00d4b084-d1d1-ffce-2491-7129213e66b0', N'中琺000172N000000000', N'掐絲琺瑯鼎', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'直口，雙立耳，深壁，分檔底，三足，帶階式蓋，鏤空雲龍紋鈕。全器以淺藍色為地，以掐絲技法於全器飾回紋錦地，蓋沿及腹壁外飾獸面紋，口沿下方頸部四面出脊，外壁掐飾魚龍紋，器底飾葵花紋，足飾幾何紋。器底外有掐絲琺瑯「乾隆年製」四字二行楷款。', N'徑 19.4 公分', N'/media/catalog/enamel/中琺000172N000000000/display.jpg', N'/media/catalog/enamel/中琺000172N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54042?dep=U', N'CC-BY-4.0', N'掐絲琺瑯鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('214b862f-775b-2192-dc97-718139265b08', N'中銅000016N000000000', N'雷紋觶', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'扁口，器物截面為橢圓形，頸飾雲雷紋，圈足飾目雷紋，頸足各飾雷紋一道。清宮舊藏，收入《西清續鑑·乙編》卷十二頁九，著錄作｢漢雷紋觶｣。', N'高 15.5 公分', N'/media/catalog/bronze/中銅000016N000000000/display.jpg', N'/media/catalog/bronze/中銅000016N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6879?dep=U', N'CC-BY-4.0', N'雷紋觶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('610e11d0-fe40-4777-a646-71f96334e3e7', N'故漆000113N000000000', N'剔紅茶花盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅圓盒，朱漆黃素地，鮮艷有光澤，漆層略有剝損。子母口，淺直壁，平底。全器雕飾多種連枝花卉，花瓣枝葉舒捲自然，層次豐富嚴謹。器裡與底髹黑色光漆，底面邊側有直書刀刻填金楷書「大明宣德年製」。', N'高 9.6 公分、徑 31.7 公分', N'/media/catalog/lacquer/故漆000113N000000000/display.jpg', N'/media/catalog/lacquer/故漆000113N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18059?dep=U', N'CC-BY-4.0', N'剔紅茶花盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('70faecdb-fb91-0281-250a-723114a20c73', N'中琺000863N000000000', N'掐絲琺瑯玉壺春', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。撇口，長頸，溜肩，垂腹，圈足外撇。以掐絲技法、琺瑯料填色製作花紋，口沿飾蕉葉紋，全器飾纏枝番蓮紋及石榴紋，腹部下緣飾一圈蓮瓣紋，圈足飾纏枝菊花紋。', N'高 55.1 公分、深 50.9 公分、口徑 15.0 公分、底徑 21.2 公分、腹圍 109.1 公分', N'/media/catalog/enamel/中琺000863N000000000/display.jpg', N'/media/catalog/enamel/中琺000863N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54686?dep=U', N'CC-BY-4.0', N'掐絲琺瑯玉壺春 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a600247c-6f37-5efe-bd7b-7286dd0975ce', N'購瓷000002N000000000', N'邢窯 白釉玉璧足茶碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'敞口捲唇，斜壁，淺腹，玉璧形底足。內壁滿施白釉，外壁掛釉不及底，底部無釉。白釉瑩潤，聚釉處泛青，胎質細膩堅緻。敞口、玉璧足的淺碗為唐代中晚期典型茶碗形制，最有名者莫過於越窯青瓷玉璧足茶碗，及邢窯玉璧足茶碗，兩窯皆為陸羽《茶經》所載。雖然《茶經》以越窯青瓷茶碗為尚，但首都長安或洛陽墓葬或寺院遺址所出土者，仍以邢窯白釉茶碗為多。同類型茶碗或「盈」字款邢窯白釉玉璧足茶碗，長安西明寺、洛陽白居易邸宅等遺址均有發現。', N'高 4.2 公分、口徑 14.4 公分、足徑 6.0 公分', N'/media/catalog/ceramic/購瓷000002N000000000/display.jpg', N'/media/catalog/ceramic/購瓷000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1075?dep=U', N'CC-BY-4.0', N'邢窯 白釉玉璧足茶碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a40879cc-7568-a5f1-abe5-72e4af74281b', N'故琺000318N000000000', N'掐絲琺瑯簋式爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。束頸碩腹，鍍金鳳鳥雙耳，圈足外撇，腹至足部前後出棱脊。蓋之抓手鏨為蓮瓣形，蓮瓣內鏤空以異獸為飾。全器以掐絲技法、琺瑯料填色為飾，淺藍釉地，蓋面飾纏枝花卉及拐子龍，器腹飾纏枝花卉紋與獸面紋。', N'長 17.0 公分、高 26.6 公分、深 12.5 公分、口徑 23.5 公分、足徑 16.6 公分', N'/media/catalog/enamel/故琺000318N000000000/display.jpg', N'/media/catalog/enamel/故琺000318N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61433?dep=U', N'CC-BY-4.0', N'掐絲琺瑯簋式爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9e4d4bc8-c9fa-b448-6659-73246b2c5677', N'贈錢001265N000000000', N'光緒元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。正面有楷書：「光緒元寶」四字，外圈有「浙江省造」、「十當」及滿文二字。背面有紋飾。', N'待測量', N'/media/catalog/coin/贈錢001265N000000000/display.jpg', N'/media/catalog/coin/贈錢001265N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9088?dep=U', N'CC-BY-4.0', N'光緒元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d6a22d22-4ab2-86e6-413b-7348318997c3', N'贈雕000059N000000000', N'牙龍紋璜', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'扁平弧形，中段較寬，一端雕成龍首形，另一端尖銳作龍尾；龍首以圈點紋為眼紋，張口，淺浮雕三角形為龍角，龍身分成五段，每段陰刻三道弦紋，弦紋間陰刻斜線，其後交叉陰刻十數道斜線；第一段三道弦紋間斜線較精刻，是為所謂綯紋之紐絲紋。器窄內側鑿二小凹槽，全器已染成綠色。有一面顏色較深，或因較接近墓中銅器所致。', N'長 9.8 公分、寬 1.0 公分、厚 0.5 公分', N'/media/catalog/carving/贈雕000059N000000000/display.jpg', N'/media/catalog/carving/贈雕000059N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45285?dep=U', N'CC-BY-4.0', N'牙龍紋璜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4e7f86b7-ae47-1ccf-acc2-74024406784e', N'中銅000094N000000000', N'子己冊角', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'深腹卵形底，獸首鋬，三足截面作三角形，足背較寬。壁面飾獸面紋，雲雷紋為地。銘文位於鋬後。', N'通高 21.5 公分、寬 16 公分', N'/media/catalog/bronze/中銅000094N000000000/display.jpg', N'/media/catalog/bronze/中銅000094N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53471?dep=U', N'CC-BY-4.0', N'子己冊角 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f63990d0-0f23-b5e4-7281-74095b2fd2a7', N'故玉001304N000000000', N'雙龍首玉珩', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋中晚期', NULL, N'玉質，微有赭斑。器近璜形而較平直，器身滿琢雲紋為飾，中間上下邊及龍口處亦琢飾繩紋。兩端作龍首，器有三穿，一在器正中上方處，另兩穿在龍口。', N'長 11.1 公分、寬 2.2 公分、厚 0.4 公分', N'/media/catalog/jade/故玉001304N000000000/display.jpg', N'/media/catalog/jade/故玉001304N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/49429?dep=U', N'CC-BY-4.0', N'雙龍首玉珩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bf1c5321-30e7-b638-27fc-7450cb0c6d6a', N'中漆000062N000000000', N'剔彩山水人物圖六方花盆', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'六方形花盆，黃、綠色雕漆錦地，面髹紅色漆，器身略有傷裂。廣口外撇，深壁，平底，下接六如意形足。器壁六面開光，四周雕飾番蓮花，內雕山水人物樹石，人物多持桃實靈芝，有長壽吉祥之意，開光外餘地刻滿綠框紅花斜方朵花錦地紋。盆內壁露木胎未加髹飾。', N'通高 16.6 公分、深 13.8 公分、口徑長 31.9 公分、寬 28.1 公分、足徑 18.6 公分、寬 16.6 公分', N'/media/catalog/lacquer/中漆000062N000000000/display.jpg', N'/media/catalog/lacquer/中漆000062N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17523?dep=U', N'CC-BY-4.0', N'剔彩山水人物圖六方花盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3e9dbb50-62e1-fb39-a632-748a25519809', N'中漆000055N000000000', N'剔紅八仙慶壽人物筆筒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'垂直筆筒，底有三足，口沿米字形錦地帶狀飾。器身雕八仙慶壽，構圖分成三段，近景為小丘，鶴、鹿漫步。中段八仙成列，以張果老為首，手捧壽桃，獻給上方的西王母。八仙中第二位漢鍾離手放異光，第四位李鐵拐的葫蘆放煙上天，和行列後方的松樹直上雲霄，打破中段與上段的區隔。西王母騎鳳，前後侍者擁立，畫面熱鬧。漆層厚，漆色暗紅，錦地之上復刻叢樹、雲朵，再上層為人物，雕刻層次多，用刀直陡，甚具特色。', N'高 9.8 公分、深 9.4 公分、口徑 5.0 公分、足徑 4.9 公分', N'/media/catalog/lacquer/中漆000055N000000000/display.jpg', N'/media/catalog/lacquer/中漆000055N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17459?dep=U', N'CC-BY-4.0', N'剔紅八仙慶壽人物筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5c9abf69-2b18-0803-12c5-7587017e5bee', N'中玉000001N000000000', N'玉三足爐', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'仿古青玉鼎式爐，三獸蹄形足，紋飾以回紋為地，並有變形鳳鳥紋。附後配之木蓋，木蓋上為元代汀渚鷺鷥紋玉頂。', N'高 7.5 公分、口徑 8.9 公分', N'/media/catalog/jade/中玉000001N000000000/display.jpg', N'/media/catalog/jade/中玉000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52737?dep=U', N'CC-BY-4.0', N'玉三足爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('06171186-2de7-5176-7621-75976720ae1d', N'中銅000007N000000000', N'三角雲紋壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'撇口，長頸，斜肩，圓腹，高圈足，器肩兩側有獸首銜環。器身飾三帶紋，肩、腹及足共飾三角雲紋四道，各圍以綯紋，頸飾三角蟬紋及雲紋。著錄於《西清續鑑‧乙編》卷九頁九，作「周獸環壺六」。', N'高 30.4 公分', N'/media/catalog/bronze/中銅000007N000000000/display.jpg', N'/media/catalog/bronze/中銅000007N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6081?dep=U', N'CC-BY-4.0', N'三角雲紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6d1dea08-8a04-fcbd-cb71-77a0fe26874f', N'故漆000119N000000000', N'剔紅祿位高昇人物圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，子母口，平底無足，盒內髹黑漆。盒身與盒蓋分別刻錦地人物與花卉。盒底雕折枝茶花，主幹轉折穿過盒心，上下各一主花，刻意保留刀痕，枝幹轉折有力，花與葉的輪廓線條圓韌有勁，以嶔側的刀法製造出陰影的效果。漆色紅偏暗，漆層不厚，不重打磨，反而表現刀痕，刀法靈活，非常具有個性。盒蓋中央立一手持笏、頭戴官帽、身著官服者，他身側還有一隻鹿，象徵祿位高昇的吉祥意涵，畫面高聳一太湖石，石形奇特，石後一松樹，石與松猶如人物的背屏與傘蓋，還有浮雲三、四，雲形半現半隱入盒側。構圖巧妙，物象掌握精到，刀法肯定，用刀如筆，俐落生動。', N'高 4.0 公分、徑 7.2 公分', N'/media/catalog/lacquer/故漆000119N000000000/display.jpg', N'/media/catalog/lacquer/故漆000119N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18065?dep=U', N'CC-BY-4.0', N'剔紅祿位高昇人物圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1744d725-242b-b8bb-618e-77c37a4d4c8f', N'中玉000010N000000000', N'玉壽字簋形爐', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'玉簋式爐，雙耳，圈足。耳飾獸首，下有小珥。器身飾圓乳丁，中央為「壽」字紋。有後配之鏤空木蓋，木蓋上為元代鳧荷⽟頂。', N'通寬 12.0 公分、爐高 5.2 公分、口徑 7.4 公分、底徑 4.4 公分', N'/media/catalog/jade/中玉000010N000000000/display.jpg', N'/media/catalog/jade/中玉000010N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52748?dep=U', N'CC-BY-4.0', N'玉壽字簋形爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('468bd1e2-599c-e951-b99a-781b51822928', N'故漆000344N000000000', N'剔紅花鳥圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，子母口，盒內髹黑漆，盒內清宮原置玉璲。盒身與盒蓋均為茶花、梅花，盒蓋中央一鳥，枝葉並延伸至盒側。盒蓋以梅幹直切中間線，中央一鳥翹首棲於枝幹上，梅花盛開在上方，茶花盛開在下方，空間雖小，卻十分豐富。盒底的構圖方式相同，枝幹居中，中央為花苞，茶花自右下角斜切，兩朵盛開的茶花，豐富下部空間。漆色紅潤，底滿鋪錦地，刀法純熟，漆面略打磨，漆質堅實，可屬佳品。', N'徑 7.26 公分', N'/media/catalog/lacquer/故漆000344N000000000/display.jpg', N'/media/catalog/lacquer/故漆000344N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48319?dep=U', N'CC-BY-4.0', N'剔紅花鳥圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e18fa4ae-c76e-9934-8a23-78ee0c20f26f', N'故漆000339N000000000', N'剔彩雲龍紋圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'圓盒，拱頂，圈足，盒內清宮加一木製淺承盤，盒內、盒底髹黑漆。盒身飾龍行山水之間，龍身一黃一紅相間，一昂首一回首，龍紋之下為連續回紋，之上為連續花形三角錦地，再上為唐草紋。盒蓋分內外兩圈，兩圈之間雕帶狀花形錦地，外圈為山水行龍。盒面內圈一龍張牙舞爪，邁步向前，龍之下方波浪紋錦地，再雕山與海。龍之上方一圓形乾坤卦，雲紋散佈。色彩以紅色為主，綠次之。龍形簡化，麟片作捲渦狀，刀痕清晰，表情誇張，胎重，漆色暗沈，粗率不精。底有「大明嘉靖年製」六字款。', N'徑 23.0 公分', N'/media/catalog/lacquer/故漆000339N000000000/display.jpg', N'/media/catalog/lacquer/故漆000339N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48312?dep=U', N'CC-BY-4.0', N'剔彩雲龍紋圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('75c382bf-0593-8275-2dcc-7940a414454e', N'購錢000734N000000000', N'祥符通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「祥符通寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000734N000000000/display.jpg', N'/media/catalog/coin/購錢000734N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10072?dep=U', N'CC-BY-4.0', N'祥符通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f75e71f5-b98c-84f0-59bb-79461aac8c81', N'中銅000790N000000000', N'太師望鼎', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'帶蓋圓鼎，子母口，附耳，蹄足，蓋附三環形鈕。腹飾變形環帶紋，間飾繩紋，下飾蟬紋，蓋飾變形環帶紋，耳飾繩紋。蓋及器有銘二行六字。', N'高 33.4 公分', N'/media/catalog/bronze/中銅000790N000000000/display.jpg', N'/media/catalog/bronze/中銅000790N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5730?dep=U', N'CC-BY-4.0', N'太師望鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('037bd3d7-8c01-130a-8c44-79e2dce6c16e', N'贈錢001178N000000000', N'乾道元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'方孔圓錢。「乾道元寶」有篆、楷兩種字體，又有銅、鐵兩種材質。此枚銅錢正面有楷書「乾道元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/贈錢001178N000000000/display.jpg', N'/media/catalog/coin/贈錢001178N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9001?dep=U', N'CC-BY-4.0', N'乾道元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('47dadfb9-d49f-c6e7-cf90-7a39fddb7bf8', N'中銅000117N000000000', N'□簋', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'敞口折沿，深壁略收，圓弧底，高足。外壁紋飾分為上下兩部份，上層窄如束頸，下層廣包腹外壁。下層以直接相交為網紋，每一四邊形網眼中，都沿著邊廓飾回紋一圈，網眼中央則凸起乳釘。上層以凸棱、獸面等距分割器面，飾以雲雷紋地夔龍。足脛外紋樣設計與之類同，只是純以凸棱分割壁面而未見獸首。銘文位於器底心。', N'高 17.7 公分、徑 24.7 公分', N'/media/catalog/bronze/中銅000117N000000000/display.jpg', N'/media/catalog/bronze/中銅000117N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53470?dep=U', N'CC-BY-4.0', N'□簋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('04198293-8b90-7785-5b07-7a817b381cdc', N'購錢001204N000000000', N'至和元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「至和元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001204N000000000/display.jpg', N'/media/catalog/coin/購錢001204N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10542?dep=U', N'CC-BY-4.0', N'至和元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8fc7d462-c3e8-f577-0b39-7af5b37c9cbb', N'故漆000025N000000000', N'剔紅放鶴圖圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，子母口，圈足，底部及盒內髹黑漆。盒面為庭園人物圖。畫面以欄杆區隔出前景，左側奇石聳立，林木茂密，石後一樓閣，一人半開門而出，柳樹立於畫面中央，樹下二人、一童子面對著一隻回首張翅的鶴，呼應著柳樹梢自天空俯衝而下的另一隻鶴。畫面漆層明顯分為二層，底層為錦地紋，包含中景的水波紋，和遠景的回紋，是承襲十五世紀以來的作法。底層之上為山石人物樹木，表面刻劃石頭紋理、樹葉形態等，刻痕淺，物象平板，尤其畫面右側石頭的造型重覆，柳樹長葉的結組固定，雲紋亦規格化，與明初風格迴異。盒側為轉枝花卉，茶花、牡丹、菊花、梔子花，兩兩成組，枝葉作波浪狀，雖承永樂風格，然花朵下方擠入枝葉，花形亦大為不同。綜合略顯拙鈍的用工與漆層層次的處理，當為晚明風格。', N'高 7.0 公分、徑 19.0 公分', N'/media/catalog/lacquer/故漆000025N000000000/display.jpg', N'/media/catalog/lacquer/故漆000025N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18150?dep=U', N'CC-BY-4.0', N'剔紅放鶴圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ee6e43fa-d1b2-f9e9-1f4a-7b0373a67781', N'中銅000106N000000000', N'廿六年詔橢量', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '561e3931-1096-c637-9eb3-b5c5ce02c88f', N'秦', NULL, N'橢圓形，有鋬柄。外壁有銘四十字：「廿六年皇帝盡并兼天下諸侯，黔首大安，立號為皇帝，乃詔丞相狀、綰，法度量則，不壹，歉疑者，皆明壹之。」記秦王政在位的第二十六年（西元前221），統一了各國諸侯，百姓得到安寧，建立尊號為「皇帝」。於是詔示丞相隗狀與王綰制定標準的度量，使不統一、有疑問的、都能明確劃一。秦始皇廢封建，立郡縣，集權中央是奠定在制度統一的基礎上。秦始皇「一法度、衡石丈尺、車同軌、書同文」的措施，見證於秦始皇頒布的統一度量衡的詔書，鑄刻在大批製作的度量衡標準器上，秦量上即載此詔。《史記》記載秦始皇的丞相隗林，參之秦量銘，方知「林」為「狀」之誤。金文考史，本器銘是一個很好的例證。', N'長 21.9 公分、高 6.2 公分、深 6.07 公分、口徑長 17.1 公分、寬 9.2 公分', N'/media/catalog/bronze/中銅000106N000000000/display.jpg', N'/media/catalog/bronze/中銅000106N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47082?dep=U', N'CC-BY-4.0', N'廿六年詔橢量 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c27b451f-1c20-0097-97af-7b7dcc5842ff', N'故畫00069300000', N'清王鑑倣黃公望煙浮遠岫圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙十四年（1675）', NULL, N'王鑑（西元一五九八至一六七七年）江蘇太倉人。字圓照，號湘碧，自稱染香庵主。王世貞之孫，仕至廉州知府，精通畫理，山水為清四大家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'清初四王特愛黃公望，此幅構景近似王時敏仿黃公望山水軸．與浮嵐暖翠亦有相類處，惟佈局略有鬆散之感。作於乙卯夏日，即康熙十四年（西元一六七五），圓照已至七十八高齡。', N'134.9 × 78.9 公分', N'/media/catalog/painting/故畫00069300000/display.jpg', N'/media/catalog/painting/故畫00069300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3471?dep=P', N'CC-BY-4.0', N'清王鑑倣黃公望煙浮遠岫圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('22c6dbd3-4ac1-9850-ee4c-7c775d4a846c', N'中銅000045N000000000', N'義楚耑', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'耑，敞口、長頸、垂腹、圈足。器外壁有銘文五字：義楚之祭耑。', N'高 20.3 公分', N'/media/catalog/bronze/中銅000045N000000000/display.jpg', N'/media/catalog/bronze/中銅000045N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6981?dep=U', N'CC-BY-4.0', N'義楚耑 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e40a96e5-8493-a423-69c4-7e5e2d467753', N'購玉000344N000000000', N'玉四牙璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'玉質，淡綠色帶暗褐色斑，有白綹，半透明。環形，外緣等距離突飾四組鉏牙，其中一組有斷傷；環形本體為西北風格者，一面有淺的切割截口，另一面平整。表面光素，黏附土質物。', N'外徑 8.3 公分、孔徑 6.2 公分、厚 0.3 公分', N'/media/catalog/jade/購玉000344N000000000/display.jpg', N'/media/catalog/jade/購玉000344N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2537?dep=U', N'CC-BY-4.0', N'玉四牙璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2e31d4a8-78d3-9a2e-2abb-7e64807f59a5', N'故畫00068400000', N'清王時敏倣黃公望山水　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙九年（1670）', NULL, N'王時敏（西元一五九二－一六八○年），江蘇太倉人。字遜之，號煙客，又號西廬老人、西田主人、偶諧道人、歸村老農等。生既天資穎異，加上好學精勤，家中又富於收藏，所以博學淹雅，除善詩文書法外，對於山水畫特有領悟，一生尊崇黃公望，精研力學其畫法，獲得出藍之稱譽。他的畫以構圖複雜為特色，重山峻嶺、千村萬樹，都能安排得層次井然，令人宛然有身入實境之感。', N'147.8 × 67.4 公分', N'/media/catalog/painting/故畫00068400000/display.jpg', N'/media/catalog/painting/故畫00068400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3462?dep=P', N'CC-BY-4.0', N'清王時敏倣黃公望山水　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('309c81e7-7371-9273-6618-7e820e503ab8', N'中玉000373N000000000', N'玉圓形水盛', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'玉質，青色，有褐紅色斑。圓形似缽，縮口，歛腹。口沿下三分之一處琢一道弦紋。附玉杓。', N'高 3.6 公分、腹徑 4.2 公分', N'/media/catalog/jade/中玉000373N000000000/display.jpg', N'/media/catalog/jade/中玉000373N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53127?dep=U', N'CC-BY-4.0', N'玉圓形水盛 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4be63352-6d15-efbf-11a6-7f0c92a471e4', N'購玉000466N000000000', N'玉帶板', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'玉質，嵌入銅件中。玉帶板上琢西域胡人樂師，手持鈴鼓。', N'長 5.0 公分', N'/media/catalog/jade/購玉000466N000000000/display.jpg', N'/media/catalog/jade/購玉000466N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52377?dep=U', N'CC-BY-4.0', N'玉帶板 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d8489a1a-ea0e-35ca-96c6-7fe315c9365b', N'故玉003122N000000000', N'玉龍佩（紋飾後加）', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋晚期', NULL, N'虎形，器側有一小穿孔。器面淺浮雕雲紋，在雲紋之上再加刻平行細線紋，據細線紋的刻法，乃清乾隆時期常用的剛玉作刀的戳刻法，因此推測細紋乃為清代所加，而原器可能為春秋戰國時淺浮雕雲紋的琥。據《考古圖》畫有類似之物。', N'長 9.72 公分、通寬 6.4 公分、厚 0.5 公分', N'/media/catalog/jade/故玉003122N000000000/display.jpg', N'/media/catalog/jade/故玉003122N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/386?dep=U', N'CC-BY-4.0', N'玉龍佩（紋飾後加） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8a2a458b-8ce7-95c1-c090-802699f6e759', N'贈雕000128N000000000', N'骨雕三鳥紋嵌片', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'將骨材磨成一橢圓形，正面細線陰刻三鳥，頭向中心，中心則細線陰刻一個三瓣之朵花紋，朵花紋之花瓣又延伸出一細陰線，穿過兩鳥紋間達器緣，近器緣處又各飾一雲紋。朵花紋、鳥紋與雲紋內皆陰刻短斜線紋，並填紅彩為飾。', N'長 4.3 公分、寬 3.4 公分', N'/media/catalog/carving/贈雕000128N000000000/display.jpg', N'/media/catalog/carving/贈雕000128N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45357?dep=U', N'CC-BY-4.0', N'骨雕三鳥紋嵌片 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('32356454-519a-f12d-e18c-80d65f0c5595', N'中雕000010N000000000', N'雕犀角花籃', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'〈犀角雕花籃〉及〈犀角雕梅樹香插〉（中雕9、中雕10），是造型罕見的犀角雕，一件雕仿竹編提籃，提把可活動，籃中探出鏤雕梅枝水仙，刻工質樸。另一件鏤雕老幹虯枝的梅樹，梅花含苞待放，樹幹中空可做香插，刀法純熟。兩件成組被置於紫檀木座上，一深一淺，是質樸與清雅兼具的陳設。', N'高 9.5 公分、口徑 7.5 公分、底徑 5.0 公分', N'/media/catalog/carving/中雕000010N000000000/display.jpg', N'/media/catalog/carving/中雕000010N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18529?dep=U', N'CC-BY-4.0', N'雕犀角花籃 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('197bf3b1-ef69-be8b-d7b9-8147f6525977', N'中漆000057N000000000', N'剔黑嵌玉卷書式几', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'卷書式几，兩端內捲，下有兩足外撇。全器髹黑漆，正面剔黑萬字紋，邊雕回紋。背面週邊以金屬鑲白玉一層，兩端隨器形內捲，末端夾在黑漆之間，對比的顏色形成特殊的美感。', N'長 40.8 公分、寬 20.7 公分、高 8.6 公分', N'/media/catalog/lacquer/中漆000057N000000000/display.jpg', N'/media/catalog/lacquer/中漆000057N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17461?dep=U', N'CC-BY-4.0', N'剔黑嵌玉卷書式几 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4481ed40-d771-503c-c179-819e35ea1ad0', N'南購畫00001500000', N'東海道五 五十三次 程谷', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪程谷宿（程ヶ谷宿，又名「保土谷宿」（保土ヶ谷宿），神奈川縣橫濱市保土谷區）風景，畫面由右而左標示「東海道五」、「五十三次 程ヶ谷」、畫面橋右下角副題「かたびら橋 かたびら川」、畫面左下角「廣重画」，畫面框外右下角「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001500000/display.jpg', N'/media/catalog/painting/南購畫00001500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36470?dep=P', N'CC-BY-4.0', N'東海道五 五十三次 程谷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4ae790af-361e-30cd-73bb-821665c1c23c', N'故畫00042100000', N'明宣宗畫花下貍奴圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明宣宗宣德元年（1426）', NULL, N'宣宗（西元一三九九─一四三五年）姓朱，名瞻基。明成祖長孫，明代第五位皇帝，年號宣德。宣宗雅尚詞翰繪事，於書畫之作，隨意自然，往往與宣和爭勝。' + NCHAR(13) + NCHAR(10) + N'此圖繪文石、野菊，二貍奴戲於石下。畫家先填染底色，再鈎描皴擦毛髮及斑紋。太湖石先以筆勾勒輪廓，再以乾筆皴擦石面，畫菊則以細筆勾勒敷彩。此幅畫貓頗有追彷宣和畫院畫家李迪之風貌，具有清新優雅的氣息。', N'41.5 × 39.3 公分', N'/media/catalog/painting/故畫00042100000/display.jpg', N'/media/catalog/painting/故畫00042100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3220?dep=P', N'CC-BY-4.0', N'明宣宗畫花下貍奴圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1e6719af-191e-b3a1-eb68-83c765c71b7d', N'中漆000067N000000000', N'剔紅博古花卉龍紋方勝盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅方勝式套盒，色硃紅。平頂蓋，子母口，矮直壁，平底，淺足座。蓋面以波濤紋為地雕雙龍戲珠，珠作團壽字，並以回紋為邊，蓋與三層套盒壁各有六處開光，內雕瓶、筆筒、寶盆等博古圖，紋間填飾斜方朵花錦地紋，開光外雕飾番蓮花。座亦為方勝形，面黃漆素地雕紅萬字錦，有如意形足六。器裡與底髹黑色光漆。', N'長 28.0 公分、寬 19.8 公分、通高 22.3 公分、各層高 4.6 公分', N'/media/catalog/lacquer/中漆000067N000000000/display.jpg', N'/media/catalog/lacquer/中漆000067N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17533?dep=U', N'CC-BY-4.0', N'剔紅博古花卉龍紋方勝盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('26e185a6-4706-5cf6-8bbb-83ce6b4c1515', N'故琺000619N000000000', N'掐絲琺瑯三多瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'瓶，撇口，長頸，梨腹，圈足。銅胎，外壁飾藍地五彩掐絲琺瑯。瓶腹裝飾佛手、桃樹和石榴樹花果，並佈列品字雲紋和蝴蝶穿梭其間，腹下方有湖石及仰蓮瓣紋一圈，圈足飾五瓣花朵。', N'高 42.5 公分、腹徑 23.0 公分', N'/media/catalog/enamel/故琺000619N000000000/display.jpg', N'/media/catalog/enamel/故琺000619N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1528?dep=U', N'CC-BY-4.0', N'掐絲琺瑯三多瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('83a9fddb-80ad-d58c-ad10-8418b261e978', N'中琺000020N000000000', N'掐絲琺瑯盒', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'蒸餅式盒，子母口，深壁，圈足，子母口蓋。全器藍地，器內施藍釉，以掐絲技法於蓋緣、口緣飾如意雲紋，蓋面與腹飾番蓮紋，足飾幾何紋。', N'高 6.5 公分、盒口徑 7.8 公分', N'/media/catalog/enamel/中琺000020N000000000/display.jpg', N'/media/catalog/enamel/中琺000020N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53897?dep=U', N'CC-BY-4.0', N'掐絲琺瑯盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a24cee0c-271c-3e3b-d8cc-8423f6c4ede0', N'故玉000004N000000000', N'玉劍鐔（琫）', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'玉質，中空，器表為仿漢代的獸面紋。劍鐔是作為劍身與劍柄之間的間隔，本器為仿戰國晚期至西漢的作品。', N'長 4.32 公分、寬 2.1 公分', N'/media/catalog/jade/故玉000004N000000000/display.jpg', N'/media/catalog/jade/故玉000004N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48202?dep=U', N'CC-BY-4.0', N'玉劍鐔（琫） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7463a5e2-a78a-d703-78a1-84b57a76435a', N'故漆000109N000000000', N'剔紅人物圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅小盒，色磚紅，漆層有多道深裂痕。子母口，淺直壁，平底內凹。蓋面雕庭院敞軒，高士攜僕訪友，器與蓋側面雕滿番蓮花葉。器裡與底髹黑色光漆。', N'高 3.2 公分、徑 8.0 公分', N'/media/catalog/lacquer/故漆000109N000000000/display.jpg', N'/media/catalog/lacquer/故漆000109N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18055?dep=U', N'CC-BY-4.0', N'剔紅人物圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9109c596-5588-5c8d-f538-86b538a78097', N'中瓷000033N000000000', N'粉彩蟠桃天球瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'瓷胎天球瓶，直口，長頸部向下微斂，寬圓肩，碩圓腹，矮圈足。全器外壁以粉彩描繪桃枝連連、桃花錦簇及桃實飽滿。構圖佈局生動，設色雅麗，釉彩粉嫩可以見到顆粒狀浮起，足底緣未上釉露白胎。器外底部書有「大清乾隆年製」青花篆書款識。琺瑯彩瓷指的是使用琺瑯料，以混容中西繪法進行裝飾的瓷器，生產地位於清宮中造辦處，也稱為瓷胎畫琺瑯。洋彩瓷則是在江西景德鎮御窯廠生產，部分使用琺瑯料進行裝飾的瓷器。至於粉彩，是清末民初時對洋彩作品出現的一種新的稱呼。', N'高 50.5 公分、口徑 11.0 公分、底徑 18.0 公分', N'/media/catalog/ceramic/中瓷000033N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000033N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18995?dep=U', N'CC-BY-4.0', N'粉彩蟠桃天球瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bbfa8194-8f04-47e6-5255-88005b0e08b5', N'中銅000012N000000000', N'竊曲紋簋', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'附鈕蓋、圈足鈕、子母口、雙環耳、圓腹、圈足，耳做獸首形，下有附珥，圈足下有三小獸面足。蓋沿與口沿各有一圈有目竊曲紋飾帶，蓋與器腹飾瓦紋，圈足則飾垂鱗紋。', N'高 23.7 公分', N'/media/catalog/bronze/中銅000012N000000000/display.jpg', N'/media/catalog/bronze/中銅000012N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5821?dep=U', N'CC-BY-4.0', N'竊曲紋簋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4d892ee0-01a3-695b-18d1-881549aa8d91', N'中雕000001N000000000', N'犀角雕螭紋觥', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'滿雕為數眾多且姿態各異螭龍於犀角觥上，螭龍由器底向上攀爬，或回首、或仰望、或探頭， 且雕刻由淺而深、由浮雕而透雕， 整體充滿動態張力，底刻篆書「子孫永寶」四字。配有透雕龍鳳紋木座。', N'長 17.7 公分、寬 10.5 公分、高 13.0 公分', N'/media/catalog/carving/中雕000001N000000000/display.jpg', N'/media/catalog/carving/中雕000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14930?dep=U', N'CC-BY-4.0', N'犀角雕螭紋觥 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d0dedbb4-f387-a3ff-1518-88b5887040db', N'購錢001041N000000000', N'元祐通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「元祐通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001041N000000000/display.jpg', N'/media/catalog/coin/購錢001041N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10379?dep=U', N'CC-BY-4.0', N'元祐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fb12acad-08bd-9e8f-18a8-8992435e2bdd', N'中瓷000338N000000000', N'白瓷雙魚水波紋暗花洗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'金至元', NULL, N'敞口大洗，弧形深壁，平底，凹下寬平具邊棱，圈足，口外壁凸唇沿。全器施牙白色釉，釉色瑩潤。口緣無釉，鑲銅棱釦，足端亦無釉露胎，色灰。內底飾劃花雙魚，線條輕淺。', N'高 4.8 公分、口徑 27.5 公分、底徑 15.4 公分', N'/media/catalog/ceramic/中瓷000338N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000338N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23128?dep=U', N'CC-BY-4.0', N'白瓷雙魚水波紋暗花洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2633ec36-2ec7-2fa3-4a28-8993b8dda02b', N'南購畫00001700000', N'東海道七 五十三次 藤澤', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪藤澤宿（神奈川縣藤澤市）風景，畫面由右而左標示「東海道七」、「五十三次 藤澤」、畫面右側建築內「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001700000/display.jpg', N'/media/catalog/painting/南購畫00001700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36472?dep=P', N'CC-BY-4.0', N'東海道七 五十三次 藤澤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dc0f1e71-9c7c-c4db-ad02-89a5cd124370', N'贈錢001271N000000000', N'日本錢幣', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '4feb18c3-ce05-4ccd-4a62-237658459e77', N'日本 明治時代', NULL, N'圓錢，正面楷書：「大日本明治九年」「1 SEN」；背面「一錢」「百枚換一圓」。正面中央有草葉紋飾，背面文字被圍繞在花草紋中。', N'待測量', N'/media/catalog/coin/贈錢001271N000000000/display.jpg', N'/media/catalog/coin/贈錢001271N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9094?dep=U', N'CC-BY-4.0', N'日本錢幣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('37fd2763-4872-9951-ae96-89c535984cd5', N'故琺000726N000000000', N'掐絲琺瑯雙耳方瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯，四方形，直口，長頸，雙鳥形耳，斜肩，斂腹，外撇圈足。器表藍地，口緣飾一圈朵雲紋，肩部飾花朵紋，頸部及腹部飾蕉葉紋及番蓮花，圈足飾蓮瓣紋。底部露胎，刻去地陽文「景泰年製」方框雙行楷書款。', N'高 15.5 公分', N'/media/catalog/enamel/故琺000726N000000000/display.jpg', N'/media/catalog/enamel/故琺000726N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61764?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙耳方瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('596c5cf9-e167-d133-2b87-8a004b1ea2d3', N'故漆000121N000000000', N'剔紅仕女戲童圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段式盒，子母口，盒底及盒內髹黑漆，盒側雕回紋，回紋以一順一逆成組。盒蓋滿鋪回折紋錦地，形成如地毯般柔軟的背景。前景沿著盒緣突出一小石丘，界定出地平線，右側太湖石伸出植物二、三枝，左側一盆假山，空間完整卻自然疏朗。一仕女微快步，手持枝葉，回身逗弄著雙手高舉跳躍的童子。仕女臉微側，臉形尖而豐腴，削肩，雙手交叉腹前，動作含蓄，衣衫飄動，姿態生動優雅。童子臉微揚，身形豐圓，伸手抬足，動感十足，活潑可愛。漆色紅潤，刀法流轉，打磨圓轉，人物動作鮮活，手法精緻細膩。', N'高 2.9 公分、徑 6.7 公分、底徑 6.4 公分', N'/media/catalog/lacquer/故漆000121N000000000/display.jpg', N'/media/catalog/lacquer/故漆000121N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18067?dep=U', N'CC-BY-4.0', N'剔紅仕女戲童圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e5f8b174-37d5-1f5e-1d7a-8a5a6b9d405e', N'故玉000030N000000000', N'獸紋玉劍璏', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'東漢', NULL, N'玉質，面琢回首神獸。劍璏本是嵌飾於劍鞘上的飾物，同時具有用以固定革帶的功能。', N'長 5.36 公分、寬 2.5 公分', N'/media/catalog/jade/故玉000030N000000000/display.jpg', N'/media/catalog/jade/故玉000030N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48226?dep=U', N'CC-BY-4.0', N'獸紋玉劍璏 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('30921d0e-a57d-8a52-1e1c-8af3a657f7ae', N'中日瓷000005N000000000', N'墨地素三彩四季花鳥瓷方瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 康熙', NULL, N'方瓶，圓撇口、長頸、平方肩下折，長筒型器身，平底。上圓下方器型，取琮式瓶天圓地方的造型概念。平底心有四方臍，內有透明釉下青花書「大清康熙年製」楷款。字體筆法隨性，為康熙時期民窯的作品。器內施白釉，外無釉，高溫素燒後，在無釉素坯的外壁上以焦墨鉤勒、點畫紋飾輪廓，再填繪綠葉，黃、紫色夏荷，秋菊，芙蓉等四季花。素坯留白作梅花，並有蝴蝶、鳥雀穿梭其間。花葉色彩分明，釉色分濃淡，使紋飾有陰陽向背的層次感。細心避開紋飾，填入勻亮如漆的墨地。彩上再罩一層透明乳白鉛釉。此類高溫素坯上低溫鉛釉的作品，為康熙時期素三彩的特色。 素三彩，釉色以黃、綠、紫、白為主，偶爾也加紅、藍色。或因釉彩直接施於無釉的素燒坯上，故有「素三彩」之稱。墨彩是康熙時期的創燒，濃厚漆黑瑩亮，獨樹一幟。以外銷歐洲為主，傳世數量不多。據推測，當時在歐洲或有如漆器般地被珍視。', N'口徑 15.2 公分、肩部 15 × 15 公分、底 11 × 11 公分、高 51 公分', N'/media/catalog/ceramic/中日瓷000005N000000000/display.jpg', N'/media/catalog/ceramic/中日瓷000005N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71959?dep=U', N'CC-BY-4.0', N'墨地素三彩四季花鳥瓷方瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8a941d56-a062-7352-176a-8b4744167228', N'購錢004454N000000000', N'聖宋通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'銅質。方孔圓錢，正面有篆書：「聖宋通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢004454N000000000/display.jpg', N'/media/catalog/coin/購錢004454N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13792?dep=U', N'CC-BY-4.0', N'聖宋通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fb9dc89c-04e2-0ac1-8ad3-8b9c88af6a52', N'購錢000978N000000000', N'天聖元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「天聖元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000978N000000000/display.jpg', N'/media/catalog/coin/購錢000978N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10316?dep=U', N'CC-BY-4.0', N'天聖元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b542a8d0-eac9-3882-2aa2-8c27c71bae23', N'中銅000150N000000000', N'獸面紋觚', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'觚口極度外張，直筒腹，圈足起臺。頸部飾蕉葉紋，內填解體獸面紋，下頸處則有一小周渦紋與四瓣花紋相間紋飾帶。腹部、圈足飾解體獸面紋。下頸處、腹部、圈足皆有四條扉稜。此器仿自商晚期觚的造型，但渦紋、四瓣花紋、地紋的雲雷紋等細節多有訛舛。器表紅、綠作鏽，局部紋飾覆蓋瘤狀物彷彿堆疊的鏽層，以上特徵均為晚期仿古器常見的作舊方式。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周雷紋觚」。', N'高 34.4 公分', N'/media/catalog/bronze/中銅000150N000000000/display.jpg', N'/media/catalog/bronze/中銅000150N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6841?dep=U', N'CC-BY-4.0', N'獸面紋觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8bc93c67-bd38-aea1-7727-8cf72f94e45b', N'中瓷000011N000000000', N'豇豆紅釉太白尊', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 康熙', NULL, N'小口微外侈，短頸溜肩，廣腹，形似半圓球，平底凹足。器身施銅紅釉，因受窯爐溫度影響，呈色有深淺之別，類似豇(音同姜)豆色澤，故有豇豆紅釉之說。器腹淺劃三組暗花團螭紋，口沿及器內施白釉，外底有「大清康熙年製」楷體款識。此類小口半圓穹狀的器型一般被稱為「太白尊」，然而清宮檔案舊稱為「花囊」。對照西洋傳教士殷弘緒的書簡，得知是以吹釉法施釉。', N'高 8.6 公分、口徑 3.3 公分、底徑 12.5 公分', N'/media/catalog/ceramic/中瓷000011N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000011N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19336?dep=U', N'CC-BY-4.0', N'豇豆紅釉太白尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('241c5d0d-9cf3-90be-5d10-8cfce2d26326', N'故玉001113N000000000', N'玉摩羯佩', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'青色閃玉質。器首為龍形，有雙翅，尾作魚形，龍口銜珠。在翅、鰭與尾部共有七個圓穿，可能為佩飾之物。', N'長 7.2 公分、高 4.75 公分、厚 1.2 公分', N'/media/catalog/jade/故玉001113N000000000/display.jpg', N'/media/catalog/jade/故玉001113N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/87?dep=U', N'CC-BY-4.0', N'玉摩羯佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('db952f44-95a8-4d62-45c5-8d11629d5f8a', N'中銅000122N000000000', N'內言卣', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'帶蓋，器作子母口，長頸，鼓腹略垂，圈足。U形提梁兩端作浮雕獸首，提梁與器頸之間以環耳相接。全器無地紋，蓋面和器腹中段作獸面紋，頸間和圈足飾夔鳳紋。器蓋對銘二字。本器為乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之「周內言卣」。', N'器高 33.0 公分、帶提粱 35.3 公分、腹寬 21.5 公分', N'/media/catalog/bronze/中銅000122N000000000/display.jpg', N'/media/catalog/bronze/中銅000122N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1948?dep=U', N'CC-BY-4.0', N'內言卣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e015de14-8d45-7397-903b-8d3fa88ae172', N'中琺000127N000000000', N'掐絲琺瑯花卉紋瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'長頸瓶，侈口，頸有雙雲形耳，耳間有二道銅箍，圓腹，外撇圈足。頸與圓腹之間有一小圓腹，器形十分特別。以淺藍地掐絲琺瑯為飾，口沿、腹上緣及下緣各飾一圈如意雲紋，頸部飾卷枝朵花紋，腹部飾番蓮紋，圈足飾海棠紋。中琺126、127、128為一組。', N'瓶高 10.3 公分', N'/media/catalog/enamel/中琺000127N000000000/display.jpg', N'/media/catalog/enamel/中琺000127N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53999?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f95c7ccb-a06a-e869-f31c-8f94184366ff', N'購錢000894N000000000', N'天禧通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「天禧通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000894N000000000/display.jpg', N'/media/catalog/coin/購錢000894N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10232?dep=U', N'CC-BY-4.0', N'天禧通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a2e2ee5a-94fe-478e-ffd6-9052be803d54', N'中銅000294N000000000', N'「昭武通寶」錢紋鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'圓鏡，圓鈕。鏡背有銘四字。', N'直徑 5.3 公分', N'/media/catalog/bronze/中銅000294N000000000/display.jpg', N'/media/catalog/bronze/中銅000294N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7104?dep=U', N'CC-BY-4.0', N'「昭武通寶」錢紋鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('af0a1fe0-aee2-dcb5-2152-908ae76d88c5', N'南購畫00001600000', N'東海道六 五十三次 戸塚', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪戶冢宿（神奈川縣橫濱市戶冢區）風景，畫面由右而左標示「東海道六」、「五十三次 戶塚」、畫面左下角「廣重画」，畫面框外右下角一半「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001600000/display.jpg', N'/media/catalog/painting/南購畫00001600000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36471?dep=P', N'CC-BY-4.0', N'東海道六 五十三次 戸塚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('693b22dd-ae95-66b7-9d34-90ea7870e6e1', N'中玉000362N000000000', N'玉環形器', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'商至西周', NULL, N'玉質，青白泛灰黑色，散布深淺褐斑，有黃赭斑。圓筒式手鐲，上下緣作折邊，外壁琢飾三道弦紋。', N'徑 9.5 公分', N'/media/catalog/jade/中玉000362N000000000/display.jpg', N'/media/catalog/jade/中玉000362N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53118?dep=U', N'CC-BY-4.0', N'玉環形器 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e356e911-0767-8e63-e800-9213a9a2d218', N'故畫00097100000', N'元王振鵬寶津競渡圖　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大三年（1310）', NULL, N'王振鵬（約活動於西元一二八○—一三二九年），永嘉人（浙江溫州）。字明梅，受知仁宗，賜號孤雲處士。界畫極工緻，毫分縷析，左右高下，俯仰曲折，方圓平直，曲盡其體，而神氣飛動。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'本院藏王振鵬界畫手卷共三幅，而構圖略同，皆畫宋代習俗，農曆三月三日開放金明池，龍舟競渡，百戲雜陳。', N'36.6 × 183.4 公分', N'/media/catalog/painting/故畫00097100000/display.jpg', N'/media/catalog/painting/故畫00097100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1107?dep=P', N'CC-BY-4.0', N'元王振鵬寶津競渡圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('db8d6c31-34eb-bef5-de75-92fe4187ee44', N'中銅000028N000000000', N'蟠虺紋器蓋', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'圓蓋，圓捉手、蓋沿呈盤口狀，可倒置承物。蓋飾蟠虺紋。', N'高 6.5 公分', N'/media/catalog/bronze/中銅000028N000000000/display.jpg', N'/media/catalog/bronze/中銅000028N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6706?dep=U', N'CC-BY-4.0', N'蟠虺紋器蓋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('88ad38db-796d-2d94-5b38-933a8dd10793', N'故畫00098800000', N'宋王詵瀛山圖　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋英宗治平元年（1064）', NULL, N'王詵（約一０四八—一一二二），字晉卿。幼善讀書，長能屬文，博雅該洽，以至奕棋，無不造妙。畫山水略師李成，著色略師李思訓，而能自成一格。畫竹師文湖州。本幅畫峻嶺迴溪，山村茅茨，遠水平沙，數艇隱隱。圖後一遠峰山題款云：「保寧賜第王晉卿瀛山既覺，因圖夢中所見。甲辰春四月，夢遊者。」細審圖中絕壑層巒，俱以青綠著色，用筆工細，氣韻古雅，良為一夢中山水矣。', N'24.5 × 145.1 公分', N'/media/catalog/painting/故畫00098800000/display.jpg', N'/media/catalog/painting/故畫00098800000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14434?dep=P', N'CC-BY-4.0', N'宋王詵瀛山圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d64e181c-d7dc-795c-174b-93c3b39dddae', N'中瓷001110N000000000', N'青瓷貫耳瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'瓶，廣口微撇，收腰式頸，飾二道突弦紋，雙管狀貫耳，夸腹，淺圈足。全器內外施青釉灰綠色，清亮透明，器面滿佈黑色開片與稀疏的冰裂紋。器底有七枚細小的支釘痕，圈足露胎，塗深棕色汁。', N'高 20.1 公分、口徑 8.0 公分、底徑 6.8 公分', N'/media/catalog/ceramic/中瓷001110N000000000/display.jpg', N'/media/catalog/ceramic/中瓷001110N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18912?dep=U', N'CC-BY-4.0', N'青瓷貫耳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3c6c84a8-b6a6-cf2e-b695-94401e9c5df6', N'中瓷000175N000000000', N'霽青釉葫蘆瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明 宣德', NULL, N'葫蘆瓶，圓口，短頸，圓腹，束腰，平底，凹足。外壁施藍釉外底以青花書「大明宣德年製」六字雙行楷款，外加雙圈。', N'高 12.7 公分、口徑 1.8 公分、底徑 5.0 公分', N'/media/catalog/ceramic/中瓷000175N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000175N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23605?dep=U', N'CC-BY-4.0', N'霽青釉葫蘆瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e531679e-38f5-c798-b4a7-94714f2092ef', N'購錢004609N000000000', N'紹興元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'方孔圓錢，「紹興元寶」有篆、楷兩種字體，又有銅、鐵兩種材質。此枚銅錢正面有小篆「紹興元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢004609N000000000/display.jpg', N'/media/catalog/coin/購錢004609N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13947?dep=U', N'CC-BY-4.0', N'紹興元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7d6a9d50-7829-e2c7-b7d5-947be0987706', N'中瓷000064N000000000', N'青花折枝花卉紋六方瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'器作六方瓶形，口緣一周回紋，頸部畫纏枝番蓮。肩頸相間處一周「卍」字紋，腹作六面，各畫折枝番蓮、石榴、桃實與佛手等紋飾。足部飾花卉圖案與回紋。底青花書「大清乾隆年製」六字篆款。', N'高 66.0 公分、口徑 18.3 公分、底徑 18.5 公分、最大徑 31.0 公分', N'/media/catalog/ceramic/中瓷000064N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000064N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2345?dep=U', N'CC-BY-4.0', N'青花折枝花卉紋六方瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('789a07bb-2f77-05be-d530-952fcfc18daf', N'故畫00070300000', N'清王翬千巖萬壑圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙三十二年（1693）', NULL, N'王翬（西元一六三二至一七一七年）常熟人，字石谷，號耕煙散人，清暉主人、烏目山人、劍門樵客。山水得王時敏指授，為清四大家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'叢山中溪沼平皋，於林木叢萃處寺宇倚麓而築。僧侶三人，閒步空林之下，其餘漁者棹槳，遊者縱目，點綴山水之間。畫幅甚巨，而筆墨從容，傅彩雅淡，氣息厚潤，是石谷佳作。畫時年六十二歲。', N'254.1 × 103 公分', N'/media/catalog/painting/故畫00070300000/display.jpg', N'/media/catalog/painting/故畫00070300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3481?dep=P', N'CC-BY-4.0', N'清王翬千巖萬壑圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3f677655-689b-7489-9541-957ffef4de65', N'中琺000128N000000000', N'掐絲琺瑯花卉紋盒', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'圓盒式，子母口，高圈足。以淺藍地掐絲琺瑯為飾，全器飾番蓮花紋，蓋緣及器緣飾如意雲紋，圈足飾幾何紋。中琺126、127、128為一組。', N'盒高 4.6 公分', N'/media/catalog/enamel/中琺000128N000000000/display.jpg', N'/media/catalog/enamel/中琺000128N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54000?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉紋盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2dd2c0d7-7553-2788-c3e1-969153cc7cd7', N'中漆000041N000000000', N'剔紅萬壽龍紋碗', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明 嘉靖', NULL, N'圓碗作弧壁，圈足，碗內及足內髹黑漆。口沿為花卉連枝紋，足壁為連續回字紋，碗外壁飾雲龍紋二，中間以山海紋及圓框「萬」字、「壽」字分界，行龍身軀脩長舞動，瞪眼張口，五爪奮張，龍鬚發揚，姿態威武。一行龍回首呼應後面的行龍，龍身下方海浪起伏，間飾如意雲紋，極富動感。龍紋之下為帶狀如意雲紋。構圖緊湊，佈局滿，剔紅之外，間露褐黃地漆，莊嚴中不失富麗。刀法俐落有力，刀痕鑿鑿，益顯行龍的生命力，漆層薄，漆色潤，是官方雕漆的佳品。', N'通高 8.4 公分、深 6.7 公分、口徑 16.1 公分、足徑 7.5 公分', N'/media/catalog/lacquer/中漆000041N000000000/display.jpg', N'/media/catalog/lacquer/中漆000041N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17451?dep=U', N'CC-BY-4.0', N'剔紅萬壽龍紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1b3b4005-b027-53ff-de74-96ab75f58f64', N'贈雕000136N000000000', N'骨雕填彩匕', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'取一片骨材磨製而成，一端磋磨出寬片狀，弧緣，另一端扁窄，端部磨製出一小環，以供繫掛。全器傷蝕嚴重，但有一面近環部位仍遺留原細陰線刻三角紋、弧形紋等紋飾，局部尚依稀可辨出原填紅彩。依此陰線刻紋與填彩遺痕，應為漢代器。', N'長 6.8 公分、最寬 2.1 公分', N'/media/catalog/carving/贈雕000136N000000000/display.jpg', N'/media/catalog/carving/贈雕000136N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45365?dep=U', N'CC-BY-4.0', N'骨雕填彩匕 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7c6eb723-3a45-02c4-7295-96c85e37a5cd', N'故畫00194700000', N'元趙孟頫達摩像　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元世祖至元二十九年（1292）', NULL, N'據傳達摩為中國禪宗始祖，本為印度王子，南北朝時泛海至中國傳法，曾於嵩山少林寺面壁十年，深受國人崇仰。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'松蔭下，達摩身披紅色袈裟，手捻白花，趺坐於石上，神情怡然。年款雖為至元二十九年（一二九二），然畫法細碎，近於吳門畫派末流，當是後人仿本。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'趙孟頫（一二五四—一三二二），字子昂，號松雪道人。詩文清遠，書畫為後世所宗。', N'111.1 × 35 公分', N'/media/catalog/painting/故畫00194700000/display.jpg', N'/media/catalog/painting/故畫00194700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1239?dep=P', N'CC-BY-4.0', N'元趙孟頫達摩像　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5173bd74-07db-cffc-4c86-975c2626da1c', N'中琺000028N000000000', N'掐絲琺瑯蓋碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'微撇口，深壁，圈足，圓頂蓋，圈足鈕。鈕內為一藍色團壽字。全器藍地，以掐絲技法於蓋緣、口緣飾綠地拐子龍紋，蓋與腹部飾纏枝番蓮紋，鈕旁與腹底飾四色如意雲紋，鈕外與圈足飾深藍地回紋。', N'高 6.0 公分、深 5.2 公分、口徑 12.0 公分、足徑 6.7 公分', N'/media/catalog/enamel/中琺000028N000000000/display.jpg', N'/media/catalog/enamel/中琺000028N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53905?dep=U', N'CC-BY-4.0', N'掐絲琺瑯蓋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('182a97c7-dcd6-8ebf-b771-97aaa94a8d8d', N'中瓷000341N000000000', N'白瓷橄欖瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'橄欖瓶，侈口、長頸、斜肩、碩腹下斂、圈足微外撇。胎骨較薄，全器施白釉，表面可見細碎開片，足底露白胎。器外口沿繞回紋一周，頸飾蕉葉紋，肩劃回紋及卷渦紋，腹部滿飾蓮荷花葉，近底處繞蓮瓣紋一周，足外亦飾回紋。近底處有舊傷修補痕跡。', N'高 24.9 公分、口徑 4.6 公分、底徑 5.5 公分', N'/media/catalog/ceramic/中瓷000341N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000341N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23131?dep=U', N'CC-BY-4.0', N'白瓷橄欖瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('51e8b3c4-2112-cea9-2506-995270e1c878', N'中瓷001289N000000000', N'鈞窯 天藍釉碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'斂圓口，深弧壁，尖底，矮圈足，足壁微外撇。全器罩施天藍色釉，釉層厚薄不勻，釉色自口沿至底部，呈現米黃、黃藍、天藍的變化，釉表開淺棕色細紋片。施釉至足際，積垂的厚釉覆罩住整隻足壁。外底中心鼓起，施一滴釉藥，足底緣、內周壁無釉處，皆露䊣色胎。足底緣經刀鏇削，裏緣高過外緣修足過肩。', N'高 10.0 公分、口徑 22.5 公分', N'/media/catalog/ceramic/中瓷001289N000000000/display.jpg', N'/media/catalog/ceramic/中瓷001289N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1297?dep=U', N'CC-BY-4.0', N'鈞窯 天藍釉碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dfbbb093-eff0-836d-b64d-997c31dc3d98', N'故雕000019N000000000', N'癭木靈芝筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'此件天然木癭，略加磨礱，極盡木紋之美。底刻隸書︰「絳雲樓珍藏」，朱印：「牧齋」。收藏者為明末詩人錢謙益（1582-1664），字受之，號牧齋，晚號蒙叟、東澗老人，江蘇常熟人。', N'長 12.5 公分、寬 32.5 公分、高 17.9 公分', N'/media/catalog/carving/故雕000019N000000000/display.jpg', N'/media/catalog/carving/故雕000019N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2413?dep=U', N'CC-BY-4.0', N'癭木靈芝筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1d576ab5-2644-d0c5-5cec-997dabb2f02a', N'購錢001139N000000000', N'明道元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「明道元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001139N000000000/display.jpg', N'/media/catalog/coin/購錢001139N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10477?dep=U', N'CC-BY-4.0', N'明道元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c6fa4c43-c0cf-a283-617c-9a56115d1abb', N'贈雕000048N000000000', N'象牙梳', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'器由兩塊牙片組成，一片作梯形梳柄，有一面尚有褐彩紋飾；另一片雕製成梯形梳身，梳齒密佈，但已殘缺，再經修磨。山東曲阜魯故城春秋墓出土的一件象牙梳，其梳身之梯形角度較平直；山東萊蕪西上崮戰國墓葬出土的三件牙梳，其梳身角度皆較斜，故可能也是戰國時代的象牙梳。', N'長 5.3 公分、厚 5.9 公分', N'/media/catalog/carving/贈雕000048N000000000/display.jpg', N'/media/catalog/carving/贈雕000048N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45274?dep=U', N'CC-BY-4.0', N'象牙梳 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f316c60d-abcc-4bce-77fe-9af3ffafdf16', N'中玉000015N000000000', N'玉荷花圓盒', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'白玉小圓盒，玉色泛灰黃，小塊淺赭斑。蓋與器身略相等，有圈足。蓋面中心浮雕荷花與荷葉。', N'高 3.9 公分、口徑 6.7 公分、足徑 4.2 公分', N'/media/catalog/jade/中玉000015N000000000/display.jpg', N'/media/catalog/jade/中玉000015N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52754?dep=U', N'CC-BY-4.0', N'玉荷花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('20f653ae-99f8-95c9-4c9a-9b823befc471', N'贈雕000174N000000000', N'牙雕魚式佩', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'全器雕成一尾魚形，以圈點紋為眼紋，魚身兩面滿刻交叉斜線為魚鱗紋，尾分叉。口部橫向與直向皆有孔，可供懸佩。器之ㄧ面染成深綠色，另一面成淺綠色。魚符、魚袋均為唐代官員朝服的一種佩飾，當時佩魚制度在初期比較嚴格，魚符的質料到魚袋的鑲飾均有定制，皇太子佩玉魚，親王配金魚，諸官佩銅魚，後來限制放寬，不限官員佩魚，魚式佩成為腰間的魚形佩飾，而非魚符了。', N'長 8.2 公分、最寬 1.1 公分', N'/media/catalog/carving/贈雕000174N000000000/display.jpg', N'/media/catalog/carving/贈雕000174N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45402?dep=U', N'CC-BY-4.0', N'牙雕魚式佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e677290a-1d1a-4000-ebed-9b9ec42d5c52', N'購瓷000065N000000000', N'長沙窯 綠釉單柄壺', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'壺圓口，橢圓腹，短流，長方形空心橫柄，柄中段附圓穿孔，以便穿插木柄；蓋側及器肩各附穿帶繫孔。全器除口沿及圈足無釉外，均施綠釉。釉色青綠乳濁，釉層較厚，釉面滿佈細碎開片紋，器蓋釉色偏藍，積釉處雜呈藍斑。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'側把單柄壺盛行於唐代晚期，浙江越窯、湖南長沙窯等南北各窯均有燒造，石製器亦有製作。長沙窯製作多種日常茶器如單柄壺、茶瓶、茶碗、茶末盒等多帶器銘如「荼埦」、「荼盞子」、「大茶合」、「鎮國茶瓶」，可見飲茶風氣在湖南地區頗為盛行。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'單柄壺在唐晚期與短流茶瓶一樣，皆作為注湯點茶之用，其形制與院藏驪山石單柄壺，以及國立臺中自然科學博物館收藏的一組唐代滑石茶器中的小型單柄壺極為接近。此為唐代晚期盛行於茶盞內點茶的帶柄茶瓶，或亦可稱之為「急須」，因單柄壺形制在宋人黃裳〈龍鳳茶寄照覺禪師〉詩中稱「急須」為東南之茶器，用以煎煮茶湯，這類造型，由唐至今造型、胎釉雖經演變，然千餘年來仍為茶家所愛，明清時期宜興紫砂或閩粵所製白泥尤為多見。', N'通蓋高 18.5 公分、口徑 4.9 公分、足徑 7.4 公分', N'/media/catalog/ceramic/購瓷000065N000000000/display.jpg', N'/media/catalog/ceramic/購瓷000065N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1074?dep=U', N'CC-BY-4.0', N'長沙窯 綠釉單柄壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('8e051dc6-49f6-b31b-b24a-9cd7d1701367', N'中銅000051N000000000', N'嵌金銀雲紋壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'本器紋飾以簡化的獸帶紋為主，填以回紋地。由上至下，第一道為三角紋，第二、三道為獸帶紋。三角紋及獸帶紋以紅銅片鑲嵌。口沿及圈足上也有銀絲嵌的心形紋、螺形紋及三角紋。兩側有鋪首銜環為飾。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周雷紋壺」。', N'高 45.7 公分', N'/media/catalog/bronze/中銅000051N000000000/display.jpg', N'/media/catalog/bronze/中銅000051N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6553?dep=U', N'CC-BY-4.0', N'嵌金銀雲紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dbcfa7df-1e83-c9bc-66ff-9d39d8a53283', N'中琺000075N000000000', N'掐絲琺瑯番蓮紋八吉祥高足碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'侈口，深壁，高圈足。口緣及外壁露胎，全器以掐絲琺瑯技法完成，淺藍色地，外壁飾蓮花座八吉祥，底部飾一圈蕉葉紋，足部上段飾五瓣花紋，下段飾番蓮紋。', N'高 17.2 公分', N'/media/catalog/enamel/中琺000075N000000000/display.jpg', N'/media/catalog/enamel/中琺000075N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53951?dep=U', N'CC-BY-4.0', N'掐絲琺瑯番蓮紋八吉祥高足碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a64c7beb-7d8c-6ff0-1aa5-9d3b2c7b58b3', N'中漆000001N000000000', N'剔紅龍紋方勝式三層套盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅方勝式套盒，色硃紅光潤。平頂蓋，子母口，矮直壁，平底，淺足座。蓋面以波濤紋為地雕雙龍戲珠，中心有菊花團壽字，並以回紋為邊，蓋與三層套盒壁各有六處開光，內雕梅、蘭、蓮、菊、秋葵、月季、桃花等四季花卉，紋間填飾斜方回紋錦地，開光外雕飾番蓮花。座亦為方勝形，面雕紅萬字錦，有如意形足六。器裡與底髹黑色光漆。', N'長 32.7 公分、寬 20.5 公分、通高 18.8 公分、每層深 3.0 公分；座長 35.5 公分、寬 23.0 公分', N'/media/catalog/lacquer/中漆000001N000000000/display.jpg', N'/media/catalog/lacquer/中漆000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17537?dep=U', N'CC-BY-4.0', N'剔紅龍紋方勝式三層套盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('53551041-4114-b4e0-c194-9d7fd758108c', N'購錢004845N000000000', N'開元通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'銅質。方孔圓錢，正面有楷書：「開元通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢004845N000000000/display.jpg', N'/media/catalog/coin/購錢004845N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/14183?dep=U', N'CC-BY-4.0', N'開元通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0aa693e2-ef1c-efc4-f1df-9da678e018f2', N'贈雕000068N000000000', N'牙扭絲紋環', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'環形，環身剖面呈扁橢圓形，器表滿雕扭絲紋。這種扭絲紋也稱為繩索紋或綯紋，或逕稱為綯索紋，在戰國時代的玉器與銅器上皆常見，不一定為佩飾器，也可為鋪首上的活環或其他器物上的附件。例如在河南汲縣山彪鎮第五號戰國墓出土的一件弦紋骨環，出土時伴隨一件鐵帶鉤，當時骨環或與鐵帶鉤一起佩戴。', N'徑 3.4 公分', N'/media/catalog/carving/贈雕000068N000000000/display.jpg', N'/media/catalog/carving/贈雕000068N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45294?dep=U', N'CC-BY-4.0', N'牙扭絲紋環 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('28e2da9b-052c-c2d0-10d5-9dba6fe5118b', N'中瓷002222N000000000', N'哥窯 青瓷葵口盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'六瓣花口，淺弧壁，平底，圈足。全器施哥釉。釉色白中透青，口緣處呈色為黃褐。內外壁均見冰裂紋。足緣露胎塗褐色汁，足內滿釉無款識。由其足緣施塗褐色汁平整規矩的狀況，或許這是一件宋代以後的仿哥窯之作。', N'高 6.8 公分、口徑 19.5 公分、底徑 5.6 公分', N'/media/catalog/ceramic/中瓷002222N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002222N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23702?dep=U', N'CC-BY-4.0', N'哥窯 青瓷葵口盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4f85e5d0-89df-eeba-90b1-9e08bc7c3d3b', N'購錢003323N000000000', N'□祐元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有行書：「□祐元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢003323N000000000/display.jpg', N'/media/catalog/coin/購錢003323N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/12661?dep=U', N'CC-BY-4.0', N'□祐元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7dfec52f-33cf-1c18-f3e9-9f16f1851402', N'中玉000301N000000000', N'穀紋玉瑗', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'玉質，黃綠色。兩面均雕穀紋為飾，穀紋稍平。', N'厚 0.4 公分、外徑 14.78 公分、內徑 5.4 公分', N'/media/catalog/jade/中玉000301N000000000/display.jpg', N'/media/catalog/jade/中玉000301N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53054?dep=U', N'CC-BY-4.0', N'穀紋玉瑗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('831e7396-4442-67cc-24da-a05885bbe9bc', N'中琺000051N000000000', N'掐絲琺瑯米碟', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'敞口，淺壁，平底，雲紋扁足，盤心有一孔。全器紋飾以掐絲技法完成，通體淺藍地，內壁及盤心滿飾纏枝朵花紋，外壁飾番蓮紋。', N'高 2.6 公分、口徑 14.1 公分、底徑 12.6 公分', N'/media/catalog/enamel/中琺000051N000000000/display.jpg', N'/media/catalog/enamel/中琺000051N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53928?dep=U', N'CC-BY-4.0', N'掐絲琺瑯米碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1bde0682-14ad-3a67-c8b2-a0ac8734c22d', N'中玉000645N000000000', N'玉龍鳳紋飾件', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周中期', NULL, N'牙黃玉，兩面雕琢了相似的龍鳳紋。一隻長頸、彎喙，有羽冠與長尾的鳳鳥，端莊地站立於中央，尾羽自身後彎繞於前；在鳳鳥前、後，飄逸的羽毛中，又各顯露出一個捲鼻的龍頭；龍鼻前端各琢一束飾有平行線紋，似長髮般的羽毛；迴旋繞轉的弧線紋填飾於龍、鳳之間。由風格觀之，這件玉飾應是西元前十、九世紀西周中期的作品。', N'長 7.0 公分、寬 6.1 公分、高 0.4 公分', N'/media/catalog/jade/中玉000645N000000000/display.jpg', N'/media/catalog/jade/中玉000645N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1809?dep=U', N'CC-BY-4.0', N'玉龍鳳紋飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4f9d3794-dcb7-8d89-2101-a12bad9cc272', N'故玉002816N000000000', N'玉覆面組件', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'玉質，色白有赭斑。器形略類菱角，質厚而微鼓。光素無紋。', N'長 3.3 公分、通高 1.4 公分、厚 0.75 公分', N'/media/catalog/jade/故玉002816N000000000/display.jpg', N'/media/catalog/jade/故玉002816N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50921?dep=U', N'CC-BY-4.0', N'玉覆面組件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('de2163e1-ec9e-7fc3-6d5d-a19da08b7326', N'贈雕000129N000000000', N'骨雕彩繪飾片', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'以骨磨製成長條形薄片，細線陰刻紋飾後以紅、黑兩色彩繪，紋飾為雲氣紋。西漢漆器上可得見類似細線陰刻雲氣。此件骨片紋飾具西漢特色，以骨為材孔，其薄如紙，距今有兩千年光陰，保存不易，極其珍稀。', N'長 6.8 公分、寬 1.0 公分、厚 0.1 公分', N'/media/catalog/carving/贈雕000129N000000000/display.jpg', N'/media/catalog/carving/贈雕000129N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45358?dep=U', N'CC-BY-4.0', N'骨雕彩繪飾片 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dd90a460-69a8-dec3-31c7-a1bb5512312d', N'中琺000124N000000000', N'掐絲琺瑯夔龍紋瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'蒜頭口，長頸，圓腹，圈足。以淺藍地掐絲琺瑯為飾，全器飾靈芝、夔龍紋。附方形花卉紋銅鏟一支，銅箸一雙。中琺123、124、125為一組。', N'瓶高 11.2 公分', N'/media/catalog/enamel/中琺000124N000000000/display.jpg', N'/media/catalog/enamel/中琺000124N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53996?dep=U', N'CC-BY-4.0', N'掐絲琺瑯夔龍紋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7b9acc22-9cff-6f24-751d-a21bf8ab7a8d', N'中漆000018N000000000', N'剔犀如意雲紋小圓盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'盤沿斜，底平，底髹褐漆。底面盤沿作唐草文三組。盤面中央由內而外為四星形、小圓、六組雲尾形，六星形，最外圈為六如意雲紋，盤緣弦紋兩道。如意雲紋頭寬，轉折方，線條粗細勻整，空隙處造型規律一致。刀切凹槽斜深而底窄細，漆層側面露出細密漆層重疊線，漆面亮，刀下切處尖銳，漆質潤。', N'通高 1.8 公分、深 1.0 公分、口徑 13.7 公分、底徑 10.6 公分', N'/media/catalog/lacquer/中漆000018N000000000/display.jpg', N'/media/catalog/lacquer/中漆000018N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17554?dep=U', N'CC-BY-4.0', N'剔犀如意雲紋小圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('85ec43a2-aa45-118e-baf6-a260f1b3a76e', N'故琺000625N000000000', N'掐絲琺瑯海棠式雙耳瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，由口至足作四瓣花形，雙螭龍耳。整器形如四個形制相同的銅瓶接連合而成。頸與腹間鏨變形蓮瓣一圈，器壁以掐絲琺瑯料填色裝飾，全器垂拱式夔龍紋為飾。足內鏨「大明景泰年製」楷款。', N'口徑長 14.3 公分、寬 12.4 公分；足徑長 13.6 公分、寬 11.1 公分', N'/media/catalog/enamel/故琺000625N000000000/display.jpg', N'/media/catalog/enamel/故琺000625N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61680?dep=U', N'CC-BY-4.0', N'掐絲琺瑯海棠式雙耳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('16119cb6-3596-3261-1ed8-a29055e3c50a', N'故銅000472N000000000', N'鋪首銜環蒜頭扁壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '561e3931-1096-c637-9eb3-b5c5ce02c88f', N'秦', NULL, N'圓口，直頸，圓扁腹，圈足。口呈蒜頭形，肩飾獸首銜環耳。腹飾橢圓形紋。', N'高 28.8 公分、腹深 25.4 公分、口徑 3.2 公分、底徑長 14.8 公分、寬 8.5 公分、耳柱高 4.6 公分、足高 3.7 公分、腹圍 74.0 公分', N'/media/catalog/bronze/故銅000472N000000000/display.jpg', N'/media/catalog/bronze/故銅000472N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3582?dep=U', N'CC-BY-4.0', N'鋪首銜環蒜頭扁壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2279a5d1-3f26-5ec2-94bc-a2982c468f35', N'中畫00015500000', N'清黃應諶陋室銘圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙六年（1667）', NULL, N'黃應諶，順天人。字敬一，號劍庵。善畫人物、鬼判、嬰孩。於順治十五年（西元一六五八年）入畫院。' + NCHAR(13) + NCHAR(10) + N'　　此圖筆墨明淨，設色光艷。凡林木、峰巒、屋宇、流泉，無不布置妥帖。人物仍有明院派習氣。', N'243.3 × 158 公分', N'/media/catalog/painting/中畫00015500000/display.jpg', N'/media/catalog/painting/中畫00015500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1725?dep=P', N'CC-BY-4.0', N'清黃應諶陋室銘圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1e77f720-7591-49bf-5391-a372c62470d1', N'贈錢001263N000000000', N'光緒通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「光緒通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001263N000000000/display.jpg', N'/media/catalog/coin/贈錢001263N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9086?dep=U', N'CC-BY-4.0', N'光緒通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c3dbbcf6-6461-fded-65c0-a3b74f01bb15', N'購錢004586N000000000', N'建炎通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'方孔圓錢，「建炎通寶」有篆、楷兩種字體，又有銅、鐵兩種材質。此枚銅錢正面有篆書「建炎通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢004586N000000000/display.jpg', N'/media/catalog/coin/購錢004586N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13924?dep=U', N'CC-BY-4.0', N'建炎通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b7f00ca3-b876-23d8-786d-a430d763fe1b', N'中瓷000339N000000000', N'白瓷弦紋樽', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'金至元', NULL, N'樽，直筒形，深壁，三蹲式獸足。全器施釉，色呈牙白，積釉處帶黃色調，底部多冷紋。口沿鑲銅釦，其餘滿釉。外壁有弦紋三層，每一層各有三道凸弦紋，足後方有孔。', N'高 10.8 公分、口徑 13.2 公分', N'/media/catalog/ceramic/中瓷000339N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000339N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23129?dep=U', N'CC-BY-4.0', N'白瓷弦紋樽 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('475da0ee-8bde-1321-4fef-a441c20b9a6e', N'中漆000017N000000000', N'剔紅方龕', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅方龕，色暗紅，略有傷損，本件僅存四圍龕壁，頂與座皆無。長方形，除背面外皆飾連續回紋為邊，正面以篆字為地，中有長方形嵌玻璃開光，下有銅片飾件，應可開啟，二短面以番蓮紋為地，上方有較小嵌玻璃開光，背面刻飾寶相花。器內壁髹黑色光漆。', N'長 42.0 公分、寬 29.5 公分、通高約 60.0 公分', N'/media/catalog/lacquer/中漆000017N000000000/display.jpg', N'/media/catalog/lacquer/中漆000017N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17553?dep=U', N'CC-BY-4.0', N'剔紅方龕 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('604af6a8-54a4-0149-bcf8-a5118be8a5d5', N'南購畫00001900000', N'東海道九 五十三次 大磯', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪大磯宿（神奈川縣中郡大磯町）風景，畫面由右而左標示「東海道九」、副題「鴫立沢西行庵」、「五十三次 大磯」、「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001900000/display.jpg', N'/media/catalog/painting/南購畫00001900000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36474?dep=P', N'CC-BY-4.0', N'東海道九 五十三次 大磯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1e90b27c-9ce3-8e40-35f0-a5b204637fd5', N'中琺000018N000000000', N'掐絲琺瑯爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'鍍金口，短頸，雙夔龍耳，斜肩，圓腹，三張口龍足，穹頂蓋，蓮瓣座鏤空龍紋鈕。蓋頂三處開光為鏤空團壽字。全器藍地，以掐絲技法於蓋、頸與腹飾番蓮紋，頸飾拐子龍紋，肩飾如意雲紋。', N'通高 24.9 公分', N'/media/catalog/enamel/中琺000018N000000000/display.jpg', N'/media/catalog/enamel/中琺000018N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53895?dep=U', N'CC-BY-4.0', N'掐絲琺瑯爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bae429cc-6fee-f12b-23bd-a605a7c617c8', N'購錢001016N000000000', N'紹聖元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有行書：「紹聖元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001016N000000000/display.jpg', N'/media/catalog/coin/購錢001016N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10354?dep=U', N'CC-BY-4.0', N'紹聖元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9ab1d313-ea98-dfde-450b-a61cb949458d', N'故玉000012N000000000', N'玉管', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'玉質，圓筒形，面琢有三凸棱。', N'徑 2.98 公分、孔徑 1.95 公分', N'/media/catalog/jade/故玉000012N000000000/display.jpg', N'/media/catalog/jade/故玉000012N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48210?dep=U', N'CC-BY-4.0', N'玉管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c0202b15-cf83-e489-17b5-a66e6fcc574f', N'中琺000003N000000000', N'掐絲琺瑯爐（五供）', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'銅胎。直口，豎邊，短頸，圓腹，雙板形耳，圓底，嵌飾鍍金獸面三足。以掐絲技法、琺瑯料填色制作花紋，口沿飾深藍地回紋，其餘皆為淺藍地，頸部飾海棠花紋及雙夔龍拱珠紋，下接一圈如意雲紋邊飾，腹部及底部飾纏枝番蓮紋，足身飾番蓮紋及葵花紋。外底部露胎，有鏨刻「乾隆年製」雙行楷書雙方框款。香爐為五供之一，本器與中琺4-7成套。', N'通高 22.5 公分', N'/media/catalog/enamel/中琺000003N000000000/display.jpg', N'/media/catalog/enamel/中琺000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53880?dep=U', N'CC-BY-4.0', N'掐絲琺瑯爐（五供） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f182c6af-ea27-da17-f474-a7cf35d39c68', N'中漆000036N000000000', N'剔黑多寶紋碗', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'碗，侈口，深壁，圈足。外髹朱黑二色，內彩金漆。以朱漆菱格花錦紋為底；黑漆則雕各式花卉、果實、蝴蝶及雜寶，隨意漫佈，果實上都細刻幾何花紋，裝飾意味濃厚。', N'高 10.1 公分、深 7.7 公分、口徑 22.4 公分、足徑 11.8 公分', N'/media/catalog/lacquer/中漆000036N000000000/display.jpg', N'/media/catalog/lacquer/中漆000036N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17448?dep=U', N'CC-BY-4.0', N'剔黑多寶紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e3575f07-7617-8ce0-96ba-a848c273f509', N'中琺000129N000000000', N'掐絲琺瑯花卉紋蓋碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'口微撇，深壁，圈足，帶圈足鈕圓形蓋，蓋緣略外撇。器表淺藍地，飾五彩轉枝番蓮紋，鈕頂有一紅色地深藍變形團壽字，蓋鈕及圈足外緣為深藍地回紋，鈕旁飾一圈如意雲紋，腹底飾一圈蓮瓣紋，蓋緣及碗緣飾綠地深藍色拐子龍紋邊飾。', N'高 9.1 公分', N'/media/catalog/enamel/中琺000129N000000000/display.jpg', N'/media/catalog/enamel/中琺000129N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54001?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉紋蓋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('60321efd-8aa5-91bf-bb1c-a8f73e18c652', N'贈雕000036N000000000', N'牙飾件', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'長條形，剖面呈長方形，兩長面紋飾同，兩端皆陰刻一線，中刻三個X為界，於四間隔內各刻圈點紋。器之兩端窄面各對穿一孔，孔壁有未對準的錯置臺痕。', N'長 8.7 公分、寬 1.2 公分、厚 0.6 公分', N'/media/catalog/carving/贈雕000036N000000000/display.jpg', N'/media/catalog/carving/贈雕000036N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45262?dep=U', N'CC-BY-4.0', N'牙飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f21cbdca-171e-7291-7982-a8f79ee06964', N'中畫00008300000', N'元趙孟頫湯王徵尹圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大二年（1309）', NULL, N'夏朝末年，意欲討伐夏桀的商湯，苦無賢士協助。他聽說當時莘國伊尹，雖然以農耕為生，但賢名遠播，非常有才能，因此數次請人前往徵聘。伊尹最後終於答應了，並在政治和軍事上輔佐湯王，成功地建立商朝。 圖上有元代趙孟頫（一二五四－一三二二）的款識，不過由人物樹石細膩多彩的敷色方式及格套式的構圖來看，應為十七世紀的擬古之作。', N'148.7 × 73 公分', N'/media/catalog/painting/中畫00008300000/display.jpg', N'/media/catalog/painting/中畫00008300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1250?dep=P', N'CC-BY-4.0', N'元趙孟頫湯王徵尹圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('68b48d9f-f586-883a-8aae-a913a4557efa', N'贈瓷000450N000000000', N'陶編鐘', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'陶鐘，器型仿青銅器編鐘，方鈕，鐘身有二十四枚，上下緣塗白陶衣，鉦部及鼓部有白陶衣紋飾，已漫渙不清，部分可能是動物類紋飾。', N'待測量', N'/media/catalog/ceramic/贈瓷000450N000000000/display.jpg', N'/media/catalog/ceramic/贈瓷000450N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43480?dep=U', N'CC-BY-4.0', N'陶編鐘 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0d2fd6c6-8ba7-bdf0-3e7d-a93040c21e2e', N'中銅000101N000000000', N'紹興豆', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋 紹興十六年', NULL, N'直壁斂口盆式，淺腹。器腹以橫弦紋為上下界，鑄成淺浮雕幾何式的迴轉圖案，形成類似西周晚期重環紋的裝飾，並間以突出的圓形乳丁紋。與法國賽努奇亞洲博物館藏帶有豆柄之〈北宋政和豆〉相對照，此器原應有豆柄，現已佚失。口沿外壁鑄有銘文一圈二十八字：「唯紹興丙寅三月乙丑，帝命作豆，賜師臣檜家廟，以薦菹醢，唯予永世用享。」此器曾經劉體智收藏。', N'通高 7.0 公分、深 3.7 公分、口徑 14.5 公分、底徑 14.8 公分', N'/media/catalog/bronze/中銅000101N000000000/display.jpg', N'/media/catalog/bronze/中銅000101N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5?dep=U', N'CC-BY-4.0', N'紹興豆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ad397695-963b-f128-72e8-a98037372c7a', N'故漆000383N000000000', N'剔紅雙獅圖圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明 永樂', NULL, N'盒作扁圓形，子母口，圈足，盒內及底部髹褐漆，漆色紅褐帶透明感。盒面雕雙獅戲球，兩獅側身躍動，回首面向圓心，露齒銜帶，獅面深目捲髮，肌肉緊拉。盒心為錦地綵球，四周綵帶翻折，三條長帶曲折延長，環繞於四周的雲紋之上，雲紋以四、五朵相連成組，自盒下緣向兩側延伸，流動綿長。盒底外緣刻雲紋，共十組，斜向流轉環繞，自然靈活。盒面佈局多處露出黃地，物象雖多，井然有序。漆色紅潤，漆層堅實，刀法深峻，雲紋、獅身肌肉等處並用減地與陰刻線，毛髮以更淺的刻線表達，雕工講究。', N'高 4.4 公分、徑 10.6 公分', N'/media/catalog/lacquer/故漆000383N000000000/display.jpg', N'/media/catalog/lacquer/故漆000383N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17725?dep=U', N'CC-BY-4.0', N'剔紅雙獅圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3a01216b-ccbc-68c9-3990-aa48e1f37ad2', N'中漆000052N000000000', N'剔彩春壽寶盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'盒緣開光，內飾四組山水人物，開光間飾黃地綠漆斜格錦地，其上浮雕八寶。盒蓋大圓內一聚寶盆，滿盛各式珍寶，光芒四射，當中一大大的春字，春字中又南極仙翁，外側各一行龍，完全承襲嘉靖樣式的春壽寶盒，且尺寸比例、圖樣等也幾乎完全相同，似乎為刻意的模仿。然顏色更為多樣，綠、黃、紫褐、紅，且色彩鮮豔，刀法更為工整，具體呈現乾隆一朝的工藝水準。', N'通高 12.6 公分、徑 35.4 公分', N'/media/catalog/lacquer/中漆000052N000000000/display.jpg', N'/media/catalog/lacquer/中漆000052N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17457?dep=U', N'CC-BY-4.0', N'剔彩春壽寶盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('52245f0b-e445-c524-acc7-aa7f2f2f4a99', N'中漆000004N000000000', N'剔紅六角亭式香筒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'亭式香筒，上為六邊形屋簷式，脊端接銅飾，下懸銅鈴，瓶式銅頂，器身六面各鑲嵌一鏤雕萬壽紋牙片，六角形須彌座，有六如意式足。底座中設插孔，用來插置香枝。亭面雕番蓮紋，紋下雕六方朵花錦紋，脊面雕飾回紋，周雕如意雲紋作瓦當。六柱上方嵌飾藍白料珠串，柱身滿飾回紋，下端雕蕉葉紋、回紋及六方朵花錦紋。座上下端有番蓮紋，襯以斜方回紋及斜方朵花錦紋，折腰處雕變形蓮瓣紋，中間界以折帶紋一道。', N'通高 56.5 公分、徑 19.4 公分、座徑 15.6 公分', N'/media/catalog/lacquer/中漆000004N000000000/display.jpg', N'/media/catalog/lacquer/中漆000004N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17501?dep=U', N'CC-BY-4.0', N'剔紅六角亭式香筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d1cbc96e-c3c3-ae29-41a1-aa9b4c3ecc86', N'故雕000250N000000000', N'紫檀木靈芝盤', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'紫檀木雕靈芝形淺盤，周緣卷起，盤面磨琢出數道淺稜，如靈芝紋理。盤底圈足為浮雕靈芝二及竹枝，盤心刻填漆「吳下朱英製」楷款及「小松」填硃印，朱小松為明嘉靖、萬曆間著名竹雕名家。盤底滿刻明後期文人屠隆（1542-1605）之銘文，說明此件木雕盤原為盛放元末名家朱碧山銀卮的承盤。名家承盤配置名家銀卮，相得益彰。此盤是否真為朱小松所刻，尚待進一步考證，但以選材之精，造型線條簡約洗練，誠為木雕文玩之精品。', N'長 18.5 公分、寬 13.2 公分、高 2.8 公分', N'/media/catalog/carving/故雕000250N000000000/display.jpg', N'/media/catalog/carving/故雕000250N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/2471?dep=U', N'CC-BY-4.0', N'紫檀木靈芝盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b7d1c630-3a7f-4d09-6cff-aad8f53ba9f3', N'故畫00069600000', N'清王鑑臨王蒙松陰丘壑　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙四年（1665）', NULL, N'王鑑（1598－1677），祖父王世貞是明代後期文學復古運動的領袖。與王時敏同樣擁有淵厚家學，王鑑亦自幼喜好繪畫創作，並也強調仿古，與王時敏並稱為二王。然而王鑑所引用的古代傳統不限於黃公望，對於五代董源、巨然、元代的王蒙風格等，都有著濃厚興趣。在這件臨仿王蒙的作品中，取用王蒙慣用的構圖模式，並且援用許多相似母題，例如在前景的高大松樹，以及後景山頭的起伏造型，甚至筆墨皴線上強調捲曲扭動，也與王蒙筆意相通。此外，畫中部份特質則超乎王蒙風格之外。例如山體的構成更為清晰，筆墨亦顯得更為整順，處處彰顯清代仿古作風特質。（陳韻如）', N'101.8 × 48.3 公分', N'/media/catalog/painting/故畫00069600000/display.jpg', N'/media/catalog/painting/故畫00069600000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3474?dep=P', N'CC-BY-4.0', N'清王鑑臨王蒙松陰丘壑　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c444502c-9cb8-4abd-4176-ab10f4acba41', N'購瓷000154N000000000', N'灰釉直紋雙耳罐', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'春秋、戰國時期，江蘇、浙江一帶高溫灰釉器的燒造頗為盛行。這件灰釉瓷直紋雙耳罐，是以瓷土為胎，施以透明鈣灰釉，在1200度的高溫下燒製而成的作品。罐呈直口、斜肩、圓鼓腹、腹部下收、平底。肩上對稱位置有二環形繫耳，耳內銜環。胎呈黃褐色，器表施釉至器腹中間，釉色青黃，釉層較薄，並有剝釉現象。器身上最搶眼之處是位於肩部和上腹部的直紋瓦楞線刻紋，同樣的作品在浙江德清亭子橋窯址可以得見，江蘇無錫鴻山越國貴族墓葬中也有類似作品出土。', N'高 22.1 公分、腹寬 34.5 公分、口徑 17.5 公分', N'/media/catalog/ceramic/購瓷000154N000000000/display.jpg', N'/media/catalog/ceramic/購瓷000154N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43031?dep=U', N'CC-BY-4.0', N'灰釉直紋雙耳罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('da3ac4bc-d12f-e7d4-6850-ab204196528d', N'中日陶000077N000000000', N'灰陶耳杯', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'器形仿自漆器，杯身橢圓如船形，兩端微微上揚。器耳如新月狀。器底皆作橢圓形。全器平素無紋。出土不詳。', N'高 3.2 公分、口徑長 10.2 公分、寬 6.3 公分、底徑長 6.3 公分、寬 3.4 公分', N'/media/catalog/ceramic/中日陶000077N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000077N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71769?dep=U', N'CC-BY-4.0', N'灰陶耳杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e24c4aea-58ce-b176-f79d-ab93a374bdf0', N'購錢000248N000000000', N'宋元通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「宋元通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000248N000000000/display.jpg', N'/media/catalog/coin/購錢000248N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9586?dep=U', N'CC-BY-4.0', N'宋元通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7836c455-efa1-c8d3-e2f0-aba867ea2fc0', N'贈雕000043N000000000', N'牙觿', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'東周', NULL, N'器呈扁平觿形，尖端殘缺，首部磨平，並穿一孔以供繫掛。器之內緣多處蝕傷，全器呈淡綠色。類似的觿形器曾見於春秋與戰國墓葬中，為佩飾器；其質材有骨、牙、石、玉等，尤以玉製者較精美，此件則以牙製。', N'殘長 6.1 公分、最寬 0.9 公分、最厚 0.4 公分', N'/media/catalog/carving/贈雕000043N000000000/display.jpg', N'/media/catalog/carving/贈雕000043N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45269?dep=U', N'CC-BY-4.0', N'牙觿 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2276cdba-b441-5d7e-bec8-abc24feb4b44', N'中銅000015N000000000', N'三角雲紋盤', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'圓口，折沿，附耳，腹壁略直，圈足。腹、足皆飾三角雲紋。', N'高 10.1 公分', N'/media/catalog/bronze/中銅000015N000000000/display.jpg', N'/media/catalog/bronze/中銅000015N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6324?dep=U', N'CC-BY-4.0', N'三角雲紋盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('830e01ce-9d8d-0475-1840-abc65c14849b', N'中琺000678N000000000', N'掐絲琺瑯龍鳳紋觚', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'仿古銅器觚的形制，喇叭口，腹鼓起，胎外撇，圈足，鑲拐子鏤空稜脊四。銅胎，器壁飾藍地五彩法掐絲琺瑯，口頸內壁飾轉枝番蓮，外壁飾番蓮及幾何龍鳳紋，底鑄陽文「景泰年製」方框楷款。', N'高 39.7 公分、口徑 21.7 公分', N'/media/catalog/enamel/中琺000678N000000000/display.jpg', N'/media/catalog/enamel/中琺000678N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1532?dep=U', N'CC-BY-4.0', N'掐絲琺瑯龍鳳紋觚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b3b6bb63-5579-54a2-71e3-abeb19cdcaea', N'故雕000010N000000000', N'竹雕文字筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'全器截取竹子地上莖兩節間的一段，經整治與刮磨稱為「竹青」或「青筠」的表皮後，以大字深刻技法陰刻行書北宋蘇軾所作「江月」五言詩的詩引，然後另配以木質器底。所刻詩引本文十行，後接二行款識，全文如后：蘇子瞻曰：「嶺南風氣不齊。吾嘗云：菊花開時乃重陽，涼天佳月即中秋，不須以日月為斷也。今歲九月，殘暑方退，既望之後，月出逾遲。予嘗夜登合江樓，與客遊豐湖，入栖霞禪寺，扣羅浮道院，登逍遙堂，逮曉乃歸。杜子美云：四更山吐月，殘夜水明樓。殆古今絕唱也。」另低兩格陰刻行書款：「舜江王永芳錄於一枝居。」清嘉慶十二年（1807）金元鈺《竹人錄》專載嘉定竹刻藝術，上卷收錄了嘉定竹人王永芳，曰「王永芳字玉斧，自署舜江，工鐫字，墨守蘇文忠清勁洒落」。也就是說，王永芳擅長竹刻藝術中的陰刻文字，所作字跡總能展現出蘇東坡書法藝術的「清勁洒落」韻致。這件文字筆筒壁面所錄是蘇軾五首「江月」詩的引言，蘇軾生長於四川，對於熱帶或亞熱帶的嶺南氣候較陌生。蜀中菊花綻放於九九重陽前後，八月中秋時節天候已涼，但是嶺南遲至農曆九月，殘暑方退，此時月亮升起的時間也晚。雖然如此，蘇東坡反常於半夜起身，或游於江湖之上，或造訪寺院，不亦快哉！嘉定竹人陰刻文字，清前期所作者字體較大，清代中期日漸趨小，其他地區則有不少擅長篆刻的文人或印人以業餘之姿參與竹刻藝術之創作，其所作陰刻文字多偏小字，此時已不易覓得如王永芳這件筆筒上的文字般的長篇大字者！', N'通高 15.21 公分、口徑 6.8 公分', N'/media/catalog/carving/故雕000010N000000000/display.jpg', N'/media/catalog/carving/故雕000010N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62313?dep=U', N'CC-BY-4.0', N'竹雕文字筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('20cb347b-45f8-11fb-a1fc-ac0fb10529ed', N'贈雕000177N000000000', N'牙雕花鳥紋梳柄', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'橫長形梳之柄部，連接梳齒部位有數十道刻鑿梳齒之遺痕，梳齒已佚。器另三緣刻飾短鋸齒紋，其內凸弦紋兩道，在器上方弦紋部位鑿二小孔；弦紋內刻飾一圈連瓣紋，二孔下方飾一朵花，器中央一面飾淺浮雕折枝花，一面淺浮雕折枝花上飾一展翅鴻雁；兩面皆陰刻菱格紋襯地。', N'長 9.0 公分、寬 3.0 公分', N'/media/catalog/carving/贈雕000177N000000000/display.jpg', N'/media/catalog/carving/贈雕000177N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45405?dep=U', N'CC-BY-4.0', N'牙雕花鳥紋梳柄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('43db7f0c-4207-0b6a-3975-ad30666209ba', N'購錢000547N000000000', N'景德元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面楷書：「景德元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000547N000000000/display.jpg', N'/media/catalog/coin/購錢000547N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9885?dep=U', N'CC-BY-4.0', N'景德元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('459e2a3b-095e-370b-a031-ad461aab5a4e', N'中玉000007N000000000', N'花卉紋雙耳爐', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'青玉爐，爐身作大小不一重瓣花形，附蓋、活環耳、圈足。全器以不同技法飾莨苕與薔薇等花葉紋：蓋鈕為鏤空透雕花葉、雙耳上有立雕花葉，蓋面與器身則以陰刻的方式呈現盛開的花卉與草葉。', N'通寬 16.3 公分、蓋徑 9.2 公分、口徑 8.9 公分、底徑 7.8 公分', N'/media/catalog/jade/中玉000007N000000000/display.jpg', N'/media/catalog/jade/中玉000007N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52745?dep=U', N'CC-BY-4.0', N'花卉紋雙耳爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('31138901-3166-29a6-b126-ae4092cd51c3', N'贈雕000039N000000000', N'磋牙長柱細腰', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'周', NULL, N'長柱形，剖面呈圓形，中腰細縮，兩端徑較小，局部已染成鮮綠色，器身滿佈裂璺。此器與灃西出土的骨細腰外型相似，然此器以牙為材，當時視牙骨為同類質材。', N'長 6.6 公分、最大徑 1.4 公分', N'/media/catalog/carving/贈雕000039N000000000/display.jpg', N'/media/catalog/carving/贈雕000039N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45265?dep=U', N'CC-BY-4.0', N'磋牙長柱細腰 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e35fbfed-6ca4-c568-eca5-aeafc61cce31', N'故漆000298N000000000', N'剔紅牡丹圓盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'弧璧形盤，圈足，足內髹褐漆。盤內外均裝飾牡丹花。底部外緣平均安排四朵盛開的牡丹，間隔一朵半開的花，花間飾三片一組的葉片。底盤面裝飾牡丹，中央一朵盛開的花朵，外圈四朵，其間並一半開的花朵，兩圈之間葉片烘托，並有小花苞。主幹隱約可見自右下伸入，葉片的方向也是從右下往左，然後往上至圓心，再向四方發散，花葉的佈局富裝飾性美感，與植物生長實況差距較大。枝葉分佈茂密，花與葉位於同一平面，構圖滿溢，微露底漆。漆色紅而偏暗，漆質潤而微澀，漆層薄，花瓣起伏強烈，在光影中閃爍，盤子的尺寸大，整體效果華麗。英國牛津大學博物館也收藏一件宣德款四季花卉大盤。', N'高 4.2 公分、口徑 32.6 公分、足徑 25.3 公分', N'/media/catalog/lacquer/故漆000298N000000000/display.jpg', N'/media/catalog/lacquer/故漆000298N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18037?dep=U', N'CC-BY-4.0', N'剔紅牡丹圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('78874dd1-242f-1ad2-1f14-aeb5d13741df', N'故漆000117N000000000', N'剔紅聽松圖圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅圓盒，色紅。子母口，淺直壁，平底。蓋面雕松林間二老者持杖並行，前有負琴童子，器與蓋側面滿飾花卉與葉。器裡與底髹黑色光漆。', N'高 7.5 公分、徑 6.9 公分', N'/media/catalog/lacquer/故漆000117N000000000/display.jpg', N'/media/catalog/lacquer/故漆000117N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18063?dep=U', N'CC-BY-4.0', N'剔紅聽松圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('85326f54-54fa-496e-fa68-aee5e89609f7', N'故瓷012455N000000000', N'白瓷雙龍耳瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'細長頸，兩龍張口向瓶中作吸食狀，形成兩弧形優美之耳。淺青釉斑剝，僅罩住器之上部，下部皆露胎，釉面有細碎紋片，露胎處有淺絳色之大塊斑點。雙龍耳瓶或稱為雙龍柄壺，是唐代常見的器形之一。它的用途至今不明，目前所見作品因多半出土自墓葬，故可將之看成是祭器或明器。這件原屬清宮舊藏的雙龍耳瓶，從雍正、乾隆兩朝官窯相繼仿燒相似的器型看來，至少出土於雍正朝或更早以前。', N'通高 36.6 公分、口徑 6.8 公分、底徑 9.2 公分', N'/media/catalog/ceramic/故瓷012455N000000000/display.jpg', N'/media/catalog/ceramic/故瓷012455N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36040?dep=U', N'CC-BY-4.0', N'白瓷雙龍耳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1bf22bf2-d3cf-b620-4ff6-af7c01396ec1', N'故雕000003N000000000', N'沉香木雕山水筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'用沉香木隨形雕刻而成，以高浮雕與淺浮雕相互運用，雕屋舍於層巒山石與鬱鬱林木間，兩件一對，同樣作為陳設器。沉香取材不易，又為成對雕件，可見宮廷陳設之奢華。北京故宮見有類似藏品。據《點查報告》此對原出於敬事房，或為《宣統十四年‧敬事房小漆木器實存》之「沉香鑲銅裏筆筒一對」。', N'高 13.0 公分、最大徑 13.0 公分', N'/media/catalog/carving/故雕000003N000000000/display.jpg', N'/media/catalog/carving/故雕000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62308?dep=U', N'CC-BY-4.0', N'沉香木雕山水筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ddbf6899-dc67-1b36-7cd3-afb3884d668a', N'中玉000314N000000000', N'玉刀', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'玉質，本應為半透明青灰色，現為土沁成深淺不一的棕色。長方形玉片，刃邊略圓弧，有二道細凸弦紋，把手以淺浮雕與陰線刻作一鳳鳥，鳳長尖喙，眼作小孔以穿佩，羽翅流線繁複，雙面同紋。', N'長 28.6 公分、寬 3.8 公分、高 0.2 公分', N'/media/catalog/jade/中玉000314N000000000/display.jpg', N'/media/catalog/jade/中玉000314N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53065?dep=U', N'CC-BY-4.0', N'玉刀 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6ec2f19d-b810-6241-ea93-b0f777fa5337', N'中日陶000108N000000000', N'灰陶龍首勺', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'圓底，平口，有柄。勺口由外向器柄內縮，橫剖面似桃形。器柄平直。全器平素無紋，唯柄端飾一龍首，似為模制。器內側塗朱。', N'長 15.2 公分、寬 6.8 公分、高 4.1 公分', N'/media/catalog/ceramic/中日陶000108N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000108N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71764?dep=U', N'CC-BY-4.0', N'灰陶龍首勺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1b24fd7c-2be2-992c-4a12-b12cd4e941d2', N'中琺000122N000000000', N'掐絲琺瑯夔龍紋轎瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'銅胎，前面為侈口豐肩斂腹瓶，連接浮雕式夔龍紋之座，靠牆面平，頸下方有一孔可以直接掛在牆面的釘上，故稱壁瓶，清檔中稱之轎瓶。此型器始見於唐朝，清代盛行於乾隆時期。此瓶綠地以淺綠色夔龍為錦，瓶腹掐絲「御製」二字，詞句則採掐絲雙鉤填墨的方式「隨分芳菲擷，觸懷長短哦。」落「臣于敏中」紅地陽文鍍金字、「恭寫」鍍金地陰文填紅字。于敏中（1714-1779），乾隆二年（1737）中狀元，工書法，歷官文華殿大學士，二十五年（1760）入懋勤殿奉敕寫華嚴經寶塔，廷論多出其手。瓶內插由青金石、碧璽與碧玉製成的花枝。（造辦處各作成做活計清檔）雍正六年（1728）九月二十七日，曾做得琺瑯桃式掛瓶一件，隨象牙茜色長春花一束。', N'高 23.5 公分', N'/media/catalog/enamel/中琺000122N000000000/display.jpg', N'/media/catalog/enamel/中琺000122N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1563?dep=U', N'CC-BY-4.0', N'掐絲琺瑯夔龍紋轎瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6d82351e-1e0c-81ce-6395-b2bc714e0571', N'故玉000011N000000000', N'玉勾連雲紋璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國晚期', NULL, N'器身作板狀圓形，中心圓孔，玉璧本身為新石器時代晚期齊家文化的作品，紋飾為明晚期至清早期後加。兩面均琢雕勾連雲紋。玉色青白細潤，受沁處呈深淺不一褐色。周緣鐫篆書乾隆乙未(四十年，1775)御題，下有篆文「乾」「隆」連珠方璽。', N'徑 20.0 公分、厚 0.7 公分', N'/media/catalog/jade/故玉000011N000000000/display.jpg', N'/media/catalog/jade/故玉000011N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48209?dep=U', N'CC-BY-4.0', N'玉勾連雲紋璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('76918aee-6a1c-2a8b-d591-b2e9f62468e2', N'南購畫00001300000', N'東海道三 五十三次 川崎', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪川崎宿（神奈川縣川崎市川崎區）風景，畫面由右而左標示「東海道三」、「五十三次 川崎」、畫面右下角「廣重画」、畫面左下角副題「六郷のわたし」，畫面框外右下角一半「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001300000/display.jpg', N'/media/catalog/painting/南購畫00001300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36468?dep=P', N'CC-BY-4.0', N'東海道三 五十三次 川崎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('91ae8050-c92d-25fe-5e8a-b4073842adcb', N'中琺000032N000000000', N'掐絲琺瑯萬壽無疆碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'口微撇，深壁，圈足。器身紋飾以掐絲技法完成，器表淺藍地，四圓形開光平均分列，內各有一深藍地篆體金字：「萬」、「壽」、「無」、「疆」，開光隙地各飾一組五彩轉枝番蓮紋。腹底與口緣紋飾以內填琺瑯技法完成，腹底飾一圈綠地鑄飾蓮瓣紋，碗緣飾綠地鍍金製拐子龍紋邊飾。底陰刻「子孫永寶」四字雙行雙方框篆款。', N'高 5.8 公分、深 4.8 公分、口徑 12.5 公分、足徑 7.3 公分', N'/media/catalog/enamel/中琺000032N000000000/display.jpg', N'/media/catalog/enamel/中琺000032N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53909?dep=U', N'CC-BY-4.0', N'掐絲琺瑯萬壽無疆碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9fa802fd-c1af-bb8c-a8cd-b4716d91d43f', N'故琺000717N000000000', N'掐絲琺瑯花卉紋玉壺春式瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯，圓口，長頸，斜肩，垂腹，短圈足。口緣飾有花卉紋，頸部為一圈蕉葉紋及葡萄紋，腹部為藍底雲紋錦地折枝四季花卉紋，器腹下緣飾有一圈蕉葉紋，圈足上飾有花卉紋。', N'高 33.1 公分', N'/media/catalog/enamel/故琺000717N000000000/display.jpg', N'/media/catalog/enamel/故琺000717N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61757?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉紋玉壺春式瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fdd6de38-97e3-fd00-7cfc-b49ce38380bf', N'中琺000126N000000000', N'掐絲琺瑯花卉紋三足爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'鍍金口，短頸，扁腹，雙獸首啣環耳，平底，三柱形足，帶鏤空番蓮紋平頂蓋，蓮瓣座太極頂鏤空番蓮紋鈕。全器淺藍地，頸部飾一圈海棠紋，下接一圈如意雲紋，腹部及足有卷枝番蓮紋，底部飾菊花紋，足部下緣飾如意雲紋。中琺126、127、128為一組。', N'通高 13.2 公分', N'/media/catalog/enamel/中琺000126N000000000/display.jpg', N'/media/catalog/enamel/中琺000126N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53998?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉紋三足爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5bbc830e-b48f-4cca-89b3-b4d4d7398b01', N'故雕000006N000000000', N'竹雕仕女庭園圖筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'筆筒以竹雕刻而成，底帶三矮足。器表飾亭台樓閣，周遭密佈峻石、梧桐、松、竹與芭蕉樹。平房內桌上置一硯，一仕女手持毛筆，臨窗書寫。桌前一人拱手而立，門外一仕婢捧碗正欲進屋。房屋雕飾細膩，屋簷刻有如意紋與回紋。竹筒背面飾雕有花紋之欄杆，上端雕有涼亭，內有方桌。', N'通高 16.0 公分、口徑 16.0 公分', N'/media/catalog/carving/故雕000006N000000000/display.jpg', N'/media/catalog/carving/故雕000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62311?dep=U', N'CC-BY-4.0', N'竹雕仕女庭園圖筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f4a8508c-87c0-ffaa-b52a-b4fe92760901', N'中玉000012N000000000', N'玉四足盒', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'青玉橢圓小盒，玉色泛灰綠，蓋與器身略相等，四小足，向外侈出。蓋中心有一橢圓形突起，光素無紋。', N'通寬 4.9 公分、通高 3.1 公分', N'/media/catalog/jade/中玉000012N000000000/display.jpg', N'/media/catalog/jade/中玉000012N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52751?dep=U', N'CC-BY-4.0', N'玉四足盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fed210a7-3b9e-e4d0-c441-b58aea753a41', N'南購畫00001800000', N'東海道八 五十三次 平塚', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪平冢宿（神奈川縣平冢市），畫面由右而左標示「東海道八」、「五十三次 平塚」、「廣重画」，畫面框外右下角一半「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001800000/display.jpg', N'/media/catalog/painting/南購畫00001800000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36473?dep=P', N'CC-BY-4.0', N'東海道八 五十三次 平塚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('56eab6f1-2403-b62b-0d73-b5c858c4587d', N'南購畫00002800000', N'東海道十八 五十三次 興津', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪興津宿（靜岡縣靜岡市清水區）風景，畫面由右而左標示「東海道十八」、「五十三次 興津」、「廣重画」，畫面左下副標「清美ヶせき 清見寺」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002800000/display.jpg', N'/media/catalog/painting/南購畫00002800000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36483?dep=P', N'CC-BY-4.0', N'東海道十八 五十三次 興津 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('017ba830-ffe0-860f-6d78-b5d695ec9507', N'中瓷002228N000000000', N'白瓷碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'敞口大碗，深弧壁下斂，圈足。口緣銅釦，器內外壁施透明釉，見白胎色，只在圈足積釉處泛青。內外壁均光素無紋，但外壁隱約可見輪製痕。底足內滿釉無款識。', N'高 7.2 公分、口徑 21.5 公分、底徑 7.0 公分', N'/media/catalog/ceramic/中瓷002228N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002228N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/23708?dep=U', N'CC-BY-4.0', N'白瓷碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e111bc3d-8ad1-10e8-e4cc-b7f573156357', N'南購畫00002300000', N'東海道十三 五十三次 沼津', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪沼津宿（靜岡縣沼津市）風景，畫面由右而左標示「東海道十三」、「五十三次 沼津」、畫面左下「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002300000/display.jpg', N'/media/catalog/painting/南購畫00002300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36478?dep=P', N'CC-BY-4.0', N'東海道十三 五十三次 沼津 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9b974b23-0898-bdd2-109b-b7ff836e5dd2', N'故漆000401N000000000', N'剔紅布袋彌勒人物圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'扁圓形盒，子母口，口外侈，圈足，足內及盒內髹黑漆。盒身刻水波地菊花紋，連續起伏的水波，以斜刀刻劃出重疊的線條，菊花兩兩成組，高高浮起。盒蓋主題人物底層滿飾錦地，下側的六角花形錦地與上側的水波紋，以一線分隔，巧妙出表現地與水的空間，線條整齊卻不呆板。大肚彌勒背負著袋，一手持麈扇，一肩荷長杖，杖尖遙指著彎月。彌勒回首，笑容可掬，臉上肌肉誇張凹凸，對形象掌握純熟，漆色紅潤，漆層薄，刀法靈活，人物生動。', N'高 2.5 公分、盒徑 5.4 公分、底徑 4.1 公分', N'/media/catalog/lacquer/故漆000401N000000000/display.jpg', N'/media/catalog/lacquer/故漆000401N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62065?dep=U', N'CC-BY-4.0', N'剔紅布袋彌勒人物圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c078f3b3-4ce5-f15d-b422-b81d534b4216', N'中玉000008N000000000', N'玉獸面瓶', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'青白玉瓶，扁身，雙耳，有圈足。耳做透雕夔紋。腹飾獸面紋，上下為蕉葉紋。', N'高 11.7 公分、腹徑 4.3 公分', N'/media/catalog/jade/中玉000008N000000000/display.jpg', N'/media/catalog/jade/中玉000008N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52746?dep=U', N'CC-BY-4.0', N'玉獸面瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('59c3b333-e1b9-5886-d3b3-b84c598131f0', N'中琺000587N000000000', N'掐絲琺瑯雙魚耳蓋罐', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'斂口，深壁，圈足，雙鯰型耳，帶蓮瓣座蓮苞鈕圓頂蓋一。器表飾十字紋錦地，蓋緣及器腹四邊有如意雲形開光，內飾紅、藍蝙蝠紋及番蓮紋，開光隙地飾圓形淺綠底紅色團壽字，鯰魚嘴中心有一孔。底有鑄刻去地陽文「景泰年製」四字雙行楷書方框款。', N'高 42.5 公分、口徑 30.0 公分、底徑 17.5 公分', N'/media/catalog/enamel/中琺000587N000000000/display.jpg', N'/media/catalog/enamel/中琺000587N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54418?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙魚耳蓋罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('aa4028bf-d755-ae9d-c69a-b84ef724809e', N'中玉000434N000000000', N'玉蟬', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'玉質，色青白部分顯半透明，有赭斑。全器作蟬形，中央厚，尾端較薄。頂端有一象鼻穿。全器線條簡單，淺琢出首、頸，羽翅與腹等部位。漢代玉唅蟬多為偏暗的青碧玉質，而且作工簡略，這是因為唅蟬的功能是放置於過世大貴族的口中，以期羽化重生的喪葬用玉，因此選材和琢磨方式自有定制。唅蟬因使用方式之故毋須繫帶穿孔，而此件玉唅蟬上下貫通的穿孔，乃後世不知唅蟬的原始功能，而將其改為佩戴玉墜之故。', N'長 6.1 公分', N'/media/catalog/jade/中玉000434N000000000/display.jpg', N'/media/catalog/jade/中玉000434N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53193?dep=U', N'CC-BY-4.0', N'玉蟬 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b8494b4f-fce6-005c-f4f3-b88928617893', N'中漆000013N000000000', N'剔紅佛塔', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅藏式塔形龕，色正紅，明艷有光澤。覆缽式圓塔身，九重簷(剎輪)，塔頂寶珠已失。塔身雕滿番蓮花葉紋，一面開背光式龕門，內有剔紅八角形須彌式佛座，下接蓮瓣紋圈足，塔剎板形簷周雕六角朵花錦紋間卍字或蝠，塔頂寶蓋作回紋一周，上有俯仰蓮瓣紋座一。', N'高約 67.0 公分、徑約 32.0 公分', N'/media/catalog/lacquer/中漆000013N000000000/display.jpg', N'/media/catalog/lacquer/中漆000013N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17548?dep=U', N'CC-BY-4.0', N'剔紅佛塔 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d177ebf2-0dab-43be-66e8-b8cb15e3e1db', N'贈雕000132N000000000', N'骨雕填彩管', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'截取一段獸骨，器表細線陰刻紋飾，中央下方飾向左奔行之四獸馳於地，上方飾兩組飛禽翔於天，山與雲錯落其間；器之上下緣各飾兩道三角形紋，一道為正三角形，另一道則為倒三角形；下緣又飾一圈菱形紋。三角形、菱形、走獸、飛禽等紋飾輪廓內皆滿刻斜陰線，並填紅或黑彩。此器紋飾刻工流暢，紋樣與西漢漆器上陰刻或彩繪紋飾相類。其功能或與車馬有關。', N'高 3.0 公分、徑 2.1 公分', N'/media/catalog/carving/贈雕000132N000000000/display.jpg', N'/media/catalog/carving/贈雕000132N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45361?dep=U', N'CC-BY-4.0', N'骨雕填彩管 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bfdef337-f707-81e5-7b60-b91673fce68e', N'中銅000347N000000000', N'十二生肖紋鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'f5c52376-b481-305c-56f3-e2750e018bb6', N'隋', NULL, N'圓形鏡，半球鈕，圓鈕座，座上有「光正隨人，長命宜新」銘文，字間有小凸點。鈕座外環卷草紋一周，外圈為十二方格，各填以雲氣環繞的十二生肖動物。最外圈為鋸齒紋。三角斜緣。同類鏡曾出土於河南陝縣劉家渠劉偉墓及陝西西安李靜訓墓中，為隋初發展出的新式銅鏡紋樣。', N'直徑 15.2 公分', N'/media/catalog/bronze/中銅000347N000000000/display.jpg', N'/media/catalog/bronze/中銅000347N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7156?dep=U', N'CC-BY-4.0', N'十二生肖紋鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a458494e-d17f-3549-7164-b9b4b2d80103', N'購錢003814N000000000', N'崇寧重寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，「崇寧重寶」有銅、鐵兩種材質。正面有隸書「崇寧重寶」四字，相傳為蔡京所書，背面無文。', N'待測量', N'/media/catalog/coin/購錢003814N000000000/display.jpg', N'/media/catalog/coin/購錢003814N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13152?dep=U', N'CC-BY-4.0', N'崇寧重寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('580b2cd3-b2af-d6b2-724a-ba1d1e809136', N'中漆000028N000000000', N'紅雕漆窩角方龕', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅窩角方龕，色硃紅至暗紅。正方形委角須彌式座，周圍矮護欄，前設六級台階，龕壁上承佛冠式頂，上有寶頂，龕壁與頂已鬆脫分置。台座雕飾蓮瓣紋與番蓮紋，階梯作斜方萬字錦地，龕壁前三面開光，以雕雲紋邊框嵌玻璃，龕頂仰式冠內覆委角罩式頂，皆雕番蓮花，方形小座上有銅製寶塔式頂。龕座上有金屬製菩薩座像。', N'長約 45.0 公分、寬約 45.0 公分、通高約 84.0 公分', N'/media/catalog/lacquer/中漆000028N000000000/display.jpg', N'/media/catalog/lacquer/中漆000028N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17564?dep=U', N'CC-BY-4.0', N'紅雕漆窩角方龕 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('de1c1bf6-5c49-aadf-81a5-ba51eae2bd76', N'故畫00150400000', N'元趙孟頫醉菊圖　卷', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元武宗至大二年（1309）', NULL, N'白描畫陶淵明事蹟。陶淵明（西元三六五—四二七年），晉宋時期詩人、辭賦家、散文家。一名潛，字元亮。曾為州祭酒，後為彭澤令。因不能「為五斗米折腰」，棄官歸隱，躬耕自給，以詩酒自娛。晚年貧病交攻，卒後世稱靖節先生。其詩自然樸素，其人名行高潔，為文士的象徵。其嗜酒、賞菊等情狀，向為後世畫家所喜繪。卷末款趙孟頫，是元代文人畫壇領袖。本卷就筆墨來看，不類趙氏風格。', N'30.8 × 536 公分', N'/media/catalog/painting/故畫00150400000/display.jpg', N'/media/catalog/painting/故畫00150400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/15775?dep=P', N'CC-BY-4.0', N'元趙孟頫醉菊圖　卷 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a09b61a3-bbc7-ceca-4ce2-badfc0ef7539', N'中雕000009N000000000', N'雕犀角梅樹香插', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'〈犀角雕花籃〉及〈犀角雕梅樹香插〉（中雕9、中雕10），是造型罕見的犀角雕，一件雕仿竹編提籃，提把可活動，籃中探出鏤雕梅枝水仙，刻工質樸。另一件鏤雕老幹虯枝的梅樹，梅花含苞待放，樹幹中空可做香插，刀法純熟。兩件成組被置於紫檀木座上，一深一淺，是質樸與清雅兼具的陳設。', N'長 9.3 公分、寬 7.8 公分、高 5.9 公分', N'/media/catalog/carving/中雕000009N000000000/display.jpg', N'/media/catalog/carving/中雕000009N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18528?dep=U', N'CC-BY-4.0', N'雕犀角梅樹香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7141b104-5eed-90d7-fe10-bc4c0dc56e19', N'中漆000076N000000000', N'剔紅八寶番蓮紋爐', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'爐，圓腹，雙長耳，三獸蹄形足。外髹朱漆，內塗金漆。口沿、耳側雕回紋，頸、腹、足、耳面雕捲枝番蓮紋，腹加飾八寶紋，襯以菱格花朵錦地紋。口沿雕「大清乾隆年製」六字篆款。為供具，一爐、二瓶、二燭台合稱「五供」，此為其中的爐。院藏中漆76-中漆80為一套五供。', N'高 22.2 公分、通高 27.4 公分、深 12.0 公分、口徑 16.2 公分、足徑 3.3 公分', N'/media/catalog/lacquer/中漆000076N000000000/display.jpg', N'/media/catalog/lacquer/中漆000076N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17476?dep=U', N'CC-BY-4.0', N'剔紅八寶番蓮紋爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('67f0ff4e-fc07-e7b7-1e47-bc72bd91d915', N'故漆000125N000000000', N'剔紅人物戲獅圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'剔紅小盒，色硃紅，器身有傷損。子母口，淺直壁，平底。蓋面雕一獅，其後有蕃人側身飛起作降獅狀，姿態甚異，器身與底雕荔枝，皆以斜方朵花錦為地。器與蓋內髹黑色光漆。', N'高 12.9 公分、口徑 33.1 公分、足徑 28.0 公分、深 5.9 公分', N'/media/catalog/lacquer/故漆000125N000000000/display.jpg', N'/media/catalog/lacquer/故漆000125N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18071?dep=U', N'CC-BY-4.0', N'剔紅人物戲獅圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5ec59b6a-c798-c940-e591-bcbe4649cfd3', N'故玉003130N000000000', N'玉戚', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'黃色玉質，局部帶有綠色及褐色斑，質地溫潤。器身作略不對稱梯形，近背端鑽有一孔，平背，平刃，兩側各刻飾五個牙飾。', N'長（中軸）13.0 公分、寬 8.5 公分、厚 0.6 公分', N'/media/catalog/jade/故玉003130N000000000/display.jpg', N'/media/catalog/jade/故玉003130N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/423?dep=U', N'CC-BY-4.0', N'玉戚 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('297d7870-2635-3798-0ec0-bd441ef43f41', N'贈雕000055N000000000', N'骨嵌綠松石龍紋帶鉤', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'全器用一塊骨材製成，鉤首簡略刻出龍首形，雙角內陰刻弦紋，器身細線陰刻三角紋、圈點紋等，中央隆起偏鉤首部位陰刻兩道弦紋，中央飾相對二連續弧形紋，其內密戳小點，相對弧形間飾三個小單圈點紋；器身後段自隆起部位分叉，似欲組成共龍首的雙身龍紋，器身嵌飾綠松石，二處嵌件脫落僅留凹坑。在已發表的資料中，骨質帶鉤幾乎都屬戰國時代，河北石家莊市莊村戰國遺址曾出土類此後段分叉的骨質帶鉤。帶鉤可供繫帶，也可懸佩器物，有的帶鉤則僅作佩飾，似此長型帶鉤，則多做繫帶的帶鉤。', N'長 14.2 公分', N'/media/catalog/carving/贈雕000055N000000000/display.jpg', N'/media/catalog/carving/贈雕000055N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45281?dep=U', N'CC-BY-4.0', N'骨嵌綠松石龍紋帶鉤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('cfc908d4-3868-ae4e-13ca-bd9a6827d254', N'中銅000005N000000000', N'弦紋洗', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'洗，侈口、圓深腹、平底、三足，口沿殘傷。腹飾弦紋及四獸面環耳。', N'高 15.5 公分', N'/media/catalog/bronze/中銅000005N000000000/display.jpg', N'/media/catalog/bronze/中銅000005N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6238?dep=U', N'CC-BY-4.0', N'弦紋洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bf3e13a8-cc37-0a44-90bb-bee8f63aaf16', N'贈錢001255N000000000', N'順治通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「順治通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001255N000000000/display.jpg', N'/media/catalog/coin/贈錢001255N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9078?dep=U', N'CC-BY-4.0', N'順治通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fc1796dd-7cbe-9237-77f5-bf00fb6ec842', N'故畫00049300000', N'明文徵明燕山春色圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖三年（1524）', NULL, N'是年，徵明在京師。集中詩有朝賀，恭候大駕還自南郊，觀駕幸文華聽講，宴慶成，再與慶成，實錄成賜燕禮部，臘日賜燕諸詩。蓋修國史，侍講筵，每日趨朝，甚為忙碌。　　此幀細筆大幅，皴山點樹，筆有凝滯倉促處。事務繁劇中，強定心神，所作間亦有此，蓋非適志之品。題詩：「屋角疏花紅自好，相看終不似江南」。意亦怏怏。徵明五十五歲。', N'147.2 × 57.1 公分', N'/media/catalog/painting/故畫00049300000/display.jpg', N'/media/catalog/painting/故畫00049300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3292?dep=P', N'CC-BY-4.0', N'明文徵明燕山春色圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a651f820-bc25-deb1-ecde-bf3aa43226cd', N'中瓷000689N000000000', N'青瓷洗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'宋', NULL, N'圓口，深直壁，口緣鑲嵌銅釦，底部一圈塗褐色護胎汁，足傷缺處，顯見灰白色胎。全器滿施青灰釉，釉面滿佈大小開片，外底中心刻「甲」字。', N'高 8.3 公分、口徑 16.0 公分、底徑 14.0 公分', N'/media/catalog/ceramic/中瓷000689N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000689N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18525?dep=U', N'CC-BY-4.0', N'青瓷洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('baaa0f14-43ed-8043-e3f5-c0628c8b5ddc', N'故畫00049000000', N'明文徵明江南春圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖二十六年（1547）', NULL, N'文徵明，江蘇長洲人，初名壁，字徵明，後以字行，亦字徵仲，號停雲生、衡山居士。詩文書畫並佳，畫師沈周，而別有成就，為明四大家之一，影響明代晚期畫風甚鉅。（童文娥）', N'106 × 30 公分', N'/media/catalog/painting/故畫00049000000/display.jpg', N'/media/catalog/painting/故畫00049000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3289?dep=P', N'CC-BY-4.0', N'明文徵明江南春圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('62c61c6f-3dd9-3999-d35a-c0716f519a1d', N'中瓷002577N000000000', N'定窯 白瓷印花分格四季花卉紋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'敞口、弧形深壁碗、圈足。全器施釉，外壁釉汁流淌，僅口緣無釉鑲銅棱釦。器裡印花為飾，口沿下方以卷草紋為窄邊飾，細陽線將內壁豎分六等分，分別飾蓮、牡丹、月季、山茶等折枝四季花卉；底心則印一叢菊花。印模刻紋深，但匠者製器時略有用力不均，故部分印紋清晰至葉脈縷縷可見，部分印紋模糊。此類分格紋飾裝飾，在金末臨淄窖藏、農安窖藏均可見；而在南宋金銀器中亦經常可見。', N'高 7.7 公分、口徑 21.5 公分、底徑 7.0 公分', N'/media/catalog/ceramic/中瓷002577N000000000/display.jpg', N'/media/catalog/ceramic/中瓷002577N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19925?dep=U', N'CC-BY-4.0', N'定窯 白瓷印花分格四季花卉紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2502a1f5-c295-6c7d-04bf-c10dbc0036bf', N'贈雕000127N000000000', N'骨雕雲紋環', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'西漢', NULL, N'將骨材磨成環形，內圈圓弧突起，其外沿突出一圈；外緣呈鋸齒狀，圓弧內圈突起部位細線陰刻雲氣紋，全器不規則地偏向一方穿鑿四孔以供固定，器背略平，有鑲嵌遺痕。西漢漆器上可得見類似細線陰刻雲氣。', N'外徑 5.7 公分、孔徑 2.9 公分', N'/media/catalog/carving/贈雕000127N000000000/display.jpg', N'/media/catalog/carving/贈雕000127N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45356?dep=U', N'CC-BY-4.0', N'骨雕雲紋環 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f2ab0e04-b33d-a691-da5a-c16193826678', N'贈瓷000479N000000000', N'三彩印團花紋長盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'長盤，花形口寬唇，淺壁，平底。器施綠、褐、白三彩，底露胎無釉。唇壁印卷草紋，內底印三朵花，以葉紋為錦地。', N'長 30.4 公分、寬 18.0 公分、高 2.4 公分', N'/media/catalog/ceramic/贈瓷000479N000000000/display.jpg', N'/media/catalog/ceramic/贈瓷000479N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43508?dep=U', N'CC-BY-4.0', N'三彩印團花紋長盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('66cf1783-1875-4048-693b-c205ed95996b', N'中漆000006N000000000', N'剔彩六瓣三層套盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'三層套盒，六瓣花式，附座。外髹紅、黃、綠三色漆，內漆黑光。蓋面雕壽星騎鹿，前後各一童子，前者持磬，後者執杖，周圍以松竹山石，空隙處刻平行回紋、菱格朵花錦紋、六方朵花錦紋及水波錦紋，以繁密的幾何紋填滿空隙為漆器獨特的裝飾手法。周壁兩層雕番蓮紋，紋間為黃色素地；兩層雕折枝花果紋，襯以菱格朵花錦紋。座面淺刻萬字錦紋，壁飾番蓮紋。器內加飾描金花卉紋。', N'通高 24.5 公分、各層高 5.5 公分、深 3.9 公分、口徑 18.6 公分', N'/media/catalog/lacquer/中漆000006N000000000/display.jpg', N'/media/catalog/lacquer/中漆000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17503?dep=U', N'CC-BY-4.0', N'剔彩六瓣三層套盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('04f48eb1-f76f-ea0c-e1a9-c213933479eb', N'故畫00041700000', N'明杜瓊南湖草堂圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明憲宗成化四年（1468）', NULL, N'杜瓊（西元一三九六－一四七四年），字用嘉，號鹿冠道人，世稱東原先生，江蘇吳縣人。從小勤奮好學，讀書過目不忘。學識淵博，人品高潔，但卻終身不仕。　　善畫山水，初師吳鎮，兼學董巨和王蒙。此圖考其畫筆，與王紱最為接近，其用意則又遠追黃公望。風格蒼秀細潤，老筆縱橫，樸實拙逸，為士人畫中佳作。畫作於成化四年（一四六八），先生時年七十三歲。', N'119.8 × 55.5 公分', N'/media/catalog/painting/故畫00041700000/display.jpg', N'/media/catalog/painting/故畫00041700000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3216?dep=P', N'CC-BY-4.0', N'明杜瓊南湖草堂圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d6819d0c-9b14-644f-31db-c26bbf81a815', N'故漆000118N000000000', N'剔紅菊花式盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'盒作圓形，口微斂，矮壁，淺圈足。髹紅色漆。蓋面雕菊花瓣紋，中心飾花蕊。器周壁雕壽山福海，裏、底均髹黑色光漆。無款識。', N'高 2.7 公分、徑 5.5 公分、足徑 3.6 公分', N'/media/catalog/lacquer/故漆000118N000000000/display.jpg', N'/media/catalog/lacquer/故漆000118N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18064?dep=U', N'CC-BY-4.0', N'剔紅菊花式盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5ec8a34b-f88e-3ad9-a3d8-c2ad17986577', N'故玉000544N000000000', N'龜游荷葉洗', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'宋至元', NULL, N'青玉玉質瑩潤半透明，帶褐黃、墨綠瑕沁斑。洗雕為一大一小荷葉，大葉為洗，小葉為柄，各有一隻烏龜伏於葉心，外壁雙陰線刻葉脈，背面鏤雕枝葉相連慈菇，轉折有款。此器附紫檀木座，木座亦雕荷葉蓮花，帶「乙」字刻款。', N'長 11.5 公分、寬 11.6 公分、高 3.5 公分', N'/media/catalog/jade/故玉000544N000000000/display.jpg', N'/media/catalog/jade/故玉000544N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48741?dep=U', N'CC-BY-4.0', N'龜游荷葉洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fe4195c8-2cf1-de67-661f-c337e65a902d', N'贈漆000007N000000000', N'黑漆方盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', 'f2a78063-931b-9926-749c-324377d136c7', N'宋至元', NULL, N'盤，矮圈足，四壁斜弧侈張，四隅微凹。通身髹黑漆，盤底矮圈足內朱漆繪出長方框，內書「□公用」，入手甚輕，器壁甚薄。', N'長 14.5 公分、寬 14.3 公分、高 1.9 公分', N'/media/catalog/lacquer/贈漆000007N000000000/display.jpg', N'/media/catalog/lacquer/贈漆000007N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/104?dep=U', N'CC-BY-4.0', N'黑漆方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fe4d20ca-20c5-1bcc-c54a-c3ea3701153e', N'贈銅000435N000000000', N'日本 江戶時代 十七－十九世紀 銅鎏金雙身天王立像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代 十七~十九世紀', NULL, N'兩位天王背對背而立，站在雲形飾的圓座上。身著盔甲，口角咬著似長索狀物，合掌，一位天王掌形向上持法輪，一位天王掌形向下，持物已失。天王的頭形方，頸繫巾，肩飾瓣形蓋，兩袖多層層疊，袖緣翻折，腰帶厚重翻轉，甲冑陰刻幾何形紋，注重細節描繪，神情威武。天王的帽頂、帽子、飄帶分別鑄造後，扣合，眼睛用材不詳，呈乳白色，造型特殊，不確定本尊像的圖像內涵。', N'全高 11.2 公分、徑 6.2 公分', N'/media/catalog/bronze/贈銅000435N000000000/display.jpg', N'/media/catalog/bronze/贈銅000435N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47065?dep=U', N'CC-BY-4.0', N'日本 江戶時代 十七－十九世紀 銅鎏金雙身天王立像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('adf13e2c-efd7-56fe-3ded-c5658f141668', N'購錢001207N000000000', N'至和通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「至和通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001207N000000000/display.jpg', N'/media/catalog/coin/購錢001207N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10545?dep=U', N'CC-BY-4.0', N'至和通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('84c8ef4d-2a21-38a2-c9f5-c568d15a6cf7', N'贈銅000439N000000000', N'日本 江戶時代 十七世紀或更晚 銅鎏金菩薩立像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代 十七世紀或更晚', NULL, N'半浮雕，背面平直，菩薩立於仰覆蓮台座上，右手支頤，左手上舉胸前，臉形圓胖，不見頸，顯得可愛。肩披帛，沿著身側，長長地垂落至腳側，身形脩長。下身著裙，在腰上反摺一三角形，上身又斜掛一巾，衣褶線與巾帛均以陰刻的手法表現，用刀拙重， 表現拙趣。沒有瓔珞等表現，圖像內容不清楚，可能為個人用，易於隨身攜帶的小尊像。', N'像高 10.4 公分、寬 2.4 公分、厚 1.5 公分、木座長 5.0 公分、寬 3.6 公分、高 1.5 公分', N'/media/catalog/bronze/贈銅000439N000000000/display.jpg', N'/media/catalog/bronze/贈銅000439N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47069?dep=U', N'CC-BY-4.0', N'日本 江戶時代 十七世紀或更晚 銅鎏金菩薩立像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('477c2635-e9bd-c718-e4e0-c57d1c78275b', N'中銅000002N000000000', N'雙魚洗', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'洗，侈口、圓深腹、平底。腹飾弦紋及一對小獸首，內底飾雙魚。', N'高 14.8 公分', N'/media/catalog/bronze/中銅000002N000000000/display.jpg', N'/media/catalog/bronze/中銅000002N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6246?dep=U', N'CC-BY-4.0', N'雙魚洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f1935b68-a76a-cb59-1343-c5c13dd44fff', N'中銅000085N000000000', N'父癸鼎', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'直口，束頸，立耳，深壁略碩，弧底，獸面紋長板狀足。束頸飾減地斜向勾雲紋，這一種勾雲紋，應是由夔龍變化而來。腹外壁飾獸面紋。內壁有銘：「父癸」。', N'高 22.5 公分、徑 20.8 公分', N'/media/catalog/bronze/中銅000085N000000000/display.jpg', N'/media/catalog/bronze/中銅000085N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53472?dep=U', N'CC-BY-4.0', N'父癸鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9d16bb42-30d9-124c-75e1-c70a913a40d6', N'故畫00070500000', N'清王翬平林散牧圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙四十一年（1702）', NULL, N'王翬（西元一六三二－一七一七），常熟人。字石谷，號耕煙散人。清暉主人。烏目山人，劍門樵客。山水得王時敏指授，為清四大家之一。' + NCHAR(13) + NCHAR(10) + NCHAR(9) + N'康熙壬午七十一歲畫，疏林之下，茅屋數間，一人讀書坐堂上，兩牛傍籬，一立一臥。隔水平坡曼衍，丘陵起伏，平坡上有大小牛四頭，或漫步，或嚙草，覺牛背斜陽。層層暮景，意趣絕佳，為仿唐寅之作。', N'118 × 56.5 公分', N'/media/catalog/painting/故畫00070500000/display.jpg', N'/media/catalog/painting/故畫00070500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3483?dep=P', N'CC-BY-4.0', N'清王翬平林散牧圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6c9e7a37-1585-6335-6d06-c79e56614d4e', N'中銅001061N000000000', N'嵌銀雙管瓶', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'瓶，雙圓管形，侈口，折肩，圈足，器正面飾立雕鳳形，口銜環，下踩辟邪。管面飾獸面紋、蕉葉紋，均為陰刻，獸眼嵌金。', N'高 24.6 公分', N'/media/catalog/bronze/中銅001061N000000000/display.jpg', N'/media/catalog/bronze/中銅001061N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6709?dep=U', N'CC-BY-4.0', N'嵌銀雙管瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fa3d1b13-2b40-0e99-aec0-c8ac97989ab5', N'中銅000067N000000000', N'父已□偁爵', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'長流，尖尾，菌狀立柱，深腹卵底，獸首鋬，三足斷面作三角形，足背較寬。器身飾獸面紋。銘文4字，柱上、口下各1字，鋬內2字。', N'寬 7.2 公分、高 21 公分', N'/media/catalog/bronze/中銅000067N000000000/display.jpg', N'/media/catalog/bronze/中銅000067N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53464?dep=U', N'CC-BY-4.0', N'父已□偁爵 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1f249f55-4dd0-86ec-24b5-c8b5782fec49', N'贈瓷000461N000000000', N'布紋硬陶罐', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'罐，斂口，豐肩，肩部兩側各有一對小貫耳，圓腹，平底。本罐屬印紋硬陶，硬陶是一種介於陶器與瓷器之間的品種，以硬度高、黏性強胎土，經過較高（約攝氏1100度）的溫度燒成；器表紋飾是於胎體製成後，再以模具拍印上去，母題多為幾何、繩紋、布紋、方格紋等紋樣，本件為布紋，為戰國時代常用的紋飾之一。', N'高 9.0 公分', N'/media/catalog/ceramic/贈瓷000461N000000000/display.jpg', N'/media/catalog/ceramic/贈瓷000461N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43491?dep=U', N'CC-BY-4.0', N'布紋硬陶罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6ae2806a-93fb-c2f1-5333-c8b7c8a83d86', N'中瓷000388N000000000', N'黃釉蓋罐', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'圓口有唇，短頸，豐肩下斂，近足處外撇，平底內凹成足，底面寬平。帶寶珠鈕蓋。全器光素無紋，器內白釉，器外壁施黃色釉，釉色亮黃。器底露胎，無款。', N'高 52.5 公分、口徑 21.0 公分、底徑 21.0 公分', N'/media/catalog/ceramic/中瓷000388N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000388N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/20418?dep=U', N'CC-BY-4.0', N'黃釉蓋罐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('56e58bc4-77f9-1cae-f39c-c8be10888847', N'贈錢001262N000000000', N'咸豐通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「咸豐通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001262N000000000/display.jpg', N'/media/catalog/coin/贈錢001262N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9085?dep=U', N'CC-BY-4.0', N'咸豐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a8b7e7fa-9fd0-6a0f-219a-c8c0054490c2', N'故雕000009N000000000', N'木根筆筒', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'筆筒用木根隨形雕刻而成，鑲深棕色木口，底平。器表樹瘤密佈，全器棕紅，口緣貼黃籤「甲字第九百四十號」。', N'通高約 17.3 公分、口徑長 18.2 公分、寬 14.5 公分', N'/media/catalog/carving/故雕000009N000000000/display.jpg', N'/media/catalog/carving/故雕000009N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62312?dep=U', N'CC-BY-4.0', N'木根筆筒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('726df344-823f-6ecd-299c-c9cd1a983aed', N'中琺000151N000000000', N'掐絲琺瑯花卉梅瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎梅瓶。器身滿施淺藍色釉並掐絲雲錦紋為地， 有蓮塘與菊園景致。花朵主要以紅色料敷染， 葉片則填草綠與深藍色釉， 其上蝴蝶、蜻蜓飛舞，白鶴翱翔， 外撇底部， 飾有湖石。底鑄陽文「景泰年製」方框偽款，實應屬十六世紀後期製作。', N'高 27.4 公分、肩寬 15.6 公分', N'/media/catalog/enamel/中琺000151N000000000/display.jpg', N'/media/catalog/enamel/中琺000151N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1529?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花卉梅瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1);
INSERT INTO [catalog].[Artifacts] ([Id], [ArtifactRef], [Name], [CategoryId], [EraBucketId], [EraTextOriginal], [CreatorDisplay], [Description], [SizeText], [PrimaryImagePath], [ThumbnailPath], [SourceUrl], [LicenseCode], [AttributionText], [IsActive]) VALUES
    ('45c9ba9f-66c8-6349-757a-c9f46b95198d', N'中漆000012N000000000', N'剔紅龍紋小櫃', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅長方形小櫃，色暗紅，似木胎，略有傷損。立式小櫃，分三層，上與中層為對開式門，中層較大層櫃上方設有空格，內有暗屜，下層作抽屜，底有四如意形足，嵌銅軸片與飾件。櫃面、頂面與兩側有多個開光，皆雕龍戲珠紋，飾以波濤，外襯繡球朵花錦地，屜面雕波紋上四飛魚，邊界均飾回紋，背面淺刻寶相花紋。器裡與底髹黑色光漆。', N'長 37.1 公分、寬 16.7 公分、高 55.4 公分', N'/media/catalog/lacquer/中漆000012N000000000/display.jpg', N'/media/catalog/lacquer/中漆000012N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17547?dep=U', N'CC-BY-4.0', N'剔紅龍紋小櫃 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f6567cde-037b-b2b0-211c-ca83996aa239', N'購錢000214N000000000', N'皇宋通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「皇宋通寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000214N000000000/display.jpg', N'/media/catalog/coin/購錢000214N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9552?dep=U', N'CC-BY-4.0', N'皇宋通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f194e0d8-d44f-6cfb-6c7c-ca9467f74167', N'中銅000197N000000000', N'瑞花鸞鳳紋葵花鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'八瓣菱花形鏡，圓鈕。鏡背飾鸞鳳與花卉紋。', N'直徑 17.1 公分', N'/media/catalog/bronze/中銅000197N000000000/display.jpg', N'/media/catalog/bronze/中銅000197N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7060?dep=U', N'CC-BY-4.0', N'瑞花鸞鳳紋葵花鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5a3fc671-795e-81b5-a4d7-caeb837adeee', N'中玉000440N000000000', N'玉長方形器飾', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'玉質，深棕黑色有光澤。長方形器，側視為弧形片狀，凸面二端各陰刻直線二束，中琢交疊圓璧形二，凹面光素無紋，二端各有一象鼻穿。本件疑為用新石器時代晚期玉圈(鐲)的殘件，兩端加鑿小隧孔，凸面加琢仿古紋飾，全器深染褐紅色。雕紋與染色的工序可能是十八世紀時所作。現收藏於飾錦袱紋扇形金色蒔繪漆盒，其中並有檀香木座。', N'長 4.05 公分、寬 10.24 公分', N'/media/catalog/jade/中玉000440N000000000/display.jpg', N'/media/catalog/jade/中玉000440N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53199?dep=U', N'CC-BY-4.0', N'玉長方形器飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4c93e354-9677-f3d5-6655-cd192d6f7fe2', N'故畫00045200000', N'明郭詡東山攜妓圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明世宗嘉靖五年（1526）', NULL, N'郭詡（西元一四五六－一五二六年），江西泰和人。字仁宏，號清狂。善山水，作畫不依畫譜，取法自然。與同時之吳偉、杜堇、沈周以畫論交，天下競傳清狂之畫名。弘治中，徵天下善畫者，應召至京師。後以寧王之亂，辭謝寧王宸濠之召納，往依王守仁。　　清狂於山水外，又喜雜畫，信手作人物，輒有奇趣。此幅畫謝安攜妓遊東山。謝安（三二０－三八五年）為東晉孝武帝時人，曾敗前秦符堅兵於淝水，因是知名。', N'123.8 × 49.9 公分', N'/media/catalog/painting/故畫00045200000/display.jpg', N'/media/catalog/painting/故畫00045200000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3251?dep=P', N'CC-BY-4.0', N'明郭詡東山攜妓圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0a73d11d-ac40-b11c-4703-cd352de1f839', N'故玉003932N000000000', N'花結單柄圓洗', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'玉質，色白潤，有瑕紋。全器作短橢圓形洗，侈口，碩腹，弧形壁，平底。腹側雕花結單柄。附木雕鏤空夔鳳紋座。', N'徑 9.1 公分', N'/media/catalog/jade/故玉003932N000000000/display.jpg', N'/media/catalog/jade/故玉003932N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/51943?dep=U', N'CC-BY-4.0', N'花結單柄圓洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b5b0c857-3d3c-ee4e-9f4c-cd7e9b8fbbe9', N'中玉000003N000000000', N'玉圓盒', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'灰黃⾊⽟，圓扁盒，有綹及赭斑。素面無紋。', N'高 2.0 公分、口徑 5.1 公分', N'/media/catalog/jade/中玉000003N000000000/display.jpg', N'/media/catalog/jade/中玉000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52740?dep=U', N'CC-BY-4.0', N'玉圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ecc59687-bc07-4e13-258f-ce35e7fcbcc2', N'故玉000723N000000000', N'玉犬', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'f2a78063-931b-9926-749c-324377d136c7', N'金至元', NULL, N'青玉，質地光潔潤澤，惜有一細璺。前肢交疊，背脊拱起，骨節、肌理清晰可見，充份表現獵犬精瘦結實的體態，後肢長於前肢且略略抬起，給人一種蓄勢待發的力度感。眼睛作圓形淺窪狀，和巴林右旗白音漢窖藏出的遼代玉獸一樣，是較為特殊的處理方式。', N'長 5.72 公分、寬 1.5 公分、高 2.56 公分', N'/media/catalog/jade/故玉000723N000000000/display.jpg', N'/media/catalog/jade/故玉000723N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/89?dep=U', N'CC-BY-4.0', N'玉犬 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6c63f22f-1e4f-f66a-9f1f-ce7aa52a6fd9', N'中日陶000043N000000000', N'灰陶灶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'灶體呈梯形，轉角處略呈圓弧狀。灶體前端設一遮檐，檐下有一方形灶門。灶上設有五個火眼（釜孔），中央的火眼略大。無底。灶尾處設有煙囪，煙囪前端略為外侈，中央略上處有一凸稜。全器僅於灶門周圍飾有菱格紋。此灰陶灶為遼陽第二號磚墓出土。', N'長 29.0 公分、寬 27.5 公分、高 11.7 公分', N'/media/catalog/ceramic/中日陶000043N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000043N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71765?dep=U', N'CC-BY-4.0', N'灰陶灶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e52983bc-e5d1-381a-6c7c-ceacdc233d2a', N'故畫00039300000', N'明夏昶清風高節圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明代宗景泰一年(1450)', NULL, N'夏昶（西元一三八八－一四七０年），江蘇崑山人。字仲昭，號自在居士，又號玉峰。擅長畫墨竹，學自陳繼（西元一三七０－一四三四年）、王紱（西元一三六二－一四一六年）。' + NCHAR(13) + NCHAR(10) + NCHAR(13) + NCHAR(10) + N'傍石而生的脩竹，隨風搖曳，頗有動感。竹幹畫的挺拔，竹葉則勁健，墨色有著明顯的前後濃淡之別。另畫石的筆墨極重，顯出石的厚實，和竹的飄逸兩相對映，意趣無窮。', N'137.3 × 43.3 公分', N'/media/catalog/painting/故畫00039300000/display.jpg', N'/media/catalog/painting/故畫00039300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3192?dep=P', N'CC-BY-4.0', N'明夏昶清風高節圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('59b7f0b4-3552-0a7b-dbee-ceb13c97a9cf', N'故瓷003699N000000000', N'日本 有田窯 青花五彩描金團花紋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'碗，侈口出唇，弧壁，矮圈足。口沿唇邊畫描金彩線紋一周，器內壁近口沿處畫青花卷草斜線紋一道，內底以青花書「永樂年製」行楷款，外繞一周青花卷草斜線紋。器外壁以藍釉為地，利用留白的白色線邊劃分八等分格，中有一圈白邊的開光圖案分別繪飾變形的西洋紋飾及線方格紋，圓形開光圖案外分別以金彩、紅彩裝飾花草及方線格紋；外壁近圈足處，以青花畫簡化而變形的靈芝紋，輔以紅彩線點飾，圈足外牆分別以青花、紅彩畫飾卷雲紋，外底心畫兩圈青花線紋。青花鮮麗多暈散，留白的白釉地微泛青色，胎骨勻輕，圈足露胎處，質堅細膩。本器應為明代晚期書寫永樂年款的日本伊萬里風格製品。', N'高 6.8 公分、口徑 16.9 公分、底徑 8.6 公分', N'/media/catalog/ceramic/故瓷003699N000000000/display.jpg', N'/media/catalog/ceramic/故瓷003699N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/28654?dep=U', N'CC-BY-4.0', N'日本 有田窯 青花五彩描金團花紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3d8fbfbc-8672-452a-ee23-cec55ae8e330', N'故畫00068300000', N'清王時敏倣王維江山雪霽　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙七年（1668）', NULL, N'王時敏（西元一五九二至一六八０），江蘇太倉人。字遜之，號煙客，又號西廬老人、西田主人、偶諧道人、歸村老農。性資穎異，淹雅博物，為清四王之首。 跋中自云：曾見王維江山雪霽圖，及江干雪意長卷。其後屏跡村居，追憶其意以為此圖。作時七十七歲。通幅構景用筆皆甚穩厚，山坳樹隙，色用重綠，於雪景中其法甚古。', N'133.7 × 60 公分', N'/media/catalog/painting/故畫00068300000/display.jpg', N'/media/catalog/painting/故畫00068300000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3461?dep=P', N'CC-BY-4.0', N'清王時敏倣王維江山雪霽　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e193c733-495e-b3b0-2185-ced2b46c8435', N'購錢001086N000000000', N'元豐通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「元豐通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001086N000000000/display.jpg', N'/media/catalog/coin/購錢001086N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10424?dep=U', N'CC-BY-4.0', N'元豐通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('41ae4f86-1bde-059d-7704-ced3e05b2f8b', N'中琺000004N000000000', N'掐絲琺瑯燭台（五供）', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅胎。由釘形燭阡，支柱，托盤及台座組成。器身以掐絲技法、琺瑯料填色製作花紋，以淺藍色為地，上托盤外飾海棠花紋，支柱為番蓮紋，下托盤底飾六瓣花紋，內壁飾番蓮紋，外壁飾雙夔龍拱壽紋，台座上緣飾如意雲紋邊飾及番蓮紋。鍍金托盤沿及足沿刻飾回紋。與中琺5成對，燭臺為五供之一，本器與中琺3-7成套。', N'燭台高 29.0 公分', N'/media/catalog/enamel/中琺000004N000000000/display.jpg', N'/media/catalog/enamel/中琺000004N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53881?dep=U', N'CC-BY-4.0', N'掐絲琺瑯燭台（五供） 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('574d3e39-6fef-e242-86fe-cf31e9952c45', N'贈雕000179N000000000', N'象牙雕馬首鈕箸', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'磨取一根象牙，一端雕一正面馬首，背面中央刻一長凹槽，斜線陰刻馬鬢，馬首立於工字臺上；其下方中段稍凸，陰刻斜線以示馬身，馬身又立於二層工字臺上，此段局部傷損，箸挺四個部位陰刻斜線為飾，全器已染成淡綠色。', N'長 20.7 公分、徑 0.6 公分', N'/media/catalog/carving/贈雕000179N000000000/display.jpg', N'/media/catalog/carving/贈雕000179N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45407?dep=U', N'CC-BY-4.0', N'象牙雕馬首鈕箸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('24dc2f37-3b29-b7bf-fe15-cfd56589daaa', N'故銅001466N000000000', N'「輔嬰隋」銅印', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '561e3931-1096-c637-9eb3-b5c5ce02c88f', N'秦', NULL, N'壇鈕，長方形印，印面白文「輔嬰隋」三字，有格欄，「輔」為姓。', N'高 1.16 公分、印面長 1.94 公分、寬 1.11 公分', N'/media/catalog/bronze/故銅001466N000000000/display.jpg', N'/media/catalog/bronze/故銅001466N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/4861?dep=U', N'CC-BY-4.0', N'「輔嬰隋」銅印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6b720454-624e-cb10-d6e7-d1f97acf8563', N'中漆000029N000000000', N'剔紅職貢圖小櫃', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'長方立式小櫃，有門二扇，櫃內以暗屜分成二層，空間相等。屜與門皆有金屬飾件以供開闔。門上方形開光中剔紅山水人物為飾，山水交錯、小徑自遠方蜿蜒而下，創造出畫面的深度感。就中人物有行走亦有有坐騎者，皆面帶喜色且捧物遠離畫面右上方之城郭。附几式漆座，座有屜。', N'長 48.4 公分、寬 19.7 公分、通高 57.7 公分', N'/media/catalog/lacquer/中漆000029N000000000/display.jpg', N'/media/catalog/lacquer/中漆000029N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17550?dep=U', N'CC-BY-4.0', N'剔紅職貢圖小櫃 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ce21bc41-d26f-161b-00b5-d26b4f800987', N'中琺000052N000000000', N'掐絲琺瑯梵文盤', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'底刻「乾隆年製」方框楷款。清宮作品，乾隆時期。折口圓盤，通體飾藍地掐絲琺瑯，金屬絲精細，琺瑯料濃厚鮮麗。盤心為十相自在符號，盤緣飾梵文一周，內外盤壁為雲紋間八吉祥、七政寶等圖樣。「十相自在」係由七個梵字及三個圖案共同組成的圖案化文字，包含世間各樣的吉祥與祝福，也是西藏各地常見的祈願符號。', N'高 2.9 公分、口徑 15.3 公分、足徑 7.8 公分', N'/media/catalog/enamel/中琺000052N000000000/display.jpg', N'/media/catalog/enamel/中琺000052N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3020?dep=U', N'CC-BY-4.0', N'掐絲琺瑯梵文盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f2c0375e-2431-79af-1b02-d2a72b47bbaf', N'中銅000010N000000000', N'獸帶紋鼎', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'器身為半球形，二耳，三獸足。器身飾獸帶紋及弦紋。附蓋，蓋上有三環鈕，飾獸帶紋。', N'高 21.0 公分', N'/media/catalog/bronze/中銅000010N000000000/display.jpg', N'/media/catalog/bronze/中銅000010N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5709?dep=U', N'CC-BY-4.0', N'獸帶紋鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e7423237-377a-3f48-bb75-d39d080f45c9', N'中琺000713N000000000', N'掐絲琺瑯雙鳳紋洗', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，折沿，壁外鼓，平底，外撇圈足附雲紋式足三，雙螭爬附在陰刻卷草紋的鍍金口沿。洗內側壁作白地佈草莓紋錦，間飾天馬寶相花各四。洗底周圍飾雲紋及轉枝花各一圈，當中綠地草莓錦中飾雙鳳及花朵。器外壁藍紫地草莓錦，間飾紅、白梅花，圈足飾轉枝花。洗外底露胎，中央鑄去地陽文「大明宣德年製」長方框三行楷書偽款。根據錦地、紋飾及釉色等特點，應屬明代末期之文物。', N'高 8.7 公分、口徑 31.5 公分', N'/media/catalog/enamel/中琺000713N000000000/display.jpg', N'/media/catalog/enamel/中琺000713N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1536?dep=U', N'CC-BY-4.0', N'掐絲琺瑯雙鳳紋洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('86546d09-cf02-9f4b-5675-d40cebccf950', N'故畫00025400000', N'元唐棣霜浦歸漁圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', 'f2a78063-931b-9926-749c-324377d136c7', N'元順帝至元四年（1338）', NULL, N'唐棣（約西元1284-1354年），浙江吳興人。字子華，晚號遁齋。畫山水初學趙孟頫，後兼法韋偃、李成、郭熙，其中對郭熙用功最深。本幅繪漁翁三人，肩負網罟漁具，且行且語，滿載而歸。畫近景喬木所用之蟹爪枝與畫坡石之雲頭皴，均傳承自郭熙，而整體布局之平遠法，則源於李成。幅左款署至元戊寅（1338），時正值唐氏盛年，故筆筆勁挺，誠為其平生傑作。', N'144 × 89.7 公分', N'/media/catalog/painting/故畫00025400000/display.jpg', N'/media/catalog/painting/故畫00025400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/518?dep=P', N'CC-BY-4.0', N'元唐棣霜浦歸漁圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4b7a4b8b-aad8-8f51-76da-d472da3aff03', N'中銅000183N000000000', N'舞鳳狻猊鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'圓鏡，半球鈕，花瓣形鈕座。內區飾異獸，外區飾鳳紋與花卉。', N'直徑 24.8 公分', N'/media/catalog/bronze/中銅000183N000000000/display.jpg', N'/media/catalog/bronze/中銅000183N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7057?dep=U', N'CC-BY-4.0', N'舞鳳狻猊鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7fe5d5cf-7e48-3644-4a26-d47a31bf4308', N'中銅000291N000000000', N'「大德元年」鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'f2a78063-931b-9926-749c-324377d136c7', N'元', NULL, N'圓鏡。鏡背飾海上觀音像，有銘四字。', N'直徑 7.2 公分', N'/media/catalog/bronze/中銅000291N000000000/display.jpg', N'/media/catalog/bronze/中銅000291N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7100?dep=U', N'CC-BY-4.0', N'「大德元年」鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e22b2a6c-a481-b977-1f8b-d4e4aa511ea2', N'中銅000187N000000000', N'雙魚紋鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'圓鏡，橋鈕。鏡背飾魚紋。', N'直徑 17.1 公分', N'/media/catalog/bronze/中銅000187N000000000/display.jpg', N'/media/catalog/bronze/中銅000187N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/7052?dep=U', N'CC-BY-4.0', N'雙魚紋鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('e4bfef20-5310-5419-1066-d50ff9aaaea1', N'中瓷000387N000000000', N'龍泉窯 青瓷梅瓶', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'小口，短頸，豐肩，碩腹下歛，平底，淺圈足。通體施青釉，釉色青淺透亮，通體光素無紋飾。圈足露胎，塗赭色汁。', N'高 38.7 公分、口徑 6.5 公分、底徑 15.3 公分、最大徑 22.0 公分', N'/media/catalog/ceramic/中瓷000387N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000387N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/20417?dep=U', N'CC-BY-4.0', N'龍泉窯 青瓷梅瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c32cc14d-3da8-2689-dff3-d568752a1798', N'中玉000639N000000000', N'雲紋玉飾', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'玉質，白色夾雜赭斑。長方形片狀，兩端磨圓而有穿孔。背面平而光素，正面微鼓，淺浮雕三組雲紋。功能不詳，應為作嵌飾用。', N'長 8.0 公分、寬 1.2 公分、高 0.5 公分', N'/media/catalog/jade/中玉000639N000000000/display.jpg', N'/media/catalog/jade/中玉000639N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53407?dep=U', N'CC-BY-4.0', N'雲紋玉飾 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('08188c59-1e9b-6d69-bfa7-d597578fc017', N'購錢000470N000000000', N'淳化元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有草書：「淳化元寶」四字，背面無文。錢文傳為宋太宗手書。', N'待測量', N'/media/catalog/coin/購錢000470N000000000/display.jpg', N'/media/catalog/coin/購錢000470N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9808?dep=U', N'CC-BY-4.0', N'淳化元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('cbf5d3c1-efb3-c22d-c7e9-d5b0ceaa5a88', N'贈雕000037N000000000', N'骨飾件', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'周', NULL, N'器用大小兩塊骨製成，小塊者製成扁圓形，側壁斜削，正中鑽一小孔，可與另一塊榫接；小塊圓骨之正中小孔尚可嵌插在他器上，可能是某類器之嵌飾件。', N'長 4.7 公分', N'/media/catalog/carving/贈雕000037N000000000/display.jpg', N'/media/catalog/carving/贈雕000037N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45263?dep=U', N'CC-BY-4.0', N'骨飾件 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1bc6866b-ead8-056a-29f3-d8d4c7e354ed', N'贈雕000053N000000000', N'骨龍紋帶鉤', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'帶鉤首做獸首形，細小圈點紋為雙眼，口部亦有一細小圈點紋，突起雙耳上細線陰刻斜弦紋，並陰刻輪廓線；器身細線陰刻弦紋與圈點紋為飾。中央突起，上下各有一深凹槽，原或嵌飾綠松石等嵌件，今已脫落不存。', N'長 13.3 公分、寬 1.8 公分', N'/media/catalog/carving/贈雕000053N000000000/display.jpg', N'/media/catalog/carving/贈雕000053N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45279?dep=U', N'CC-BY-4.0', N'骨龍紋帶鉤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5e7a348e-1707-d622-75b2-d907d6484df2', N'中琺000014N000000000', N'掐絲琺瑯碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'金屬胎之碗，口微撇，深壁，圈足。全器淺藍地，以掐絲技法於器表飾番蓮紋與葵花紋，足飾環帶紋(圈帶)。座為木胎漆器，筒式杯下接圓形碟與雙階式五腳足，外壁以醬色漆為地，內髹黑漆。外壁彩漆繪蓮瓣紋，碟面繪雙行龍與雲紋，足繪幾何紋。', N'高 6.1 公分、深 5.2 公分、口徑 12.5 公分、足徑 7.8 公分；座通高 6.5 公分、口徑 7.3 公分、碟徑約 17.0 公分、足徑 11.0 公分', N'/media/catalog/enamel/中琺000014N000000000/display.jpg', N'/media/catalog/enamel/中琺000014N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53891?dep=U', N'CC-BY-4.0', N'掐絲琺瑯碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('09165847-1105-837a-6f70-d9f836a54451', N'故琺000747N000000000', N'掐絲琺瑯牛頭瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，掐絲琺瑯。撇口，收頸，豐肩，肩上嵌三牛首，碩腹下斂，撇足，露銅胎處皆鎏金。器身施淺藍釉為地，頸與腹俱作四瓣朵花地上飾蟬形紋飾，頸部為蟬紋，腹部作獸面紋，肩冏紋與獸面紋相間，足蓮瓣紋一圈。器底有剔地陽文「景泰年製」楷款，加方框。', N'高 22.2 公分', N'/media/catalog/enamel/故琺000747N000000000/display.jpg', N'/media/catalog/enamel/故琺000747N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61778?dep=U', N'CC-BY-4.0', N'掐絲琺瑯牛頭瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('36e12767-0e28-dc20-946a-da15ad1505b1', N'中琺000076N000000000', N'掐絲琺瑯番蓮紋香插', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'敞口，淺壁，平底，中央有一蓮瓣座寶瓶形香插。通體紋飾以掐絲琺瑯技法完成，淺藍地，內外壁飾五彩番蓮紋，內底有四如意雲形開光，內飾黃地藍夔龍，開光隙地及香插部分飾卷枝花卉紋，外底飾四枚紅色番蓮紋。底部有圓形露胎，內陰刻「乾隆年製」四字雙行楷款。', N'高 3.4 公分', N'/media/catalog/enamel/中琺000076N000000000/display.jpg', N'/media/catalog/enamel/中琺000076N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53952?dep=U', N'CC-BY-4.0', N'掐絲琺瑯番蓮紋香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a6c2593c-901f-83fe-bf0f-db07268ead1b', N'中銅000014N000000000', N'蟠虺紋鼎', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋', NULL, N'隆蓋，蓋上有三環耳，子母口，立耳，圓腹，蹄足。蓋緣與口沿下飾蟠螭紋帶。', N'高 24.0 公分', N'/media/catalog/bronze/中銅000014N000000000/display.jpg', N'/media/catalog/bronze/中銅000014N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6929?dep=U', N'CC-BY-4.0', N'蟠虺紋鼎 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a230e055-d668-abe6-f3d3-db577d812211', N'故漆000338N000000000', N'剔紅山水人物方盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'長方形套盒，盒身內外髹黑漆，盒底側面為回紋，盒內清宮以木盒盛裝小玉器十件及書畫小冊頁。盒蓋側面四面為花鳥圖，盒蓋為山水人物。長邊的花鳥圖二面略為不同，以梅幹為主，自偏左位置伸出枝幹，再轉向右橫向伸展，茶花安排在畫面偏下方，中央兩隻長尾鳥回首相對，空間中散佈著全開的梅花。短邊的花鳥圖，枝幹在畫面中央一鳥，低首或昂首。整體構圖平均，鳥的眼神兇猛，花、葉及鳥的身形描寫僵硬，花鳥圖的底層滿鋪錦地。盒蓋上方為山水人物，前景偏下方一地平線斜向分割畫面，三人展卷觀看，左後方崖壁聳立，高松橫臥，右後方遠處則山石層疊，壓縮遠處空間，物象底滿飾錦地。漆色紅，刀法銳利，打磨不多，岩石紋理遺留刀痕。', N'長 13.0 公分、寬 10.0 公分、高 12.4 公分', N'/media/catalog/lacquer/故漆000338N000000000/display.jpg', N'/media/catalog/lacquer/故漆000338N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48310?dep=U', N'CC-BY-4.0', N'剔紅山水人物方盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7a97719b-cccc-ffe3-d9ad-dc3596dc7670', N'中琺000027N000000000', N'掐絲琺瑯香插', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'瓶呈葫蘆形，碟為侈口、淺壁、圈足。全器藍地，以掐絲技法於碟飾番蓮紋與六瓣花紋，瓶口飾如意雲紋，身飾纏枝花卉紋。圈足內飾六瓣花紋。', N'高 6.7 公分、口徑 15.5 公分、足徑 10.0 公分', N'/media/catalog/enamel/中琺000027N000000000/display.jpg', N'/media/catalog/enamel/中琺000027N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53904?dep=U', N'CC-BY-4.0', N'掐絲琺瑯香插 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7d008bba-d61e-eddf-eec7-dc5e7a4a190e', N'中銅000120N000000000', N'召仲簠', '35ce74f7-c31a-3a07-0cbd-91f42656d869', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'本器蓋器造型基本相同，長方形，腹斜收，圈足每邊有缺，兩側置獸耳一對，蓋沿與器合口處，每邊正中央有一牛首，可以固定器蓋不致滑落。全器裝飾吐舌蟠虺紋。器蓋對銘，銘文作：「唯六月初丁亥，冶仲考父自作壺，用祀用饗多福祿，用旂眉壽萬年無疆，子子孫永寶是尚。 」器銘泐蝕且輭弱無力，內容摹自宋代《宣和博古圖》的「周仲丁壺」。本件器物是乾隆三十四年(1769)頒賜國子監的「周笵十器」之一，名之為「周召仲簠」。', N'高 23.8 公分', N'/media/catalog/bronze/中銅000120N000000000/display.jpg', N'/media/catalog/bronze/中銅000120N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6701?dep=U', N'CC-BY-4.0', N'召仲簠 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('53eba35e-d021-5284-a23e-dcb54ee661f3', N'贈錢001480N000000000', N'「貨泉」錢幣', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'銅製，圓形中央有方孔，一面鑄有「貨泉」，一面圖文無法辨識。', N'徑 1.7 公分', N'/media/catalog/coin/贈錢001480N000000000/display.jpg', N'/media/catalog/coin/贈錢001480N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9322?dep=U', N'CC-BY-4.0', N'「貨泉」錢幣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f6b83e85-6caf-fa53-b587-dcdd4daae39c', N'中琺000001N000000000', N'掐絲琺瑯鼎式爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅胎。直口，短頸，圓腹，鍍金雙夔龍形耳，圓底，三足，帶鍍金蓮苞鈕穹頂形子母口蓋。以掐絲技法、琺瑯料填色製作花紋，以淺藍色為地，蓋身為五彩朵雲紋錦地雜寶裝飾，有古錢、卍字、犀角、如意、畫軸、方勝、珊瑚，腹部飾朵雲紋錦地法輪、寶傘、雙魚、蓮花、法螺、盤長紋。足部上方為鍍金張口獸首，足身飾番蓮紋。', N'高約 62.0 公分', N'/media/catalog/enamel/中琺000001N000000000/display.jpg', N'/media/catalog/enamel/中琺000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53878?dep=U', N'CC-BY-4.0', N'掐絲琺瑯鼎式爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('279b5ee8-6c9c-c664-537a-dcdf1bc2221b', N'故玉000010N000000000', N'玉司南形佩', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'東漢', NULL, N'白質，器作「工」字形，中有橫穿，作為佩飾器。', N'長 2.2 公分、寬 2.3 公分、厚 0.9 公分', N'/media/catalog/jade/故玉000010N000000000/display.jpg', N'/media/catalog/jade/故玉000010N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48208?dep=U', N'CC-BY-4.0', N'玉司南形佩 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3723273c-9fe9-f10b-0e90-dd14ee6e9537', N'故琺000405N000000000', N'掐絲琺瑯尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎掐絲琺瑯，侈口，長頸，頸附雙螭耳，平肩，肩附三獸首啣環繫耳，斂腹，圈足帶三狻猊(獅)形足。器表淺藍地，頸部由上至下飾纏枝花卉紋、番蓮花及花葉紋，肩部為轉枝花卉紋、蓮瓣紋；腹部為轉枝番蓮紋，階梯式圈足飾有幾何紋。底部露胎，鑄有去地陽文「大明景泰年製」三行楷書款。', N'高 34.5 公分、深 29.0 公分、口徑 18.5 公分、底徑 14.5 公分', N'/media/catalog/enamel/故琺000405N000000000/display.jpg', N'/media/catalog/enamel/故琺000405N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61502?dep=U', N'CC-BY-4.0', N'掐絲琺瑯尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9ce89353-01b7-2265-8058-dd4495557e7f', N'中銅000276N000000000', N'「朝城官」鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'鏡身作八圓瓣形，鏡背正中有一橋形小鈕，以雙弧線及小圓點相間排列而成的鈕座外，滿飾淺浮雕的纏枝花卉，其外環飾一圈連珠紋及小花瓣，寬平的鏡邊上陰刻著「朝城官押」，鈕旁的花葉中則鑄有一個陽文的「韓」字。', N'邊厚 0.2 公分、徑 11.9 公分', N'/media/catalog/bronze/中銅000276N000000000/display.jpg', N'/media/catalog/bronze/中銅000276N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/15?dep=U', N'CC-BY-4.0', N'「朝城官」鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5e79cd4c-5a4f-1a60-2889-ddc315f68d3f', N'故畫00068900000', N'清王鑑溪山深秀　軸', 'ec78c074-e905-9285-7894-321d57e98275', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清聖祖康熙十五年（1676）', NULL, N'王鑑（西元一五九八－一六七七年），江蘇太蒼人。字圓照，號湘碧，自稱染香庵主。王世貞之孫。仕至廉州知府。精通畫理，山水為清初四王之一。 以青綠設色畫疊嶂迴溪，林嵐一股蒼秀之氣。自題倣范華原，而出以工細之筆，仍能纖細中不失高雅韻味。青綠重色，妍中猶具書卷氣，堪為學畫者津梁。', N'161.7 × 62.5 公分', N'/media/catalog/painting/故畫00068900000/display.jpg', N'/media/catalog/painting/故畫00068900000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3467?dep=P', N'CC-BY-4.0', N'清王鑑溪山深秀　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ece49c1c-d149-c28c-ba74-df023b2bbe60', N'中琺000170N000000000', N'掐絲琺瑯龍鳳鈁', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，器形係仿青銅器方壼，或簡稱為鈁的形制。方口垂腹外撇的方形足，器側鑲一對鋪首環耳。器表藍地，頸飾蕉葉紋，肩裝飾拐子龍紋，腹部於雲紋錦地間二面裝飾正面龍紋，二面為鳳紋，並皆襯以壽山福海紋，外侈的足上飾壽山福海、天馬、祥雲等紋飾。', N'高 37.5 公分、腹寬 22.0 公分', N'/media/catalog/enamel/中琺000170N000000000/display.jpg', N'/media/catalog/enamel/中琺000170N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/263?dep=U', N'CC-BY-4.0', N'掐絲琺瑯龍鳳鈁 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('732384e2-e6a4-8ac5-a904-df19968d7b31', N'故漆000143N000000000', N'剔紅秋葵圓盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'雕漆盤，黃漆素地，紅漆沉艷光潤，漆層傷裂。敞口，淺壁，矮圈足。通體雕秋葵花與葉，花瓣柔美細膩，莖葉俐落富層次，刀鑿厚實圓潤。器底髹黑色光漆，底面邊側有直刀刻填金楷書「大明宣德年製」，並有紫檀鏤雕雲龍紋座及木箱。', N'高 4.3 公分、口徑 32.4 公分、足徑 24.9 公分', N'/media/catalog/lacquer/故漆000143N000000000/display.jpg', N'/media/catalog/lacquer/故漆000143N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18203?dep=U', N'CC-BY-4.0', N'剔紅秋葵圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d668edd8-aafe-e5e7-0775-e0330639a6c4', N'故瓷003942N000000000', N'有田窯 青花五彩龍鳳紋八方盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代', NULL, N'八方形的造型，盤內以雙線青花區格為八個小單位，分別繪飾鳳、鳥、芭蕉太湖石和在櫸地紋上飾圖案化花卉等圖案，另盤心四瓣花形開光中繪蟠龍紋。盤外壁主要飾八顆形態相近的石榴，圈足內書青花「大明萬曆年製」六字二行雙圈行楷體款。圈足內有五支釘痕，或因日本胎質較軟容易塌陷，以此技法因應，亦成判斷日瓷的準則之一。', N'高 2.2 公分、口徑長 23.0 公分、寬 22.0 公分、足徑 13.5 公分', N'/media/catalog/ceramic/故瓷003942N000000000/display.jpg', N'/media/catalog/ceramic/故瓷003942N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36908?dep=U', N'CC-BY-4.0', N'有田窯 青花五彩龍鳳紋八方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('33c40c4c-6b47-3ead-760e-e04848d678a7', N'贈雕000033N000000000', N'骨雕魚形鑣', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周', NULL, N'弧形，剖面呈橢圓形，一端雕魚首形，另一端雕魚尾形：魚首端兩側陰刻同心圓為眼紋，唇部凹陷，尾端凹入，近尾端刻兩道弦紋，魚背刻重複連續方格紋為魚鱗，首部刻三角紋。此件從中段斷開，今已黏合。器呈弧形，然無孔供繫掛，應不是佩璜，依其型制與尺寸，或是馬具中的鑣具。就其紋飾風格，或非中原地區先民遺物。', N'長 16.2 公分、徑 1.0 公分、尾寬 1.5 公分', N'/media/catalog/carving/贈雕000033N000000000/display.jpg', N'/media/catalog/carving/贈雕000033N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45259?dep=U', N'CC-BY-4.0', N'骨雕魚形鑣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('805bf2e7-040e-0c12-d8e8-e0f4df75dfb7', N'南購畫00002000000', N'東海道十 五十三次 小田原', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪小田原宿（神奈川縣小田原市）風景，畫面由右而左標示「東海道十」、「五十三次 小田原」、「廣重画」，畫面左下副題「酒匂川」，畫面框外右下角一半且不清晰的「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002000000/display.jpg', N'/media/catalog/painting/南購畫00002000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36475?dep=P', N'CC-BY-4.0', N'東海道十 五十三次 小田原 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3a69bd66-4260-432b-2b59-e12ac5ff4374', N'購錢000723N000000000', N'祥符元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「祥符元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000723N000000000/display.jpg', N'/media/catalog/coin/購錢000723N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/10061?dep=U', N'CC-BY-4.0', N'祥符元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('de3d4546-1eb9-3e68-6f1e-e15d65599738', N'中瓷001326N000000000', N'定窯 白瓷魚藻紋碗', '9611dce4-97c7-26b6-0248-7cb003d17c3d', 'f2a78063-931b-9926-749c-324377d136c7', N'金至元', NULL, N'敞口，深壁，短圈足。全器施牙白釉，碗心刻劃波濤魚紋，壁口沿下飾弦紋一道。全器施釉，僅口緣一圈露胎，呈褐色。胎體勻薄，器壁見拉坯遺痕，並有多處消釉痕，積釉處成牙黃色。', N'高 10.4 公分、口徑 23.5 公分、底徑 11.5 公分', N'/media/catalog/ceramic/中瓷001326N000000000/display.jpg', N'/media/catalog/ceramic/中瓷001326N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18536?dep=U', N'CC-BY-4.0', N'定窯 白瓷魚藻紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c9b0df34-0712-2351-83f2-e163903d642c', N'故琺000752N000000000', N'掐絲琺瑯獸耳尊式瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。器仿青銅尊造型，撇口，削肩，夸腹，圈足，肩上嵌銜環鋪首一對，其中一環已失，口與足皆作方形，器裡與底露胎。以掐絲琺瑯為飾，器身以掐絲琺瑯為飾，施淺藍色釉為地，以深藍飾雲紋寬帶三將裝飾分為四層，分飾蕉葉雲紋、拐子龍、龍或鳳、海上飛馬，圖案豐富用彩多樣。器底鈐陽文楷款「景泰年製」。', N'高 38.7 公分；口徑長 16.3 公分、寬 16.2 公分；足徑長 16.9 公分、寬 16.8 公分', N'/media/catalog/enamel/故琺000752N000000000/display.jpg', N'/media/catalog/enamel/故琺000752N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61781?dep=U', N'CC-BY-4.0', N'掐絲琺瑯獸耳尊式瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a73fa34b-2a87-d0b4-c2c4-e1b62b8f01df', N'故畫00038500000', N'明王紱畫山亭文會圖　軸', 'ec78c074-e905-9285-7894-321d57e98275', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明成祖永樂二年(1404)', NULL, N'王紱（西元一三六二—一四一六年），江蘇無錫人。永樂年間，任職文淵閣，官拜中書舍人。繪畫師法元代的倪瓚、王蒙，擅長墨竹和山水題材，是元、明之際，具有承先啟後地位的重要畫家。 本幅畫五名文人雅士，聚集在涼亭裡面談詩論文，神情怡然自得，四周有山川環繞，景致優美如畫。山石樹木的線條，用筆乾渴，洋溢著沉鬱、蒼茫的氣息，很能反映出王紱晚期成熟的風格。', N'129.5 × 51.4 公分', N'/media/catalog/painting/故畫00038500000/display.jpg', N'/media/catalog/painting/故畫00038500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/3184?dep=P', N'CC-BY-4.0', N'明王紱畫山亭文會圖　軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6fcf028a-b0a5-01e0-598d-e1ce99b220b2', N'中日陶000036N000000000', N'灰陶釜', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'灰陶釜，圓口，折肩，平底。全器平素。', N'高 5 公分、口徑 6.3 公分、腹徑 8.7 公分、底徑 2.1 公分', N'/media/catalog/ceramic/中日陶000036N000000000/display.jpg', N'/media/catalog/ceramic/中日陶000036N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/71772?dep=U', N'CC-BY-4.0', N'灰陶釜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2309010f-b549-3a28-9613-e1fabeee9e81', N'中玉000302N000000000', N'玉璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋至明', NULL, N'玉質，色青白而有赭斑。為一大孔玉璧，亦可稱為「瑗」。一面淺浮雕龍紋兩隻牽連圈圍器面為飾，另一面則陰線刻螭龍六隻為飾。器內外徑均有廓。附木架。', N'徑 11.57 公分', N'/media/catalog/jade/中玉000302N000000000/display.jpg', N'/media/catalog/jade/中玉000302N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53055?dep=U', N'CC-BY-4.0', N'玉璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d3658504-e0a5-adb5-fd7e-e44e6b13cc29', N'故琺000626N000000000', N'掐絲琺瑯帶三環尊式瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，敞口短頸，豐肩斂腹，鋪首銜環三，並有三獸足。口緣鏨回紋一圈，頸有仿古銅器上常見的蟬紋一圈，惟蟬紋之首呈如意雲頭狀。腹壁則掐絲藍地纏枝番蓮紋為飾。附內膽，足底鑄「景泰年製」楷款。', N'高 17.2 公分、口徑 11.3 公分、足徑 10.1 公分', N'/media/catalog/enamel/故琺000626N000000000/display.jpg', N'/media/catalog/enamel/故琺000626N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/61681?dep=U', N'CC-BY-4.0', N'掐絲琺瑯帶三環尊式瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('eb182b8f-4f7f-246c-0cd4-e4eb2edc08d3', N'贈銅000438N000000000', N'日本 江戶時代 十七世紀或更晚 銅鎏金女神立像', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'江戶時代 十七世紀或更晚', NULL, N'雕像前半為壓模成型，後半以木雕拼接，台座為後加。圓胖的臉形兩側披著髮，頭戴半月形冠飾，冠後露出高髻，神情舒緩。頸披巾，衣著寬鬆，衣袖在肩與手臂處作三層，袖幅寬而長遮住手，上衣在腰上繫帶，腰帶翻折，下身有裙及長袍，亦作三層，以陰刻線表現衣褶與裙褶，上身短而寬，整體造型圓，而線條鬆。圖像內容可能和日本神道有關。', N'高 10.4 公分、徑 5.5 公分', N'/media/catalog/bronze/贈銅000438N000000000/display.jpg', N'/media/catalog/bronze/贈銅000438N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47068?dep=U', N'CC-BY-4.0', N'日本 江戶時代 十七世紀或更晚 銅鎏金女神立像 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ae2e166e-4e2c-3dd2-cff3-e51f1e58fe83', N'故漆000321N000000000', N'剔彩雙龍紋長方盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'方盤，斜沿委角，圈足，足內髹黑漆。盤沿底面，飾紅漆連枝花卉，中央起枝，即開一花，左右各連續二枝，各二種花卉，故一側雕五花。短邊同樣方式雕三花。盤面盤沿為松竹梅，中央一糾結的太湖石立於小丘之上，左右橫向伸出松枝、梅幹，枝葉分佈大致作左右對稱，長邊與短邊轉接處作如意雲頭式樣，上陰刻花形六角格錦地。盤心下段，綠地刻波浪紋錦地，海水起伏，前方矗立三座山峰，山石旁海水洶湧，激起浪花。盤心上段，黃地花形斜方格錦地，紅地雙龍左右相對，一龍首在上，一龍首在下，隔一火球相望，行龍外，間飾如意雲紋。底有「大明宣德乙未年製」八字款。', N'長 21.1 公分、寬 19.8 公分、高 4.8 公分', N'/media/catalog/lacquer/故漆000321N000000000/display.jpg', N'/media/catalog/lacquer/故漆000321N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18282?dep=U', N'CC-BY-4.0', N'剔彩雙龍紋長方盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('70f9fba7-64ae-7c14-de22-e5fffa7ac862', N'贈錢001261N000000000', N'道光通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「道光通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001261N000000000/display.jpg', N'/media/catalog/coin/贈錢001261N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9084?dep=U', N'CC-BY-4.0', N'道光通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('92a78e4b-61a0-83f0-fca4-e60526e390e5', N'中漆000047N000000000', N'剔紅八仙人物桃式盒(張果老)', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'桃式盒。蓋面剔紅圖案，中心人物為八仙之一「張果老」，帶平頂帽，著寬博衣裳，手持魚鼓；周圍以松竹及山岩，回紋表示天，萬字錦紋表示地，最外圈為蝙蝠和如意雲頭紋。器面其餘部分雕六角形花紋。', N'長 15.0 公分、寬 14.2 公分、高 9.9 公分、深 4.8 公分、底徑長 9.7 公分、寬 9.4 公分', N'/media/catalog/lacquer/中漆000047N000000000/display.jpg', N'/media/catalog/lacquer/中漆000047N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17456?dep=U', N'CC-BY-4.0', N'剔紅八仙人物桃式盒(張果老) 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('32e70222-7862-17f0-9855-e694544f5268', N'故琺000594N000000000', N'掐絲琺瑯蟠龍瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，仿宋瓷中器形線條優雅的玉壺春瓶形制，侈口，細頸，削肩，球腹，圈足。器表施藍釉為地，口緣下飾三圈五彩如意雲頭紋，全器飾五周各色的橫「S」形轉枝番蓮紋，瓶頸盤一高浮雕式鍍金龍。底鑄去地陽文「景泰年製」方框楷書偽款，應屬十七世紀期早期的文物。', N'高 40.5 公分、腹徑 25.0 公分', N'/media/catalog/enamel/故琺000594N000000000/display.jpg', N'/media/catalog/enamel/故琺000594N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1538?dep=U', N'CC-BY-4.0', N'掐絲琺瑯蟠龍瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6c9d935c-9cde-8420-9e53-e7a3e552b5f7', N'中琺000090N000000000', N'鍍金裡銅琺瑯大碗', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'口微撇，深壁，圈足。器身紋飾以掐絲琺瑯技法完成，器表淺藍地，四圓形開光平均分列，內各有一深藍地篆體金字：「萬」、「壽」、「無」、「疆」，開光隙地各飾一組五彩轉枝番蓮紋。腹底與口緣紋飾以內填琺瑯技法完成，腹底飾一圈綠地鑄飾蓮瓣紋，碗緣飾綠地鍍金製拐子龍紋邊飾。底陰刻「子孫永寶」四字雙行雙方框篆款。', N'高 7.3 公分', N'/media/catalog/enamel/中琺000090N000000000/display.jpg', N'/media/catalog/enamel/中琺000090N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53964?dep=U', N'CC-BY-4.0', N'鍍金裡銅琺瑯大碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('62f629df-cdc4-ec98-734b-e7dcf6d0ebd9', N'贈雕000047N000000000', N'牙梳柄', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'ca8136fd-d414-902c-3f23-189593397b2d', N'東周', NULL, N'全器已殘，可能是一牙梳之柄部；下端有二榫孔以便安插梳身，上端左右亦各有一榫孔以安插立雕飾件(或為鳥首)，皆已佚。梳柄飾以兩條高浮雕的蛇，左右僅餘鳥身與鳥尾：中央為牙材本身長圓形孔，一端用一塊牙材填塞，另一端之填塞物已佚。全器雕工古樸，並已被染成淡綠色。山東曲阜春秋早期魯國墓葬中曾出土一件牙梳；山東萊蕪上崮戰國墓葬也曾出土兩件牙梳，其中一件梳柄之兩側也各以榫卯接一小梳。前述二地墓葬出土的梳柄之形制和雕工，可為此件斷代之依據；後者兩端各以榫卯接一小梳，也可做為此件兩端有孔可榫接小梳之參考。', N'長 4.9 公分、最厚 2.2 公分', N'/media/catalog/carving/贈雕000047N000000000/display.jpg', N'/media/catalog/carving/贈雕000047N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45273?dep=U', N'CC-BY-4.0', N'牙梳柄 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('69f4e007-5629-31c6-f35e-e7f4a295eb43', N'故漆000385N000000000', N'剔紅七賢過關人物圖圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'扁圓形盒，金屬胎，子母口，盒內髹褐漆，盒底黑漆似重髹。盒底外圍雕花卉紋，牡丹與菊花分居四角，花朵兩側枝葉橫置，花瓣及葉脈作減地淺浮雕，刀法平直，花葉平鋪直敘。盒蓋雕山水人物，前景五位騎乘者，漫行於山林間，隔著重重山崖，左上方遠處二位騎乘者，即將經過山石到達一關口。近景最前面一人騎牛，手持書卷，最後面一人騎麒麟，其他人騎著馬或騾，眾人顧盼談笑，氣氛熱鬧。盒面四周大石圍繞，右上一排山脈斜切畫面，將空間分為近景與遠景，構圖大膽，圓轉的岩石，紋理斜切，充滿動感，茂密的樹林和滿鋪地面的錦地，畫面密實，物象間微露地漆。漆色紅潤，漆質堅硬，斜刀、直刀並用，刀法穩定，人物表情生動，雕工細密，是十五世紀少見的佳品。底有「大明宣德年製」六字款。', N'高 3.8 公分、徑 8.9 公分', N'/media/catalog/lacquer/故漆000385N000000000/display.jpg', N'/media/catalog/lacquer/故漆000385N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17726?dep=U', N'CC-BY-4.0', N'剔紅七賢過關人物圖圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0d36dbaa-680f-37c7-6e19-e836738c2e08', N'購錢000378N000000000', N'乾元重寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'方孔圓錢，正面有隸書：「乾元重寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000378N000000000/display.jpg', N'/media/catalog/coin/購錢000378N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9716?dep=U', N'CC-BY-4.0', N'乾元重寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a37aa68c-d944-ea39-b220-e86f15746ace', N'購錢000595N000000000', N'聖宋元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有行書：「聖宋元寶」四字，漫漶不清，背面無文。', N'待測量', N'/media/catalog/coin/購錢000595N000000000/display.jpg', N'/media/catalog/coin/購錢000595N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9933?dep=U', N'CC-BY-4.0', N'聖宋元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('abcc809a-63eb-697d-da1a-e989acaf127c', N'南購畫00001100000', N'東海道一 五十三次 日本橋', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪起點日本橋（現東京都中央區）風景，畫面由左而右標示「東海道一」、「五十三次 日本橋」、「新板五十三次芝丸清板」、「廣重画」，畫面框外左下角「芝神明前 丸清板」印。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001100000/display.jpg', N'/media/catalog/painting/南購畫00001100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36466?dep=P', N'CC-BY-4.0', N'東海道一 五十三次 日本橋 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7a7d1c9d-5616-3d8c-0ae7-e99f8e4dc995', N'中銅000006N000000000', N'鋪首銜環壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'直口、長頸、斜肩、圓腹、圈足。蓋上有三環鈕。肩部有鋪首銜環，圈足外撇。通體樸素無紋。', N'高 26.9 公分', N'/media/catalog/bronze/中銅000006N000000000/display.jpg', N'/media/catalog/bronze/中銅000006N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6098?dep=U', N'CC-BY-4.0', N'鋪首銜環壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('28df78cc-57b2-9b74-fdf1-e9ccb036fa00', N'購玉000250N000000000', N'花鳥紋玉簪首', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐', NULL, N'玉質，色青白，有白斑。呈三角形，雙面淺浮雕朵花與葉，其間停有小鳥，鳥翅與花葉交錯。一角鑲嵌鏤雕枝葉果實的金屬飾件。', N'連銀柄長 9.85 公分', N'/media/catalog/jade/購玉000250N000000000/display.jpg', N'/media/catalog/jade/購玉000250N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52200?dep=U', N'CC-BY-4.0', N'花鳥紋玉簪首 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f992545a-3a40-7132-bc2e-e9e9c2d06284', N'贈雕000195N000000000', N'骨雕鸞鳳綬帶板', '4aa6ad59-8ede-1076-3507-38fb519f20c2', 'f2a78063-931b-9926-749c-324377d136c7', N'宋至元', NULL, N'長方形，四隅與中央凹入，每一邊亦內弧，兩面周邊皆起寬棱，一面中央浮雕壽石，左右各浮雕一鸞或一鳳翔於牡丹花叢中；另一面在中央分界成左右各一方形，各雕一綬帶鳥翔於牡丹花叢中，鸞鳳與綬帶鳥皆首尾相錯地面像器中央。此器兩面皆浮雕紋飾，原可能是他器之嵌件。', N'長 15.3 公分、寬 6.2 公分、厚 1.9 公分', N'/media/catalog/carving/贈雕000195N000000000/display.jpg', N'/media/catalog/carving/贈雕000195N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45423?dep=U', N'CC-BY-4.0', N'骨雕鸞鳳綬帶板 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0977cecb-2d4a-e0d5-c6e6-ea6de5cc3ad2', N'中銅001237N000000000', N'仿伊斯蘭回文盃', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'圓簋，侈口，弧形壁，圈足。腹有紋飾三圈，無法辨識。器另內有圓形紋飾。', N'高 12.0 公分', N'/media/catalog/bronze/中銅001237N000000000/display.jpg', N'/media/catalog/bronze/中銅001237N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6704?dep=U', N'CC-BY-4.0', N'仿伊斯蘭回文盃 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('97d3b1c3-ae4b-3c22-6fdc-ea6e8c3e85f4', N'故漆000398N000000000', N'剔紅鹿苑長春圖多寶格長方盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'故宮多寶格之來源，有承自明代宮中收藏者，這件長方盒，即是一例。漆器的製作、是在胎上髹飾數十層漆，再於漆上雕刻各種紋飾，這種漆工藝即稱之爲「雕漆」。但若純髹以紅色漆者、即稱之曰「剔紅」。這種雕漆的技法，始於唐、興於宋、元，而盛於明、淸，此器即屬明代「剔紅」之作品，其胎是木質，器作長方形，全器分二層，唯漆甚厚、漆色深紅、光澤溫潤、全器周壁、雕飾群鹿嬉戲於其中，按鹿爲長壽之獸。古書記載：「千年爲蒼鹿、又五百年爲白鹿、又五百年爲玄鹿。」更因鹿與福祿壽中的「祿」同音，含有官爵之意，所以百鹿即代表富貴。又因鹿是一種長壽的動物，所以常被用作各種古器物上的紋飾。此器滿佈群鹿嬉戲之狀，形態極爲生動。有作伏臥狀，有作佇立狀，或在覓食，或在競走，或在靜聽，或在呦鳴！各種神情，不一而足。隙地襯以松，竹、梅、山石、靈芝，再填刻各種錦地，如回紋、水波紋、繡球紋、朶紋、古錢紋、萬字紋等不下十數種，其構圖之精細，可見一斑。紋飾佈置，雖滿佈多樣、然仍能井然有序、繁而不亂，雕刻亦屬精緻，刀法深峻而圓潤、其層次遠近景緻，亦能自其刀法中顯現，誠屬難可貴。此器存放各式珍玩三十二件，其中以玉器居多，另有牙器、瑪瑙、畫册等等。', N'長 38.5 公分、寬 24.7 公分、高 23.7 公分', N'/media/catalog/lacquer/故漆000398N000000000/display.jpg', N'/media/catalog/lacquer/故漆000398N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/62064?dep=U', N'CC-BY-4.0', N'剔紅鹿苑長春圖多寶格長方盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4b0935de-c388-e688-947f-ead6f6877d36', N'贈雕000137N000000000', N'骨簪', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'取一片骨材磨成一端鈍尖，一端扁平圓弧。全器光素，傷蝕嚴重。', N'長 13.9 公分、最寬 1.4 公分', N'/media/catalog/carving/贈雕000137N000000000/display.jpg', N'/media/catalog/carving/贈雕000137N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45366?dep=U', N'CC-BY-4.0', N'骨簪 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('ee95ef15-e96f-e473-32c0-ead899a5f257', N'故玉000476N000000000', N'獸及雲紋玉璧', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'白玉，深色沁，並帶黑斑。一面淺浮雕雙獸紋；一面則雕如意雲紋。', N'徑 10.3 公分、孔徑 3.2 公分、厚 0.7 公分', N'/media/catalog/jade/故玉000476N000000000/display.jpg', N'/media/catalog/jade/故玉000476N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48675?dep=U', N'CC-BY-4.0', N'獸及雲紋玉璧 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d11ef2c3-9a37-f5d7-1599-ebf82152c57d', N'故銅002005N000000000', N'群仙高會鏡', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'圓形鏡，半球鈕。鏡緣寬素。鏡背浮雕紋飾為一幅仙人宴享圖。上方為仙山樓閣及雲朵，右方有一仙人乘鳳降臨。仙人或立或坐，齊聚柳畔宴飲嬉遊。 仙人服飾帶有晚唐五代風情，鏡體及紋飾布局則具有金代特徵，為金代山水人物故事鏡中的佳構。', N'直徑 18.9 公分', N'/media/catalog/bronze/故銅002005N000000000/display.jpg', N'/media/catalog/bronze/故銅002005N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/5433?dep=U', N'CC-BY-4.0', N'群仙高會鏡 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('0355891e-623c-b96b-f6ea-ec0286dac181', N'故漆000272N000000000', N'剔黃山海龍鳳花卉紋圓盤', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明 嘉靖', NULL, N'圓盤，圓沿，圈足，足內髹紅漆，盤內外均為紅地剔黃。底款嘉靖壬午年為嘉靖元年，西元1522年。盤底盤沿飾連枝花卉紋，花卉四種輪替，花形簡化，枝末花朵盛開，同時起另一枝。正面盤沿四開光，開光內連枝花卉，花葉左右對稱安排穩定平均。開光外，鋪錦地，各飾八寶其中的四寶。盤心紅漆錦地上飾龍鳳紋。下段波浪紋錦地，沿邊海水翻湧，一座山峰矗立，浪花飛揚。盤心中央及上段，紅漆米字形方格錦地，一龍騰空躍起，一鳳從天而降，隔火球，相互對望。龍身瘦長彎轉，瞪眼張口吐舌，四足外張，龍鰭飛揚，形貌強悍威嚴。鳳鳥頸細尾寬，張翼昂首，飄然輝煌。龍鳳外，連枝花卉上下纏繞，四種花卉自右側進入盤面，牡丹正位於畫面正上方，兩兩相應，構圖緊湊，佈局靈活均衡，頗具生氣。漆層薄，漆色潤，刀法熟練俐落，陰刻線條拙重，黃、紅相映，莊嚴中不失富麗，是官方雕漆的典型。', N'高 2.8 公分、徑 21.1 公分、足徑 17.1 公分', N'/media/catalog/lacquer/故漆000272N000000000/display.jpg', N'/media/catalog/lacquer/故漆000272N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18011?dep=U', N'CC-BY-4.0', N'剔黃山海龍鳳花卉紋圓盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2cb13462-526b-c08f-f400-ec1a6cf1e97c', N'中銅001192N000000000', N'獸面紋銅爐', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'器分上下兩層，上層的花口，和連接上下的把手，同樣造型柔婉。下層的獸面作淺浮雕，紋飾線條俐落，獸眼炯炯有神，運用古青銅裝飾母題，卻別具新意。內裝一筒型，筒上有鏤空鍍金雲龍紋，可供取暖之用。', N'長 20.0 公分、寬 15.2 公分、高 15.0 公分', N'/media/catalog/bronze/中銅001192N000000000/display.jpg', N'/media/catalog/bronze/中銅001192N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1929?dep=U', N'CC-BY-4.0', N'獸面紋銅爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c1773422-bab8-d1ef-b766-ed0ba0a0862f', N'中銅000505N000000000', N'嵌銀絲雙鳳紋洗', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'洗，盤口、平底。全器紋飾均為陰刻線，盤口飾卷草紋，腹內側飾雲紋，內底飾雙鳳，飛翔於雲紋間。', N'高 10.3 公分', N'/media/catalog/bronze/中銅000505N000000000/display.jpg', N'/media/catalog/bronze/中銅000505N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6282?dep=U', N'CC-BY-4.0', N'嵌銀絲雙鳳紋洗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('36b3b696-6a28-50aa-a8de-ed7633762e62', N'中漆000079N000000000', N'剔紅八寶番蓮紋燭台', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'燭台，共有兩層承盤，上層附金屬燭插，足為覆鐘式。內外皆髹朱漆。兩承盤口沿、足沿各雕回紋一周，承盤內外壁、柱及足均雕捲枝番蓮紋，大承盤和足下半部雕有八寶紋，均襯以菱格朵花錦地紋。承盤口沿下一處雕「大清乾隆年製」六字篆款。為供具，一爐、二瓶、二燭台合稱「五供」，此為其中一件燭台。院藏中漆76-中漆80為一套五供。', N'燭台高 27.6 公分、通阡高 36.2 公分、足深 6.6 公分、托徑 7.3 公分、承盤徑 14.4 公分、足徑 12.5 公分', N'/media/catalog/lacquer/中漆000079N000000000/display.jpg', N'/media/catalog/lacquer/中漆000079N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17479?dep=U', N'CC-BY-4.0', N'剔紅八寶番蓮紋燭台 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('29e75b8e-1c24-87c6-e15b-ed77c7715d29', N'中玉000004N000000000', N'玉獸面簋形爐', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'⽟簋式爐，雙耳，圈足。玉有綹。局部染為褐色。獸⾸⽿，下有垂珥。口沿下紋飾帶為獸面、渦紋及扉稜，器腹飾大獸面紋。 附後配之玉頂木蓋，木蓋上為元代汀渚鷺鷥紋玉頂。', N'通寬 19.0 公分、爐高 5.8 公分、通高 11.3 公分、口徑 12.0 公分、底徑 7.2 公分', N'/media/catalog/jade/中玉000004N000000000/display.jpg', N'/media/catalog/jade/中玉000004N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52741?dep=U', N'CC-BY-4.0', N'玉獸面簋形爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9f5d754d-9801-a374-0681-edba10f2dacf', N'中琺000121N000000000', N'掐絲琺瑯花果紋轎瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 乾隆', NULL, N'銅胎，前面為侈口豐肩斂腹瓶，連接浮雕式夔龍紋之座，靠牆面平，頸下方有一孔可以直接掛在牆面的釘上，故稱壁瓶，清檔中稱之轎瓶。此瓶白地以藍色茶花枝葉為錦，瓶腹掐絲「御製」二字，詞句則採掐絲雙鉤填墨的方式「生意四時具，韶光一室融。」落「臣于敏中」紅地陽文鍍金字、「恭寫」鍍金地陰文填紅字。瓶內插由珊瑚、碧玉與黃色石材製成的花枝。', N'高 23.5 公分', N'/media/catalog/enamel/中琺000121N000000000/display.jpg', N'/media/catalog/enamel/中琺000121N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1564?dep=U', N'CC-BY-4.0', N'掐絲琺瑯花果紋轎瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('9d8fb9fb-d1f1-ece6-205d-ee30cc56a581', N'故銅001416N000000000', N'「茅鄉」銅印', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '561e3931-1096-c637-9eb3-b5c5ce02c88f', N'秦', NULL, N'鼻鈕，長方形印，印面白文「茅鄉」二字，無邊；「茅」為姓，「鄉」字原印譜釋為「卿」，商周文字之「卿」與「鄉」寫法本同，但因秦篆始訛字，故孳生「鄉」字。此印筆畫安排自然，未見漢之工整，「鄉」字又非商周寫法，當屬秦印無疑。', N'高 1.1 公分、印面長 2.22 公分、寬 1.3 公分', N'/media/catalog/bronze/故銅001416N000000000/display.jpg', N'/media/catalog/bronze/故銅001416N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/4811?dep=U', N'CC-BY-4.0', N'「茅鄉」銅印 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f6f7e81a-850a-1731-4080-eea056482a3c', N'中玉000312N000000000', N'玉璜', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'ca8136fd-d414-902c-3f23-189593397b2d', N'西周中期', NULL, N'玉質，青白色，器面均以陰線刻變形雲氣紋為飾，器之兩端各有二穿，正可供佩飾時穿引綁縛之用。', N'長 16.4 公分', N'/media/catalog/jade/中玉000312N000000000/display.jpg', N'/media/catalog/jade/中玉000312N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/53064?dep=U', N'CC-BY-4.0', N'玉璜 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('06fa5ecb-52cf-2909-739c-eeca8f028bd0', N'購錢002313N000000000', N'元□通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「元□通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢002313N000000000/display.jpg', N'/media/catalog/coin/購錢002313N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/11651?dep=U', N'CC-BY-4.0', N'元□通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bdf49dff-6d15-e361-1881-efb2b12e4273', N'中漆000068N000000000', N'剔紅雲龍紋長方匣', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅長方形文具匣，色硃紅有光澤，器身有小傷缺。匣作對開式門，嵌金屬小扣鎖。每面皆以波濤紋為地，之上雕戲珠龍紋，周身有火焰，闊面雙龍並作相視對稱狀。頂面立雕二龍，龍凸睛雙角，鬚髮飛揚，盤身四足著地，五爪沒入波濤中，鱗片銳利細膩，造型威猛有力。', N'長 38.8 公分、寬 19.9 公分、通高 31.6 公分、深 20.9 公分', N'/media/catalog/lacquer/中漆000068N000000000/display.jpg', N'/media/catalog/lacquer/中漆000068N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17534?dep=U', N'CC-BY-4.0', N'剔紅雲龍紋長方匣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('5570d2a4-98cb-56f7-79b0-f01a24fd4926', N'贈雕000056N000000000', N'骨雙拼龍紋帶鉤', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國', NULL, N'全器由兩塊骨材組成，有一塊殘斷成三段，今已黏合。器身各有二橫穿相連接，完整的一塊鉤首多出一孔；鉤形位於中央稍偏鉤首部位。器身呈曲棒形，尾端翹起作龍首形，凹刻出龍唇、陰刻弧線作面紋，小圈點紋飾眼部與龍額，身軀飾陰線、弧線、小圈點紋與密點紋等。器身正面近鉤鈕部位各鑿一三角形深槽，向龍首方向居中並橫越於兩塊骨上鑿一三角形深槽。三處凹槽原或有綠松石類嵌件。在已發表的資料中，骨質帶鉤幾乎都屬戰國時代，但未見由兩塊組成之雙拼帶鉤者。在眾多出土的帶鉤中，末端翹起者見於戰國與漢代。帶鉤可供繫帶，也可懸佩器物，有的帶鉤則僅做佩飾，似此長型帶鉤，則多做繫帶的帶鉤。', N'長 13.0 公分', N'/media/catalog/carving/贈雕000056N000000000/display.jpg', N'/media/catalog/carving/贈雕000056N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45282?dep=U', N'CC-BY-4.0', N'骨雙拼龍紋帶鉤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('3de8588f-808d-21ee-d7ae-f0cec0ac5630', N'故漆000335N000000000', N'剔紅牡丹長頸瓶', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'瓶，盤口，長頸，頸及腹均直，圈足，底髹黑漆，口沿飾回紋，全器滿飾花卉紋。頸部一主幹向左右彎轉各開一大花，正位於頸部中央，二朵之間穿插半開的花梨。下層近肩部四朵花，約中央位置四朵，互相錯落。枝幹生長的方向不清楚，花間滿佈葉片與花蕾，頸腹之間葉片相交，花形雖圓趨平面感，葉亦平鋪，紋飾佈局滿，顯得十分熱鬧。漆色紅，漆質澀，刀法板，花葉的縫隙間露出黃色素地，葉脈及瓣脈的陰刻線直硬，打磨少，不重表現植物活潑的生氣，裝飾繁複。底有「大明宣德年製」六字款。', N'高 15.4 公分', N'/media/catalog/lacquer/故漆000335N000000000/display.jpg', N'/media/catalog/lacquer/故漆000335N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50198?dep=U', N'CC-BY-4.0', N'剔紅牡丹長頸瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2571ed7c-cee5-0793-54d4-f10238cdd7c0', N'贈錢001258N000000000', N'乾隆通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'銅質。方孔圓錢，正面有楷書：「乾隆通寶」四字，背面有滿文二字。', N'待測量', N'/media/catalog/coin/贈錢001258N000000000/display.jpg', N'/media/catalog/coin/贈錢001258N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9081?dep=U', N'CC-BY-4.0', N'乾隆通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2990ab65-0181-c9d6-9dcd-f11f21710704', N'南購畫00002500000', N'東海道十五 五十三次 吉原', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪吉原宿（靜岡縣富士市）風景，畫面由右而左標示「東海道十五」、「五十三次 吉原」、「廣重画」，畫面左下副題「名所左り不二」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002500000/display.jpg', N'/media/catalog/painting/南購畫00002500000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36480?dep=P', N'CC-BY-4.0', N'東海道十五 五十三次 吉原 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('06984c9b-b2ac-cc3c-00d7-f1a775fb49e1', N'購錢003854N000000000', N'大觀通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，「大觀通寶」有銅、鐵兩種材質。正面有楷書「大觀通寶」四字，相傳為徽宗御筆瘦金體，背面無文。', N'待測量', N'/media/catalog/coin/購錢003854N000000000/display.jpg', N'/media/catalog/coin/購錢003854N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/13192?dep=U', N'CC-BY-4.0', N'大觀通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('117cc883-5660-43d8-d55d-f1fde1467bd5', N'贈瓷000477N000000000', N'三彩印花牡丹紋方碟', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '407ae0da-98c7-4dff-3ad7-f5dd9f5cb30a', N'遼', NULL, N'方碟，花形敞口，斜壁，平底。器施白、黃、綠三彩釉，底露胎無釉。器內底心及均分成八格的內壁，各印牡丹花葉，四角加飾綠葉一片。', N'長 12.4-12.6 公分、高 2.6 公分', N'/media/catalog/ceramic/贈瓷000477N000000000/display.jpg', N'/media/catalog/ceramic/贈瓷000477N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/43506?dep=U', N'CC-BY-4.0', N'三彩印花牡丹紋方碟 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('49d0dd69-8bab-5245-3066-f2506a167231', N'購錢000505N000000000', N'治平元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有篆書：「治平元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000505N000000000/display.jpg', N'/media/catalog/coin/購錢000505N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9843?dep=U', N'CC-BY-4.0', N'治平元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('fc26a0fc-101d-143d-ede6-f26e7635fa34', N'南購畫00001400000', N'東海道四 五十三次 加奈川', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪神奈川宿或稱加奈川（現神奈川縣橫濱市神奈川區）風景，畫面由右而左標示「東海道四」、「五十三次 加奈川」、副題「台の茶や」、畫面左下角「廣重画」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00001400000/display.jpg', N'/media/catalog/painting/南購畫00001400000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36469?dep=P', N'CC-BY-4.0', N'東海道四 五十三次 加奈川 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2a43a1b3-a688-f611-0470-f2f119be1df4', N'中琺000171N000000000', N'掐絲琺瑯彝爐', '824b8d54-541c-1b21-e56c-a5d807800f18', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'長方形，直口，深壁，平底，雙螭形耳，方形外撇圈足，帶盝頂式蓋辟邪鈕。全器以淺藍色為地，以掐絲技法製作紋飾，蓋頂飾卍字不斷錦，蓋沿及腹部每面飾兩兩相對龍紋，上下方飾拐子龍紋，腹部下緣及圈足外各飾一圈蕉葉紋。足底及底部露胎。', N'口徑長 25.0 公分、寬 23.6 公分', N'/media/catalog/enamel/中琺000171N000000000/display.jpg', N'/media/catalog/enamel/中琺000171N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54041?dep=U', N'CC-BY-4.0', N'掐絲琺瑯彝爐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('6364a5ff-efc2-0d5e-5085-f3421ceed5f4', N'中漆000065N000000000', N'剔紅三獅戲球紋長方匣', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'剔紅長方形匣，朱漆艷紅有光澤。罩式蓋，矮壁、底淺凹。頂與四壁均以回紋二道分隔畫面，外圍斜方回紋錦地雕纏枝番蓮花紋，四壁中央雕團形花一列，頂面中央則雕三獅戲球，獅圓睛捲鼻，毛髮捲長，周身並有火焰紋。器內為髹黑漆雙層盒，無紋飾。', N'長 33.0 公分、寬 19.9 公分、高 10.1 公分', N'/media/catalog/lacquer/中漆000065N000000000/display.jpg', N'/media/catalog/lacquer/中漆000065N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17526?dep=U', N'CC-BY-4.0', N'剔紅三獅戲球紋長方匣 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('56862da6-c833-c4ab-f863-f3a7c4fa89b5', N'購錢001863N000000000', N'熙寧重寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「熙寧重寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001863N000000000/display.jpg', N'/media/catalog/coin/購錢001863N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/11201?dep=U', N'CC-BY-4.0', N'熙寧重寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('c8e121e5-608c-b736-966a-f3f0a6f3d852', N'贈錢001177N000000000', N'紹興通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'南宋', NULL, N'方孔圓錢，正面有楷書「紹興通寶」四字，相傳為高宗御筆，背面無文。', N'待測量', N'/media/catalog/coin/贈錢001177N000000000/display.jpg', N'/media/catalog/coin/贈錢001177N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9000?dep=U', N'CC-BY-4.0', N'紹興通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('002b9689-6729-7b39-2291-f515b5e47354', N'購玉000626N000000000', N'石調色盤', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '09edc65b-9a58-8539-4766-476f636a88a0', N'商', NULL, N'白大理石類，表面多已變黃赭色，局部輕微風化。器身琢作一上大下小的方柱體，上面有四個圓筒形凹槽，正中央有一小圓凹。方柱體的外壁，刻兩道各三組凹弦紋。方柱體之下端，有四短足。柱體之一側，伸出一有長頸的牛頭，牛角向後，眼、耳鼻頭的雕琢，簡單自然。整體造形有似一體軀成方柱體的老牛。不確定其真實功能，一般稱之為「調色盤」。', N'長 13.0 公分、高 5.5 公分', N'/media/catalog/jade/購玉000626N000000000/display.jpg', N'/media/catalog/jade/購玉000626N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/52522?dep=U', N'CC-BY-4.0', N'石調色盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('bd41fda7-22ca-2544-bb21-f5a8d9aa2b5b', N'購錢000563N000000000', N'咸平元寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有楷書：「咸平元寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢000563N000000000/display.jpg', N'/media/catalog/coin/購錢000563N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/9901?dep=U', N'CC-BY-4.0', N'咸平元寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('d273f152-25dc-0b3e-fde3-f5cc039af09f', N'中琺000869N000000000', N'掐絲琺瑯鋪首銜環尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。侈口，長頸，溜肩，雙獸首啣環耳，圓腹，高圈足外撇。以掐絲技法製作紋飾，全器淺藍地，頸部飾雲紋錦地葡萄藤紋，肩部飾轉枝番蓮紋，腹部飾雲紋錦地昇龍一對、火珠、海水江牙、花朵紋，圈足飾轉枝番蓮紋，各組紋飾間以條狀藍地花朵紋為間飾。', N'高 51.8 公分、口徑 18.3 公分', N'/media/catalog/enamel/中琺000869N000000000/display.jpg', N'/media/catalog/enamel/中琺000869N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54692?dep=U', N'CC-BY-4.0', N'掐絲琺瑯鋪首銜環尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('86ae876c-5f5c-5675-4b0a-f678ac1911bc', N'中瓷000001N000000000', N'粉彩描金法輪', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清 嘉慶', NULL, N'全器為法輪，托以須彌座。法輪中心為鏤空八輪輻形，外以心形火焰飾之。輪的部份鑲飾琺瑯釉點，若仿松石、珊瑚、藍寶石。金色心形火焰為印花卷草紋。須彌座上部為雲紋與三寶蓮葉，足脛以連珠紋飾，外撇的足部模印浮雕細蓮瓣紋，足內金彩書「大清嘉慶年製」三行六字篆款。', N'高 19.7 公分、底徑 8.7 公分', N'/media/catalog/ceramic/中瓷000001N000000000/display.jpg', N'/media/catalog/ceramic/中瓷000001N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/21537?dep=U', N'CC-BY-4.0', N'粉彩描金法輪 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('66afc79c-5157-b58a-6d00-f75b8da794ca', N'購錢001822N000000000', N'治平通寶', '2c5c80d7-6c3a-219f-835a-511d5ec59a23', 'eb297c65-bbaf-0a53-93cc-f574c8d5faa6', N'北宋', NULL, N'方孔圓錢，正面有隸書：「治平通寶」四字，背面無文。', N'待測量', N'/media/catalog/coin/購錢001822N000000000/display.jpg', N'/media/catalog/coin/購錢001822N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/11160?dep=U', N'CC-BY-4.0', N'治平通寶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('dc6634fe-226c-a365-1b74-f94043146a6e', N'中瓷003788N000000000', N'定窯 白瓷劃花龍紋大盤', '9611dce4-97c7-26b6-0248-7cb003d17c3d', '7fd11f09-8bdb-8d52-fddd-7a54353729b9', N'金', NULL, N'敞口，弧壁下斂，圈足。口緣露胎，可見本器以覆燒技法製作。整器施白釉，釉色呈牙白，器外壁可見多道弦紋，器內壁則以劃花技法刻畫一蟠龍，以為本器之主要紋飾。', N'高 6.2 公分、口徑 30.0 公分、底徑 12.0 公分', N'/media/catalog/ceramic/中瓷003788N000000000/display.jpg', N'/media/catalog/ceramic/中瓷003788N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/19949?dep=U', N'CC-BY-4.0', N'定窯 白瓷劃花龍紋大盤 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('f7738e89-ea23-6e7b-2703-f97c9e1b96c7', N'故玉002238N000000000', N'玉觽', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '925e3b9e-8ff0-62fa-ea9a-58afbdd68019', N'春秋晚期', NULL, N'玉質，因沁染玉色呈深赤，較寬一端呈黑色。作三分之一圓弧玉片器，雕一龍形，較寬一端為首，器身布滿春秋中晚期流行的浮雕側面龍首紋。由部分紋飾並不完整可知，本器可能原為玉珩，後改製成今貌。寬端與器身中央各有一小孔以供佩掛。', N'長 9.5 公分、寬 1.2 公分、厚 0.6 公分', N'/media/catalog/jade/故玉002238N000000000/display.jpg', N'/media/catalog/jade/故玉002238N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/50371?dep=U', N'CC-BY-4.0', N'玉觽 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('1a4b32ac-92d2-1ac4-c281-f9cd0e9e44c2', N'贈玉000003N000000000', N'禪地祇玉冊', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', 'bd2e592c-cade-9ae8-aefb-2d163480cf07', N'唐玄宗開元十三年', NULL, N'唐玄宗禪地玉冊共十五簡，長短不一。簡與簡之間以金屬線串聯。冊文係以斜刀鐫刻後塗金，但金粉現在多已剝落。其中，除玄宗署名「隆基」二字為楷體外，餘為隸書，字跡清晰，保留了原來書寫的筆意，端整豐勻，經研究與玄宗的書風相符，應該是他親筆御書之作。', N'單簡長 29.9 公分、寬 2.8 公分；全寬 45.3 公分', N'/media/catalog/jade/贈玉000003N000000000/display.jpg', N'/media/catalog/jade/贈玉000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1819?dep=U', N'CC-BY-4.0', N'禪地祇玉冊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('38f09b58-f613-0378-9fa7-fc4b6fceb2ae', N'中琺000666N000000000', N'掐絲琺瑯獸耳銜環尊式瓶', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎。撇口，溜肩，圓腹，雙環耳，高圈足外撇。以掐絲技法、琺瑯料填色製作花紋，口沿飾蕉葉紋，全器飾纏枝番蓮紋，環耳上方飾獸面紋，仿古銅器獸首銜環耳。', N'高 40.0 公分、口徑 15.0 公分、足徑 19.0 公分', N'/media/catalog/enamel/中琺000666N000000000/display.jpg', N'/media/catalog/enamel/中琺000666N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/54496?dep=U', N'CC-BY-4.0', N'掐絲琺瑯獸耳銜環尊式瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('7d441b46-94b2-3516-b2b1-fc5956850673', N'中銅000003N000000000', N'弦紋壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'漢', NULL, N'直口、長頸、雙環耳，斜肩、圓腹、圈足。附蓋，以鋪首銜環為鈕。器腹有凸棱二道，並飾一小耳。', N'高 29.0 公分', N'/media/catalog/bronze/中銅000003N000000000/display.jpg', N'/media/catalog/bronze/中銅000003N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/6100?dep=U', N'CC-BY-4.0', N'弦紋壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b5300a1e-74a4-f523-eb37-fc8d20bec0e8', N'贈雕000034N000000000', N'角雕人首紋錐', '4aa6ad59-8ede-1076-3507-38fb519f20c2', '537eb4b8-f69a-7ca3-e137-f528e2c7b0a3', N'西夏', NULL, N'此件取獸角製成，尖端朝下，正面上端浮雕出一人面，頂端陰刻短斜紋為頭髮，並陰刻圈點紋為眼紋(雙圈為眼形，中央深鑽一圓心為眼瞳)，斜凹雕出面頰，留出鼻部，陰刻一短線為鼻頭，再陰刻一長線為唇部。人面下方陰刻一道凹槽為頸部，頸部下方左右各斜刻兩道直線以示衣領，頷部下方(即衣領上方)陰刻一單圈圈點紋為飾。器之中段部位繞器陰刻兩道凹槽以間隔出身軀，身軀部位左右各陰刻四圈點紋，近中央部位者為雙圈，餘為單圈；凹槽上方兩側各刻一》紋，其紋正中下方而為凹槽上方部位刻一單圈圈點紋為飾。凹槽下方陰刻二道弦紋為飾，並於其下方正中部位依上下左右四方排列方式各刻一單圈圈點紋為飾。上端人面兩側於同一部位各穿一圓孔，可繫掛，亦示其雙耳。《遼史》記載當時西夏人的服御乃「冠用金縷......佩蹀躞、解錐、短刀、弓矢，......」。近人曾在寧夏回族自治區海原縣原西夏開國皇帝李元昊的行宮遺址中發掘一件人頭形鹿角質製成的解錐，長12公分，錐角直徑1.8-2.0公分，一端用作解錐的尖，角根部則雕飾人頭像，雙耳部位穿有繫繩的孔。因此，這件磋角人首紋器用或亦為當時角錐之實例。', N'長 12.0 公分', N'/media/catalog/carving/贈雕000034N000000000/display.jpg', N'/media/catalog/carving/贈雕000034N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/45260?dep=U', N'CC-BY-4.0', N'角雕人首紋錐 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('2e38e5a6-8518-d7f3-f7a3-fd0f2f718222', N'故漆000122N000000000', N'剔紅茶花梅花圓盒', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'蔗段盒，盒內髹黑漆，盒蓋與盒身紋飾相同。錦地上浮雕茶花，上側與旁邊襯著梅花，用刀直陡，花葉造型樸實，花葉分佈疏落，枝幹姿態清晰。', N'高 3.5 公分、徑 7.8 公分', N'/media/catalog/lacquer/故漆000122N000000000/display.jpg', N'/media/catalog/lacquer/故漆000122N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/18068?dep=U', N'CC-BY-4.0', N'剔紅茶花梅花圓盒 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('30afabb3-0969-0fa5-a596-fd70b594b95d', N'南購畫00002100000', N'東海道十一 五十三次 箱根', 'ec78c074-e905-9285-7894-321d57e98275', '2a787793-ab93-92c4-8f71-c90e596f8e86', N'日本江戶時代', NULL, N'《東海道五十三次》是浮世繪三傑之一是歌川廣重作品，以東海道起點和終點加上五十三個宿場特色的風景為主題，共五十五幅版畫作品，後人評價較出色的版本分別是：「保永堂版」、「行書版」和「隸書版」。 ' + NCHAR(13) + NCHAR(10) + N'本幅為江戶時代丸屋清次郎經營的「壽鶴堂」發行販賣的「隸書版」，描繪箱根宿（神奈川縣足柄下郡箱根町）風景，畫面由右而左標示「東海道十」、右下「五十三次 箱根」、畫面左下「廣重画」及副題「夜中松明とり」。', N'官方資料未提供', N'/media/catalog/painting/南購畫00002100000/display.jpg', N'/media/catalog/painting/南購畫00002100000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/36476?dep=P', N'CC-BY-4.0', N'東海道十一 五十三次 箱根 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('00a592af-93f6-bd13-91ba-fdf94e04272b', N'中漆000045N000000000', N'剔紅花卉五瓣式花盆', '4cf4b18a-96d6-5bd9-0b5e-46890a39f8f8', '57b870a3-e96c-6914-4510-51b5753b8f06', N'清', NULL, N'木胎，外髹朱漆，內塗黑漆。花盆，作五瓣花形，撇口，五足亦微外撇。外壁有五個方形開光，開光內以菱格形回紋為地，雕飾牡丹花紋；開光外其餘部分滿飾番蓮花紋。全器以剔紅技法完成。', N'通高 13.4 公分、深 11.3 公分、口徑 23.4 公分、足徑 14.7 公分', N'/media/catalog/lacquer/中漆000045N000000000/display.jpg', N'/media/catalog/lacquer/中漆000045N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/17454?dep=U', N'CC-BY-4.0', N'剔紅花卉五瓣式花盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('a96b8213-a8f1-8880-262b-fe4bcece1081', N'中銅000060N000000000', N'曾姬壺', '35ce74f7-c31a-3a07-0cbd-91f42656d869', '5d31b868-259b-75b6-d3a1-f55ae47915c8', N'戰國早期', NULL, N'體呈橢方形，微侈口，長頸、垂腹、方圈足，頸部有一對顧龍形耳。蓋呈盝頂形，上有四個S形鈕。頸部飾仰葉紋及兩條蟠虺紋飾帶，腹部以十字形凸帶分成八個區間，上部四個區間填飾蟠虺紋，下部四個區間素地無紋。兩壺器口內壁鑄有相同銘文五行三十九字：「隹（唯）王廿又六年，聖𧻚之夫人曾姬無卹，（吾）安茲漾陵，蒿間之無匹馬，甬（用）乍（作）宗彝尊壺，後嗣甬（用）之，（職）才（在）王室。」 銘文記述楚宣王二十六年（西元前344），楚聲王的夫人曾姬無卹為自己在漾陵蒿間選擇葬地。《史記•楚世家》記載楚聲王即位六年為盜所殺，是曾姬無卹早年喪偶，晚年自知不能與楚聲王合葬，因此製壺為銘記錄獨葬之處，其用意是希望楚王室不要忘了祭祀她。壺銘字體屬於典型的戰國楚系文字，銘文內容具有史料價值。與中銅393為一對，相傳為民國二十一年（1932）出自安徽壽縣朱家集李三孤堆楚幽王墓，後為劉體智先生所藏，終為本院重器。', N'器高 67.3 公分、通高 78.0 公分、腹深 57.5 公分、口徑長 20.8 公分、寬 18.8 公分', N'/media/catalog/bronze/中銅000060N000000000/display.jpg', N'/media/catalog/bronze/中銅000060N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/47509?dep=U', N'CC-BY-4.0', N'曾姬壺 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('b4a9e55d-1065-ea80-5111-ff5532124d06', N'故玉000009N000000000', N'龍紋玉環', 'c7e58cc2-4a5c-9a45-828b-57650534e3bf', '47c4962a-a731-0787-3ea9-4aaf1cc59e07', N'東漢', NULL, N'玉質，全器以龍為造型，首尾相連，連成圓環形。此器為東漢時期和帶鉤成組的腰帶扣件。', N'直徑 2.6 公分、厚 0.4 公分', N'/media/catalog/jade/故玉000009N000000000/display.jpg', N'/media/catalog/jade/故玉000009N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/48207?dep=U', N'CC-BY-4.0', N'龍紋玉環 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1),
    ('4f6a2bd9-7563-e996-8b3b-ff64edaf2ebb', N'故琺000818N000000000', N'掐絲琺瑯夔龍紋尊', '824b8d54-541c-1b21-e56c-a5d807800f18', '3a237183-839a-f3b2-be8c-b1aa2c1a24a3', N'明', NULL, N'銅胎，侈口，豐肩，鼓腹，外撇圈足渣斗式尊。除了肩與上腹的內壁露胎外，全器內外均藍地並掐絲紋飾，侈口內飾轉枝番蓮紋，外飾佛教八寶及轉枝番蓮紋，尊內頸部飾一圈縱走平行菊瓣紋、下腹及底為繡球紋；器外頸肩處、腹下方和圈足處，飾仰俯蓮瓣紋，腹面雲紋錦飾夔龍吐蓮紋二，圈足內裝飾轉枝五瓣花葉，底飾番蓮一朵。從掐絲末端捲曲的處理，以及夔龍、蓮瓣的形制與透明釉色等理由，斷定其是十六世前期的文物。', N'高 10.9 公分、口徑 11.8 公分', N'/media/catalog/enamel/故琺000818N000000000/display.jpg', N'/media/catalog/enamel/故琺000818N000000000/thumbnail.jpg', N'https://digitalarchive.npm.gov.tw/Collection/Detail/1525?dep=U', N'CC-BY-4.0', N'掐絲琺瑯夔龍紋尊 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw', 1);
GO
